insert into public.app_item_versions (item_id, language, audience, style, headline, body) values
  ('cbe62d26-429f-5224-896a-c2a796e1d54f', 'he', 'general', 'calm', 'מאות מתנדבים ניקו בחופי חיפה', 'משפחות, תנועות נוער ועובדים של עסקים מקומיים אספו שקיות רבות של פסולת, בעיקר פלסטיק קטן. החופים נקיים יותר לקראת החג.'),
  ('cbe62d26-429f-5224-896a-c2a796e1d54f', 'he', 'general', 'human', '"הילדים שלי מצאו יותר פקקים מצדפים"', 'כך סיפר אב שהגיע עם משפחתו לניקוי בחופי חיפה. מאות מתנדבים השתתפו, והחופים נקיים יותר לקראת החג.'),
  ('cbe62d26-429f-5224-896a-c2a796e1d54f', 'he', 'general', 'informative', 'מבצע ניקוי בחופי חיפה: מאות מתנדבים', 'המבצע אורגן בידי עמותות סביבה ורשויות מקומיות. רוב הפסולת שנאספה הייתה פלסטיק חד־פעמי. המבצע הבא בחורף.'),
  ('cbe62d26-429f-5224-896a-c2a796e1d54f', 'he', 'general', 'light', 'החול הזהב חזר', 'מאות מתנדבים ניקו בחופי חיפה. הפסולת הלכה, השקיעה נשארה.'),
  ('cc03dfdf-200a-5235-ab1e-8ede2e7b9400', 'he', 'general', 'calm', 'תרומת כליה חיברה בין שתי משפחות', 'אישה תרמה כליה לאדם שלא הכירה. חודשים אחרי הניתוח שניהם בריאים, והמשפחות נפגשו לארוחה משותפת.'),
  ('cc03dfdf-200a-5235-ab1e-8ede2e7b9400', 'he', 'general', 'human', '"עכשיו יש לי אחות"', 'כך אמר אב לשלושה על האישה שתרמה לו כליה, בלי שהכירו קודם. שנה אחרי הניתוח המשפחות חוגגות יחד את החגים.'),
  ('cc03dfdf-200a-5235-ab1e-8ede2e7b9400', 'he', 'general', 'informative', 'תרומת כליה אלטרואיסטית: התורמת והנתרם נפגשו', 'התרומה בוצעה לפני כמה חודשים. שניהם התאוששו היטב. לפי העמותה המלווה, מספר התורמים האלטרואיסטיים עולה בהתמדה.'),
  ('cc03dfdf-200a-5235-ab1e-8ede2e7b9400', 'he', 'general', 'light', 'תרומת כליה חיברה בין שתי משפחות', 'אישה תרמה כליה לאדם שלא הכירה. חודשים אחרי הניתוח שניהם בריאים, והמשפחות כבר חוגגות יחד.'),
  ('10f68d8b-1c63-5452-a61b-c55cf5675528', 'he', 'general', 'calm', 'שכנים ארגנו ארוחות למשפחה אחרי לידה', 'בבניין אחד בשכונה נבנה לוח תורנויות, וכל ערב מביא שכן אחר ארוחה חמה להורים הטריים.'),
  ('10f68d8b-1c63-5452-a61b-c55cf5675528', 'he', 'general', 'human', '"לא בישלנו שבועיים, ולא היינו רעבים לרגע"', 'כך מספרים הורים לתינוקת בת שבועיים, ששכניהם ארגנו לוח תורנויות לארוחות. "הבניין הפך למשפחה", הם אומרים.'),
  ('10f68d8b-1c63-5452-a61b-c55cf5675528', 'he', 'general', 'informative', 'ועד בית ארגן תורנות ארוחות למשפחה אחרי לידה', 'השכנים חילקו ביניהם את ימי השבוע דרך קבוצה משותפת. היוזמה הועתקה מאז לשני בניינים נוספים ברחוב.'),
  ('10f68d8b-1c63-5452-a61b-c55cf5675528', 'he', 'general', 'light', 'הבניין הכי טעים ברחוב', 'שכנים בנו לוח תורנויות, וכל ערב מגיע מגש חם להורים הטריים. התינוקת כבר יודעת: כאן גרים טוב.'),
  ('42c27409-f0e5-5e27-b59a-0429a17451f6', 'he', 'general', 'calm', 'ילדי גן שתלו גינת ירק והזמינו את השכונה', 'במשך חודשים טיפלו הילדים בעגבניות, בחסה ובנענע. השבוע הזמינו את השכנים לקטיף משותף.'),
  ('42c27409-f0e5-5e27-b59a-0429a17451f6', 'he', 'general', 'human', '"הילד שלי לא אכל ירקות, עד שגידל אותם בעצמו"', 'כך מספרת אם לילד בגן שבו שתלו הילדים גינת ירק. השבוע הוזמנה כל השכונה לקטיף.'),
  ('42c27409-f0e5-5e27-b59a-0429a17451f6', 'he', 'general', 'informative', 'גינת ירק של גן ילדים נפתחה לשכונה', 'הגינה הוקמה בעזרת הורים ומתנדבים. היבול חולק לשכנים ולבית תמחוי סמוך.'),
  ('42c27409-f0e5-5e27-b59a-0429a17451f6', 'he', 'general', 'light', 'החקלאים הכי קטנים בעיר', 'ילדי גן גידלו עגבניות, חסה ונענע, והזמינו את השכונה לקטיף. הנענע, כך נראה, הצליחה במיוחד.'),
  ('b767da66-b7b7-5038-bdc3-6817e3b99baf', 'he', 'general', 'calm', 'תלמידים מצאו ארנק עם כסף והחזירו אותו', 'שני תלמידי כיתה ו׳ ברמת גן מצאו ארנק ובו כמה מאות שקלים ומסמכים, ומסרו אותו לתחנת המשטרה.'),
  ('b767da66-b7b7-5038-bdc3-6817e3b99baf', 'he', 'general', 'human', '"היא בכתה מרוב שמחה, ואנחנו התביישנו"', 'כך סיפרו שני תלמידי כיתה ו׳ ברמת גן שמצאו ארנק והחזירו אותו לבעלים. היא הזמינה את כל הכיתה לעוגה.'),
  ('b767da66-b7b7-5038-bdc3-6817e3b99baf', 'he', 'general', 'informative', 'רמת גן: תלמידים החזירו ארנק שמצאו', 'שני תלמידי כיתה ו׳ מצאו ארנק עם כסף ומסמכים ומסרו אותו למשטרה. הבעלים איתרה אותם דרך בית הספר כדי להודות.'),
  ('b767da66-b7b7-5038-bdc3-6817e3b99baf', 'he', 'general', 'light', 'ביושר, ועם עוגה', 'שני תלמידים ברמת גן מצאו ארנק והחזירו אותו. בתמורה קיבלה הכיתה כולה עוגת שוקולד.'),
  ('2c3b4f01-dafc-51e1-89a3-74971fac2bd5', 'he', 'general', 'calm', 'בגיל 84 סיים תואר ראשון בהיסטוריה', 'אחרי קריירה ארוכה כמהנדס, חזר לספסל הלימודים וסיים את התואר בהצטיינות. הוא כבר נרשם לקורס הבא.'),
  ('2c3b4f01-dafc-51e1-89a3-74971fac2bd5', 'he', 'general', 'human', '"הנכדים עזרו לי עם המחשב, אני עזרתי להם עם ההיסטוריה"', 'בגיל 84 סיים מהנדס בדימוס תואר ראשון בהיסטוריה, בהצטיינות. בטקס ישבה כל המשפחה בשורה הראשונה.'),
  ('2c3b4f01-dafc-51e1-89a3-74971fac2bd5', 'he', 'general', 'informative', 'בוגר בן 84: תואר ראשון בהיסטוריה בהצטיינות', 'הבוגר, מהנדס בדימוס, למד שלוש שנים לצד סטודנטים צעירים. עבודת הסיום שלו עסקה בתולדות היישוב בשכונה שבה גדל.'),
  ('2c3b4f01-dafc-51e1-89a3-74971fac2bd5', 'he', 'general', 'light', 'אף פעם לא מאוחר מדי לסמינריון', 'בגיל 84 סיים מהנדס בדימוס תואר בהיסטוריה, בהצטיינות. הצעד הבא: קורס בערבית, וגם בישול.'),
  ('529dc2d9-cd72-56e5-9d37-0edad3a0310c', 'he', 'general', 'calm', 'ספרייה ברחוב: כל אחד לוקח ומחזיר', 'תלמידי בית ספר בנתניה בנו ארון ספרים בפינת רחוב. בתוך חודש התחלפו בו מאות ספרים.'),
  ('529dc2d9-cd72-56e5-9d37-0edad3a0310c', 'he', 'general', 'human', '"ראיתי סבא וילד בוחרים ספר ביחד"', 'כך מספרת מורה בנתניה, שתלמידיה בנו ספרייה קטנה בפינת רחוב. כל אחד לוקח ספר ומחזיר אחר.'),
  ('529dc2d9-cd72-56e5-9d37-0edad3a0310c', 'he', 'general', 'informative', 'נתניה: תלמידים הקימו ספריית רחוב', 'הארון נבנה בשיעורי נגרות, והספרים נתרמו על ידי תושבים. בחודש הראשון התחלפו בו מאות ספרים.'),
  ('529dc2d9-cd72-56e5-9d37-0edad3a0310c', 'he', 'general', 'light', 'הספרייה הכי קטנה בעיר', 'תלמידים בנתניה בנו ארון ספרים בפינת רחוב. בלי כרטיס קורא, בלי קנסות, רק לקחת ולהחזיר.'),
  ('150761d4-7b24-500a-b99b-4813c69db0bf', 'he', 'general', 'calm', 'ספרייה ברחוב: כל אחד לוקח ומחזיר', 'תלמידי בית ספר בבאר שבע בנו ארון ספרים בפינת רחוב. בתוך חודש התחלפו בו מאות ספרים.'),
  ('150761d4-7b24-500a-b99b-4813c69db0bf', 'he', 'general', 'human', '"ראיתי סבא וילד בוחרים ספר ביחד"', 'כך מספרת מורה בבאר שבע, שתלמידיה בנו ספרייה קטנה בפינת רחוב. כל אחד לוקח ספר ומחזיר אחר.'),
  ('150761d4-7b24-500a-b99b-4813c69db0bf', 'he', 'general', 'informative', 'באר שבע: תלמידים הקימו ספריית רחוב', 'הארון נבנה בשיעורי נגרות, והספרים נתרמו על ידי תושבים. בחודש הראשון התחלפו בו מאות ספרים.'),
  ('150761d4-7b24-500a-b99b-4813c69db0bf', 'he', 'general', 'light', 'הספרייה הכי קטנה בעיר', 'תלמידים בבאר שבע בנו ארון ספרים בפינת רחוב. בלי כרטיס קורא, בלי קנסות, רק לקחת ולהחזיר.'),
  ('150761d4-7b24-500a-b99b-4813c69db0bf', 'en', 'general', 'informative', 'Beersheba: pupils set up a street library', 'The bookcase was built in woodwork classes and filled with books donated by residents. Hundreds of books changed hands in its first month.'),
  ('150761d4-7b24-500a-b99b-4813c69db0bf', 'en', 'general', 'calm', 'A little street library in Beersheba', 'Schoolchildren built a bookcase on a street corner: anyone can take a book and leave another.'),
  ('150761d4-7b24-500a-b99b-4813c69db0bf', 'fr', 'general', 'informative', 'Beer-Sheva : des élèves créent une bibliothèque de rue', 'L’étagère a été construite en cours de menuiserie et remplie de livres offerts par les habitants. Des centaines de livres ont circulé le premier mois.'),
  ('150761d4-7b24-500a-b99b-4813c69db0bf', 'fr', 'general', 'calm', 'Une petite bibliothèque de rue à Beer-Sheva', 'Des écoliers ont construit une étagère au coin d’une rue : chacun prend un livre et en laisse un autre.'),
  ('150761d4-7b24-500a-b99b-4813c69db0bf', 'he', 'youth', 'light', 'בנו ספרייה בפינת הרחוב', 'תלמידים בבאר שבע בנו ארון ספרים ברחוב. כל אחד יכול לקחת ספר ולהשאיר אחר.'),
  ('150761d4-7b24-500a-b99b-4813c69db0bf', 'he', 'youth', 'calm', 'ספריית רחוב', 'תלמידים בבאר שבע בנו ארון ספרים בפינת רחוב, וכל אחד יכול לקחת ספר.'),
  ('09397659-2751-5ee4-a46d-5d7b87254241', 'he', 'general', 'calm', 'תלמידים מצאו ארנק עם כסף והחזירו אותו', 'שני תלמידי כיתה ו׳ בחולון מצאו ארנק ובו כמה מאות שקלים ומסמכים, ומסרו אותו לתחנת המשטרה.'),
  ('09397659-2751-5ee4-a46d-5d7b87254241', 'he', 'general', 'human', '"היא בכתה מרוב שמחה, ואנחנו התביישנו"', 'כך סיפרו שני תלמידי כיתה ו׳ בחולון שמצאו ארנק והחזירו אותו לבעלים. היא הזמינה את כל הכיתה לעוגה.'),
  ('09397659-2751-5ee4-a46d-5d7b87254241', 'he', 'general', 'informative', 'חולון: תלמידים החזירו ארנק שמצאו', 'שני תלמידי כיתה ו׳ מצאו ארנק עם כסף ומסמכים ומסרו אותו למשטרה. הבעלים איתרה אותם דרך בית הספר כדי להודות.'),
  ('09397659-2751-5ee4-a46d-5d7b87254241', 'he', 'general', 'light', 'ביושר, ועם עוגה', 'שני תלמידים בחולון מצאו ארנק והחזירו אותו. בתמורה קיבלה הכיתה כולה עוגת שוקולד.'),
  ('09397659-2751-5ee4-a46d-5d7b87254241', 'en', 'general', 'informative', 'Holon: pupils return a lost wallet', 'Two sixth-graders found a wallet with cash and documents and handed it in to the police. The owner tracked them down through their school to thank them.'),
  ('09397659-2751-5ee4-a46d-5d7b87254241', 'en', 'general', 'calm', 'Two children return a wallet they found', 'In Holon, two sixth-grade pupils found a wallet with a few hundred shekels and returned it to its owner.'),
  ('09397659-2751-5ee4-a46d-5d7b87254241', 'fr', 'general', 'informative', 'Holon : deux élèves rapportent un portefeuille perdu', 'Deux élèves de CM2 ont trouvé un portefeuille avec de l’argent et des papiers et l’ont remis à la police. La propriétaire les a retrouvés via leur école pour les remercier.'),
  ('09397659-2751-5ee4-a46d-5d7b87254241', 'fr', 'general', 'calm', 'Deux enfants rendent un portefeuille', 'À Holon, deux élèves ont trouvé un portefeuille contenant quelques centaines de shekels et l’ont rendu à sa propriétaire.'),
  ('09397659-2751-5ee4-a46d-5d7b87254241', 'he', 'youth', 'light', 'ילדים ישרים, עוגה מתוקה', 'שני תלמידי כיתה ו׳ בחולון מצאו ארנק והחזירו אותו. הבעלים הזמינה את כל הכיתה לעוגה.'),
  ('09397659-2751-5ee4-a46d-5d7b87254241', 'he', 'youth', 'calm', 'תלמידים החזירו ארנק', 'שני תלמידים בחולון מצאו ארנק עם כסף והחזירו אותו לבעלים.'),
  ('c0911afd-85b6-5f6c-9490-e7532ce2ecb1', 'he', 'general', 'calm', 'מאות מתנדבים ניקו בחופי אשקלון ואשדוד', 'משפחות, תנועות נוער ועובדים של עסקים מקומיים אספו שקיות רבות של פסולת, בעיקר פלסטיק קטן. החופים נקיים יותר לקראת החג.'),
  ('c0911afd-85b6-5f6c-9490-e7532ce2ecb1', 'he', 'general', 'human', '"הילדים שלי מצאו יותר פקקים מצדפים"', 'כך סיפר אב שהגיע עם משפחתו לניקוי בחופי אשקלון ואשדוד. מאות מתנדבים השתתפו, והחופים נקיים יותר לקראת החג.'),
  ('c0911afd-85b6-5f6c-9490-e7532ce2ecb1', 'he', 'general', 'informative', 'מבצע ניקוי בחופי אשקלון ואשדוד: מאות מתנדבים', 'המבצע אורגן בידי עמותות סביבה ורשויות מקומיות. רוב הפסולת שנאספה הייתה פלסטיק חד־פעמי. המבצע הבא בחורף.'),
  ('c0911afd-85b6-5f6c-9490-e7532ce2ecb1', 'he', 'general', 'light', 'החול הזהב חזר', 'מאות מתנדבים ניקו בחופי אשקלון ואשדוד. הפסולת הלכה, השקיעה נשארה.'),
  ('c0911afd-85b6-5f6c-9490-e7532ce2ecb1', 'en', 'general', 'informative', 'Beach clean-up on the beaches of Ashkelon and Ashdod: hundreds of volunteers', 'Environmental groups and local authorities organised the clean-up; most of the waste collected was single-use plastic. The next one is planned for winter.'),
  ('c0911afd-85b6-5f6c-9490-e7532ce2ecb1', 'en', 'general', 'calm', 'Volunteers clean the beaches', 'Families, youth movements and local businesses cleaned up on the beaches of Ashkelon and Ashdod, leaving the shore cleaner ahead of the holiday.'),
  ('c0911afd-85b6-5f6c-9490-e7532ce2ecb1', 'fr', 'general', 'informative', 'Nettoyage sur les plages d’Ashkelon et d’Ashdod : des centaines de bénévoles', 'Associations environnementales et municipalités ont organisé l’opération ; l’essentiel des déchets était du plastique jetable. La prochaine est prévue cet hiver.'),
  ('c0911afd-85b6-5f6c-9490-e7532ce2ecb1', 'fr', 'general', 'calm', 'Des bénévoles nettoient les plages', 'Familles, mouvements de jeunesse et commerces ont nettoyé sur les plages d’Ashkelon et d’Ashdod : le rivage est plus propre avant la fête.'),
  ('c0911afd-85b6-5f6c-9490-e7532ce2ecb1', 'he', 'youth', 'light', 'ניקוי חופים: הפסולת הלכה, השקיעה נשארה', 'מאות מתנדבים, הרבה מהם בני נוער, ניקו בחופי אשקלון ואשדוד. רוב מה שמצאו היה פלסטיק קטן.'),
  ('c0911afd-85b6-5f6c-9490-e7532ce2ecb1', 'he', 'youth', 'calm', 'מתנדבים ניקו את החוף', 'מאות מתנדבים ניקו בחופי אשקלון ואשדוד, והחופים נקיים יותר לקראת החג.'),
  ('95bdb75c-504b-55a6-9619-62f58c16c327', 'he', 'general', 'calm', 'מתנדבים בנו 40 סוכות לקשישים בירושלים', 'בני נוער ופנסיונרים עברו בין הבתים עם קרשים וסכך, ובנו סוכות למי שלא יכול לבנות לבד.'),
  ('95bdb75c-504b-55a6-9619-62f58c16c327', 'he', 'general', 'human', '"לא הייתה לי סוכה כבר חמש שנים"', 'כך אמרה אישה בת 88 בירושלים, אחרי שמתנדבים בנו לה סוכה. בסך הכל הוקמו 40 סוכות לקשישים בעיר.'),
  ('95bdb75c-504b-55a6-9619-62f58c16c327', 'he', 'general', 'informative', 'ירושלים: 40 סוכות נבנו לקשישים בידי מתנדבים', 'המיזם הקהילתי חיבר בני נוער, פנסיונרים ובעלי מקצוע. החומרים נתרמו מעסקים מקומיים.'),
  ('95bdb75c-504b-55a6-9619-62f58c16c327', 'he', 'general', 'light', 'סכך, פטיש ולב גדול', 'מתנדבים בירושלים בנו 40 סוכות לקשישים, כולל קישוטים. אחת מהן, מספרים, מפוארת יותר מכל הסוכות ברחוב.'),
  ('95bdb75c-504b-55a6-9619-62f58c16c327', 'en', 'general', 'informative', 'Jerusalem: volunteers build 40 sukkahs for older residents', 'Teenagers, retirees and tradespeople built the festival huts for people who cannot put them up themselves. Local businesses donated the materials.'),
  ('95bdb75c-504b-55a6-9619-62f58c16c327', 'en', 'general', 'calm', 'Volunteers build sukkahs for the elderly', 'In Jerusalem, volunteers of all ages built 40 sukkahs for older residents, so they can celebrate the holiday at home.'),
  ('95bdb75c-504b-55a6-9619-62f58c16c327', 'fr', 'general', 'informative', 'Jérusalem : des bénévoles montent 40 souccot pour des aînés', 'Adolescents, retraités et artisans ont construit les cabanes de la fête pour ceux qui ne peuvent pas le faire seuls. Les matériaux ont été offerts par des commerces locaux.'),
  ('95bdb75c-504b-55a6-9619-62f58c16c327', 'fr', 'general', 'calm', 'Des souccot construites pour les personnes âgées', 'À Jérusalem, des bénévoles de tous âges ont monté 40 souccot pour des aînés, afin qu’ils puissent fêter chez eux.'),
  ('95bdb75c-504b-55a6-9619-62f58c16c327', 'he', 'youth', 'light', 'בני נוער בנו סוכות לקשישים', 'בירושלים יצאו מתנדבים, רבים מהם בני נוער, ובנו 40 סוכות לקשישים. כולל שרשראות קישוט, כמובן.'),
  ('95bdb75c-504b-55a6-9619-62f58c16c327', 'he', 'youth', 'calm', 'סוכות במתנה', 'מתנדבים בירושלים בנו 40 סוכות לקשישים שלא יכולים לבנות לבד.'),
  ('46376d79-eca9-5552-8a6d-c0f4fd7799ce', 'he', 'general', 'calm', 'העגורים הראשונים הגיעו לעמק החולה', 'להקות ראשונות של עגורים נחתו בעמק בדרכן דרומה. בשבועות הקרובים יגיעו עשרות אלפים, ואפשר לצפות בהם בשעות הבוקר.'),
  ('46376d79-eca9-5552-8a6d-c0f4fd7799ce', 'he', 'general', 'human', 'צפרית: "כל שנה זה מרגש כמו בפעם הראשונה"', 'להקות העגורים הראשונות של הסתיו נחתו בעמק החולה. "שומעים אותם לפני שרואים", היא מספרת.'),
  ('46376d79-eca9-5552-8a6d-c0f4fd7799ce', 'he', 'general', 'informative', 'עונת הנדידה: להקות עגורים ראשונות בעמק החולה', 'העגורים עוצרים בעמק בדרכם מאירופה לאפריקה. השיא צפוי בעוד כמה שבועות. הצפייה אפשרית מהשבילים ומהעגלות המודרכות.'),
  ('46376d79-eca9-5552-8a6d-c0f4fd7799ce', 'he', 'general', 'light', 'האורחים הקבועים חזרו', 'העגורים הראשונים נחתו בעמק החולה. הם באים מאירופה, בלי מזוודות, ותמיד בזמן.'),
  ('46376d79-eca9-5552-8a6d-c0f4fd7799ce', 'en', 'general', 'informative', 'Migration season: first cranes arrive in the Hula Valley', 'The cranes stop in the northern valley on their way from Europe to Africa. The peak is expected in a few weeks; visitors can watch from trails and guided wagons.'),
  ('46376d79-eca9-5552-8a6d-c0f4fd7799ce', 'en', 'general', 'calm', 'The first cranes have landed in the Hula Valley', 'The first flocks of the autumn have arrived. Tens of thousands more will follow over the coming weeks.'),
  ('46376d79-eca9-5552-8a6d-c0f4fd7799ce', 'fr', 'general', 'informative', 'Migration : les premières grues arrivent dans la vallée de la Houla', 'Les grues font halte dans cette vallée du Nord entre l’Europe et l’Afrique. Le pic est attendu dans quelques semaines ; on peut les observer depuis les sentiers.'),
  ('46376d79-eca9-5552-8a6d-c0f4fd7799ce', 'fr', 'general', 'calm', 'Les premières grues sont arrivées', 'Les premiers vols d’automne se sont posés dans la vallée de la Houla. Des dizaines de milliers suivront dans les semaines à venir.'),
  ('46376d79-eca9-5552-8a6d-c0f4fd7799ce', 'he', 'youth', 'light', 'העגורים חזרו לביקור', 'להקות העגורים הראשונות נחתו בעמק החולה, בדרך מאירופה לאפריקה. בעוד כמה שבועות יהיו שם עשרות אלפים.'),
  ('46376d79-eca9-5552-8a6d-c0f4fd7799ce', 'he', 'youth', 'calm', 'העגורים הגיעו', 'העגורים הראשונים של הסתיו נחתו בעמק החולה. אפשר לצפות בהם בבוקר.'),
  ('19f18b0b-b4c4-5304-8b08-2602d8f235f2', 'he', 'general', 'calm', 'ספרייה ברחוב: כל אחד לוקח ומחזיר', 'תלמידי בית ספר בכרמיאל בנו ארון ספרים בפינת רחוב. בתוך חודש התחלפו בו מאות ספרים.'),
  ('19f18b0b-b4c4-5304-8b08-2602d8f235f2', 'he', 'general', 'human', '"ראיתי סבא וילד בוחרים ספר ביחד"', 'כך מספרת מורה בכרמיאל, שתלמידיה בנו ספרייה קטנה בפינת רחוב. כל אחד לוקח ספר ומחזיר אחר.'),
  ('19f18b0b-b4c4-5304-8b08-2602d8f235f2', 'he', 'general', 'informative', 'כרמיאל: תלמידים הקימו ספריית רחוב', 'הארון נבנה בשיעורי נגרות, והספרים נתרמו על ידי תושבים. בחודש הראשון התחלפו בו מאות ספרים.'),
  ('19f18b0b-b4c4-5304-8b08-2602d8f235f2', 'he', 'general', 'light', 'הספרייה הכי קטנה בעיר', 'תלמידים בכרמיאל בנו ארון ספרים בפינת רחוב. בלי כרטיס קורא, בלי קנסות, רק לקחת ולהחזיר.'),
  ('19f18b0b-b4c4-5304-8b08-2602d8f235f2', 'en', 'general', 'informative', 'Karmiel: pupils set up a street library', 'The bookcase was built in woodwork classes and filled with books donated by residents. Hundreds of books changed hands in its first month.'),
  ('19f18b0b-b4c4-5304-8b08-2602d8f235f2', 'en', 'general', 'calm', 'A little street library in Karmiel', 'Schoolchildren built a bookcase on a street corner: anyone can take a book and leave another.'),
  ('19f18b0b-b4c4-5304-8b08-2602d8f235f2', 'fr', 'general', 'informative', 'Karmiel : des élèves créent une bibliothèque de rue', 'L’étagère a été construite en cours de menuiserie et remplie de livres offerts par les habitants. Des centaines de livres ont circulé le premier mois.'),
  ('19f18b0b-b4c4-5304-8b08-2602d8f235f2', 'fr', 'general', 'calm', 'Une petite bibliothèque de rue à Karmiel', 'Des écoliers ont construit une étagère au coin d’une rue : chacun prend un livre et en laisse un autre.'),
  ('19f18b0b-b4c4-5304-8b08-2602d8f235f2', 'he', 'youth', 'light', 'בנו ספרייה בפינת הרחוב', 'תלמידים בכרמיאל בנו ארון ספרים ברחוב. כל אחד יכול לקחת ספר ולהשאיר אחר.'),
  ('19f18b0b-b4c4-5304-8b08-2602d8f235f2', 'he', 'youth', 'calm', 'ספריית רחוב', 'תלמידים בכרמיאל בנו ארון ספרים בפינת רחוב, וכל אחד יכול לקחת ספר.'),
  ('c3827744-51c5-59a3-9d99-8f3441764b7d', 'he', 'general', 'calm', 'מאות מתנדבים ניקו בחופי הצפון', 'משפחות, תנועות נוער ועובדים של עסקים מקומיים אספו שקיות רבות של פסולת, בעיקר פלסטיק קטן. החופים נקיים יותר לקראת החג.'),
  ('c3827744-51c5-59a3-9d99-8f3441764b7d', 'he', 'general', 'human', '"הילדים שלי מצאו יותר פקקים מצדפים"', 'כך סיפר אב שהגיע עם משפחתו לניקוי בחופי הצפון. מאות מתנדבים השתתפו, והחופים נקיים יותר לקראת החג.'),
  ('c3827744-51c5-59a3-9d99-8f3441764b7d', 'he', 'general', 'informative', 'מבצע ניקוי בחופי הצפון: מאות מתנדבים', 'המבצע אורגן בידי עמותות סביבה ורשויות מקומיות. רוב הפסולת שנאספה הייתה פלסטיק חד־פעמי. המבצע הבא בחורף.'),
  ('c3827744-51c5-59a3-9d99-8f3441764b7d', 'he', 'general', 'light', 'החול הזהב חזר', 'מאות מתנדבים ניקו בחופי הצפון. הפסולת הלכה, השקיעה נשארה.'),
  ('c3827744-51c5-59a3-9d99-8f3441764b7d', 'en', 'general', 'informative', 'Beach clean-up on the northern beaches: hundreds of volunteers', 'Environmental groups and local authorities organised the clean-up; most of the waste collected was single-use plastic. The next one is planned for winter.'),
  ('c3827744-51c5-59a3-9d99-8f3441764b7d', 'en', 'general', 'calm', 'Volunteers clean the beaches', 'Families, youth movements and local businesses cleaned up on the northern beaches, leaving the shore cleaner ahead of the holiday.'),
  ('c3827744-51c5-59a3-9d99-8f3441764b7d', 'fr', 'general', 'informative', 'Nettoyage sur les plages du Nord : des centaines de bénévoles', 'Associations environnementales et municipalités ont organisé l’opération ; l’essentiel des déchets était du plastique jetable. La prochaine est prévue cet hiver.'),
  ('c3827744-51c5-59a3-9d99-8f3441764b7d', 'fr', 'general', 'calm', 'Des bénévoles nettoient les plages', 'Familles, mouvements de jeunesse et commerces ont nettoyé sur les plages du Nord : le rivage est plus propre avant la fête.'),
  ('c3827744-51c5-59a3-9d99-8f3441764b7d', 'he', 'youth', 'light', 'ניקוי חופים: הפסולת הלכה, השקיעה נשארה', 'מאות מתנדבים, הרבה מהם בני נוער, ניקו בחופי הצפון. רוב מה שמצאו היה פלסטיק קטן.'),
  ('c3827744-51c5-59a3-9d99-8f3441764b7d', 'he', 'youth', 'calm', 'מתנדבים ניקו את החוף', 'מאות מתנדבים ניקו בחופי הצפון, והחופים נקיים יותר לקראת החג.'),
  ('3d17b8f0-3d9b-507c-84ba-3cb08f4b4dae', 'he', 'general', 'calm', 'נבחרת הנוער בטניס עלתה לחצי הגמר באליפות אירופה', 'הנבחרת ניצחה אתמול בשני משחקים רצופים. המשחק הבא ישודר בערוצי הספורט, והשחקנים מספרים שהם ממוקדים ורגועים.'),
  ('3d17b8f0-3d9b-507c-84ba-3cb08f4b4dae', 'he', 'general', 'human', 'ההורים ביציע לא הפסיקו לשיר', 'נבחרת הנוער בטניס עלתה לחצי הגמר באליפות אירופה. "הם שיחקו בשביל החברים שלהם בבית", אמר המאמן אחרי הניצחון.'),
  ('3d17b8f0-3d9b-507c-84ba-3cb08f4b4dae', 'he', 'general', 'informative', 'נבחרת הנוער בטניס: עלייה לחצי הגמר באליפות אירופה', 'אחרי שני ניצחונות רצופים הבטיחה הנבחרת את מקומה לחצי הגמר. המשחק הבא בסוף השבוע ישודר בשידור חי.'),
  ('3d17b8f0-3d9b-507c-84ba-3cb08f4b4dae', 'he', 'general', 'light', 'הנוער שלנו בטניס ממשיך לטפס', 'עוד ניצחון, ועוד שלב: נבחרת הנוער בטניס עלתה לחצי הגמר באליפות אירופה. הדגלים כבר במרפסות.'),
  ('dc9308b8-4903-504b-8b7c-140e5664712c', 'he', 'general', 'calm', 'עבודות הרכבת הקלה בחיפה: שינויי תנועה ברחוב הרצל', 'במשך חודש יוצר נתיב אחד בכל כיוון ברחוב הרצל. קווי האוטובוס ממשיכים לפעול, עם תחנות זמניות מסומנות.'),
  ('dc9308b8-4903-504b-8b7c-140e5664712c', 'he', 'general', 'human', 'סוחרים ברחוב הרצל מקווים שהעבודות יסתיימו מהר', '"הלקוחות הקבועים מגיעים גם ברגל", מספר בעל חנות. עבודות הרכבת הקלה בחיפה יצמצמו את התנועה ברחוב הרצל במשך חודש.'),
  ('dc9308b8-4903-504b-8b7c-140e5664712c', 'he', 'general', 'informative', 'חיפה: צמצום נתיבים ברחוב הרצל ל־חודש', 'בשל עבודות הרכבת הקלה יפעל נתיב אחד בכל כיוון. תחנות אוטובוס יועתקו זמנית. מומלץ להשתמש בצירים חלופיים בשעות העומס.'),
  ('dc9308b8-4903-504b-8b7c-140e5664712c', 'he', 'general', 'light', 'רחוב הרצל על דיאטת נתיבים', 'במשך חודש ייסגר נתיב בכל כיוון בגלל עבודות הרכבת הקלה בחיפה. אופניים וקורקינטים, זה הזמן שלכם.'),
  ('f0bf10b7-dc23-59af-b493-efec1235b9ad', 'he', 'general', 'calm', 'אובך קל עד בינוני בדרום, היום', 'ריכוזי אבק גבוהים מהרגיל צפויים בדרום ובמרכז. לרוב האנשים אין צורך לשנות תוכניות; לרגישים מומלץ להפחית מאמץ בחוץ.'),
  ('f0bf10b7-dc23-59af-b493-efec1235b9ad', 'he', 'general', 'human', 'אמא לילד עם אסתמה: "היום נשחק בבית"', 'אובך קל עד בינוני צפוי בדרום, היום בדרום ובמרכז. המשרד להגנת הסביבה ממליץ לרגישים, לחולי לב ולילדים להפחית פעילות בחוץ.'),
  ('f0bf10b7-dc23-59af-b493-efec1235b9ad', 'he', 'general', 'informative', 'בדרום, היום: אובך בדרום ובמרכז, המלצה לרגישים', 'המשרד להגנת הסביבה צופה ריכוזי אבק גבוהים עד שעות הערב. חולי לב, ריאה, מבוגרים וילדים מתבקשים להימנע ממאמץ בחוץ.'),
  ('f0bf10b7-dc23-59af-b493-efec1235b9ad', 'he', 'general', 'light', 'השמיים קצת צהובים בדרום, היום', 'אובך קל עד בינוני בדרום ובמרכז. מי שרגיש, ישחק היום בבית; לכל השאר: לשטוף את הרכב אחר כך.'),
  ('acefd9f0-c734-5610-bdab-126da7297c65', 'he', 'general', 'calm', 'הפסקת חשמל יזומה ברעננה ביום רביעי בבוקר', 'חברת החשמל תבצע עבודות תחזוקה בכמה רחובות ברעננה בין 08:30–12:30. הלקוחות ברחובות האלה קיבלו הודעה, והזרם יחזור בסיום העבודות.'),
  ('acefd9f0-c734-5610-bdab-126da7297c65', 'he', 'general', 'human', 'עסקים קטנים ברעננה נערכים לבוקר בלי חשמל', '"נפתח שעתיים אחר כך, זה בסדר", אומרת בעלת בית קפה. חברת החשמל תבצע ביום רביעי עבודות תחזוקה בכמה רחובות בין 08:30–12:30.'),
  ('acefd9f0-c734-5610-bdab-126da7297c65', 'he', 'general', 'informative', 'רעננה: הפסקת חשמל מתוכננת ביום רביעי בין 08:30–12:30', 'העבודות נועדו לשדרג את רשת החשמל לקראת החורף. רשימת הרחובות באתר חברת החשמל. מומלץ לנתק מכשירים רגישים לפני ההפסקה.'),
  ('acefd9f0-c734-5610-bdab-126da7297c65', 'he', 'general', 'light', 'ביום רביעי בבוקר: קפה בחוץ, תושבי רעננה', 'חברת החשמל משדרגת את הרשת בכמה רחובות בין 08:30–12:30. מנתקים מחשבים רגישים, ובצהריים הכל דולק שוב.'),
  ('7b235498-cb59-5a9a-9999-67835c556324', 'he', 'general', 'calm', 'מחקר: 30 דקות הליכה ביום עושות הבדל', 'חוקרים שעקבו אחר אלפי משתתפים מצאו שהליכה קלה של 30 דקות ביום קשורה לשינה טובה יותר ולמצב רוח יציב. לא צריך ציוד, רק לצאת מהבית.'),
  ('7b235498-cb59-5a9a-9999-67835c556324', 'he', 'general', 'human', '"התחלתי ללכת עם השכנה, ועכשיו אני ישנה טוב יותר"', 'מחקר חדש מאשר את מה שהרבה הולכי ערב מרגישים: 30 דקות הליכה ביום קשורות לשינה טובה ולמצב רוח יציב יותר.'),
  ('7b235498-cb59-5a9a-9999-67835c556324', 'he', 'general', 'informative', 'מחקר: 30 דקות הליכה ביום משפרות שינה', 'במחקר שעקב אחר אלפי מבוגרים במשך שנה, הליכה יומית של 30 דקות נקשרה לשיפור באיכות השינה ולירידה בדיווחים על מתח. הממצאים פורסמו בכתב עת רפואי.'),
  ('7b235498-cb59-5a9a-9999-67835c556324', 'he', 'general', 'light', 'הנעליים כבר ליד הדלת', 'מחקר חדש מצא ש־30 דקות הליכה ביום עוזרות לישון טוב יותר. סיבוב סביב הבלוק נחשב, גם עם עצירה לגלידה.'),
  ('a24d6e27-2c6b-5dd6-8456-85cbb052602b', 'he', 'general', 'calm', 'ערב קהילתי ברחוב עמק רפאים: הופעה וסדנאות לילדים', 'המתנ״ס מזמין את התושבים לערב פתוח עם מוזיקה, דוכני יצירה ופינת קפה. הכניסה חופשית.'),
  ('a24d6e27-2c6b-5dd6-8456-85cbb052602b', 'he', 'general', 'informative', 'רחוב עמק רפאים: ערב קהילתי פתוח ביום חמישי ב־18:00', 'בתוכנית: הופעה של להקה מקומית, סדנאות יצירה לילדים ודוכנים של עסקים מהשכונה. כניסה חופשית, ללא הרשמה.'),
  ('5442d62a-07a2-5d24-850f-d63caac29cf2', 'he', 'general', 'calm', 'עבודות הרכבת הקלה בירושלים: שינויי תנועה ברחוב הרצל', 'במשך שבועיים יוצר נתיב אחד בכל כיוון ברחוב הרצל. קווי האוטובוס ממשיכים לפעול, עם תחנות זמניות מסומנות.'),
  ('5442d62a-07a2-5d24-850f-d63caac29cf2', 'he', 'general', 'human', 'סוחרים ברחוב הרצל מקווים שהעבודות יסתיימו מהר', '"הלקוחות הקבועים מגיעים גם ברגל", מספר בעל חנות. עבודות הרכבת הקלה בירושלים יצמצמו את התנועה ברחוב הרצל במשך שבועיים.'),
  ('5442d62a-07a2-5d24-850f-d63caac29cf2', 'he', 'general', 'informative', 'ירושלים: צמצום נתיבים ברחוב הרצל ל־שבועיים', 'בשל עבודות הרכבת הקלה יפעל נתיב אחד בכל כיוון. תחנות אוטובוס יועתקו זמנית. מומלץ להשתמש בצירים חלופיים בשעות העומס.'),
  ('5442d62a-07a2-5d24-850f-d63caac29cf2', 'he', 'general', 'light', 'רחוב הרצל על דיאטת נתיבים', 'במשך שבועיים ייסגר נתיב בכל כיוון בגלל עבודות הרכבת הקלה בירושלים. אופניים וקורקינטים, זה הזמן שלכם.'),
  ('b3747ef0-73ae-5802-ab0e-8488dc509b29', 'he', 'general', 'calm', 'בית משפט: משכיר חייב להחזיר פיקדון בזמן', 'בפסק דין שעסק בסכסוך שכירות נקבע כי יש להחזיר את הפיקדון בתוך זמן סביר מסיום החוזה, אלא אם הוכח נזק.'),
  ('b3747ef0-73ae-5802-ab0e-8488dc509b29', 'he', 'general', 'human', 'שוכר שחיכה חודשים לפיקדון קיבל את כספו', '"לא ויתרתי, והתברר שהחוק לצידי", הוא מספר. בית המשפט קבע כי יש להחזיר פיקדון בזמן סביר, אלא אם הוכח נזק לדירה.'),
  ('b3747ef0-73ae-5802-ab0e-8488dc509b29', 'he', 'general', 'informative', 'פסק דין: פיקדון שכירות יוחזר תוך זמן סביר', 'בית משפט השלום קבע כי משכיר אינו יכול לעכב פיקדון בלי להציג נזק מוכח. השוכר יקבל את הסכום בתוספת הוצאות משפט.'),
  ('b3747ef0-73ae-5802-ab0e-8488dc509b29', 'he', 'general', 'light', 'הפיקדון שלכם, לא של המשכיר', 'בית משפט קבע: בסוף החוזה מחזירים את הפיקדון בזמן, אלא אם יש נזק מוכח. שמרו תמונות מהיום הראשון.'),
  ('7b9dba2e-56eb-5ad9-b27d-1b5b51308724', 'he', 'general', 'calm', 'אובך קל עד בינוני מחר', 'ריכוזי אבק גבוהים מהרגיל צפויים בדרום ובמרכז. לרוב האנשים אין צורך לשנות תוכניות; לרגישים מומלץ להפחית מאמץ בחוץ.'),
  ('7b9dba2e-56eb-5ad9-b27d-1b5b51308724', 'he', 'general', 'human', 'אמא לילד עם אסתמה: "היום נשחק בבית"', 'אובך קל עד בינוני צפוי מחר בדרום ובמרכז. המשרד להגנת הסביבה ממליץ לרגישים, לחולי לב ולילדים להפחית פעילות בחוץ.'),
  ('7b9dba2e-56eb-5ad9-b27d-1b5b51308724', 'he', 'general', 'informative', 'מחר: אובך בדרום ובמרכז, המלצה לרגישים', 'המשרד להגנת הסביבה צופה ריכוזי אבק גבוהים עד שעות הערב. חולי לב, ריאה, מבוגרים וילדים מתבקשים להימנע ממאמץ בחוץ.'),
  ('7b9dba2e-56eb-5ad9-b27d-1b5b51308724', 'he', 'general', 'light', 'השמיים קצת צהובים מחר', 'אובך קל עד בינוני בדרום ובמרכז. מי שרגיש, ישחק היום בבית; לכל השאר: לשטוף את הרכב אחר כך.'),
  ('e64b019b-375b-5ad5-9e10-6c49c9a1d133', 'he', 'general', 'calm', 'עבודות מתוכננות: הפסקת מים לילית בחולון', 'בשכונות אחדות בחולון לא יהיו מים הלילה בין 23:00–05:00, בשל החלפת צנרת. בבוקר האספקה תחזור כרגיל.'),
  ('e64b019b-375b-5ad5-9e10-6c49c9a1d133', 'he', 'general', 'human', 'תושבי חולון ממלאים קומקום לפני השינה', '"שמתי בקבוק ליד המיטה ומילאתי קומקום לקפה של הבוקר", מספר תושב. בשכונות אחדות לא יהיו מים הלילה בין 23:00–05:00.'),
  ('e64b019b-375b-5ad5-9e10-6c49c9a1d133', 'he', 'general', 'informative', 'חולון: הפסקת מים מתוכננת בין 23:00–05:00', 'תאגיד המים מחליף צנרת ראשית. ההפסקה הלילה תחול על כמה שכונות, והרשימה המלאה באתר התאגיד. אחרי החידוש ייתכן צבע עכור במים לכמה דקות.'),
  ('e64b019b-375b-5ad5-9e10-6c49c9a1d133', 'he', 'general', 'light', 'מקלחת מוקדמת הערב, תושבי חולון', 'בשכונות אחדות לא יהיו מים הלילה בין 23:00–05:00, כי מחליפים צנרת. ממלאים קומקום, והבוקר הכל זורם.'),
  ('899182ec-7a38-5fd0-ba3b-e18142a48954', 'he', 'general', 'calm', 'פיקוד העורף מזכיר: לבדוק את המרחב המוגן לפני החורף', 'כדאי לוודא שהחלון והדלת נסגרים היטב ושיש בממ״ד מים ופנס. בדיקה של עשר דקות מספיקה.'),
  ('899182ec-7a38-5fd0-ba3b-e18142a48954', 'he', 'general', 'human', 'ועד בית בחיפה סידר את המקלט המשותף', '"פינינו ארגזים, הבאנו כיסאות ומים", מספרת חברת ועד. פיקוד העורף ממליץ לבדוק את המרחב המוגן לפני החורף.'),
  ('899182ec-7a38-5fd0-ba3b-e18142a48954', 'he', 'general', 'informative', 'פיקוד העורף: בדיקת מרחב מוגן לפני החורף', 'ההמלצה: לבדוק את אטימות החלון והדלת, לפנות חפצים, ולהחזיק מים, פנס ומטען. במקלט משותף, לתאם עם ועד הבית.'),
  ('899182ec-7a38-5fd0-ba3b-e18142a48954', 'he', 'general', 'light', 'הממ״ד הוא לא רק מחסן', 'פיקוד העורף ממליץ לפנות מקום, לבדוק שהחלון נסגר ולשים שם פנס ומים. עשר דקות, וסימנתם וי.'),
  ('7ac45d65-2f08-562e-9ca2-45b38dacfc7e', 'he', 'general', 'calm', 'שיבוש באספקת המים בשכונות הדרומיות של אשקלון עד 17:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 17:00. תאגיד המים מציב נקודות חלוקה, והצוותים כבר עובדים בשטח.'),
  ('7ac45d65-2f08-562e-9ca2-45b38dacfc7e', 'he', 'general', 'human', 'תושבים בשכונות הדרומיות של אשקלון בלי לחץ מים עד 17:00', 'משפחות בכמה שכונות מתארגנות עם בקבוקים ושכנים. "מילאנו סירים מראש, יהיה בסדר", מספרת תושבת. תאגיד המים מציב נקודות חלוקה.'),
  ('7ac45d65-2f08-562e-9ca2-45b38dacfc7e', 'he', 'general', 'informative', 'אשקלון: לחץ מים נמוך בשכונות הדרומיות עד 17:00', 'תקלה בצנרת ראשית פוגעת באספקת המים בשכונות הדרומיות. התיקון צפוי להסתיים עד 17:00. נקודות חלוקת מים פועלות, והפרטים באתר תאגיד המים.'),
  ('7ac45d65-2f08-562e-9ca2-45b38dacfc7e', 'he', 'general', 'light', 'שיבוש באספקת המים בשכונות הדרומיות של אשקלון עד 17:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 17:00. תאגיד המים מציב נקודות חלוקה ומעדכן באתר.'),
  ('1aeb4bed-5862-5b69-99e1-049040f32d87', 'he', 'general', 'calm', 'עונת התיאטרון החדשה נפתחת אחרי החגים', 'התיאטראות מציגים הצגות חדשות לצד חידושים של קלאסיקות. למנויים חדשים מוצעות הנחות בחודש הקרוב.'),
  ('1aeb4bed-5862-5b69-99e1-049040f32d87', 'he', 'general', 'human', 'שחקנית צעירה לפני הבכורה: "אני סופרת את הימים"', 'עונת התיאטרון החדשה נפתחת אחרי החגים, עם הצגות מקור וקלאסיקות מחודשות. גם הקהל, כך נראה, מתגעגע.'),
  ('1aeb4bed-5862-5b69-99e1-049040f32d87', 'he', 'general', 'informative', 'התיאטראות משיקים את עונת החורף', 'העונה כוללת הצגות מקור ועיבודים לקלאסיקות. המכירה למנויים פתוחה, עם הנחות עד סוף החודש.'),
  ('1aeb4bed-5862-5b69-99e1-049040f32d87', 'he', 'general', 'light', 'המסך עולה', 'עונת התיאטרון החדשה מגיעה אחרי החגים. מנוי זה גם תירוץ מצוין לצאת מהבית באמצע השבוע.'),
  ('b6d2a65d-7a43-54d3-8286-4c51fca47eaa', 'he', 'general', 'calm', 'שיעור האבטלה נותר נמוך', 'לפי נתוני הלשכה המרכזית לסטטיסטיקה, שוק העבודה יציב. הביקוש לעובדים גבוה בעיקר בבריאות, בחינוך ובבנייה.'),
  ('b6d2a65d-7a43-54d3-8286-4c51fca47eaa', 'he', 'general', 'human', 'מגייסת עובדים: "יש יותר משרות ממועמדים"', 'בענפי הבריאות, החינוך והבנייה מחפשים עובדים. הנתונים החדשים מראים שהאבטלה נותרה נמוכה ושוק העבודה יציב.'),
  ('b6d2a65d-7a43-54d3-8286-4c51fca47eaa', 'he', 'general', 'informative', 'הלמ״ס: האבטלה נמוכה, הביקוש לעובדים גבוה', 'שיעור האבטלה נותר נמוך ברבעון האחרון. מספר המשרות הפנויות בולט בבריאות, בחינוך ובבנייה. השכר הממוצע עלה מעט.'),
  ('b6d2a65d-7a43-54d3-8286-4c51fca47eaa', 'he', 'general', 'light', 'מחפשים עבודה? יש מה לחפש', 'הנתונים החדשים מראים אבטלה נמוכה, והמשרות הפנויות מחכות בעיקר בבריאות, בחינוך ובבנייה.'),
  ('f9a12b52-bf18-560a-a9f6-33ff9da0ce46', 'he', 'general', 'calm', 'מרוץ לילה בחיפה: כבישים ייסגרו בערב', 'אלפי רצים ישתתפו במרוץ העירוני. רחובות במרכז העיר ייסגרו בין 19:30–23:00, ומומלץ להגיע ברגל או בתחבורה ציבורית.'),
  ('f9a12b52-bf18-560a-a9f6-33ff9da0ce46', 'he', 'general', 'human', 'רצים חובבים מתכוננים למרוץ הלילה בחיפה', '"אני רצה לכבוד אבא שלי, זו השנה הראשונה שלי", מספרת משתתפת. המרוץ יתקיים הערב, וחלק מהרחובות ייסגרו בין 19:30–23:00.'),
  ('f9a12b52-bf18-560a-a9f6-33ff9da0ce46', 'he', 'general', 'informative', 'חיפה: סגירת רחובות בין 19:30–23:00 בשל מרוץ לילה', 'המרוץ העירוני יתקיים במקצים של 5, 10 ו־21 ק״מ. מפת הסגירות מתפרסמת באתר העירייה. קווי אוטובוס יוסטו למסלולים חלופיים.'),
  ('f9a12b52-bf18-560a-a9f6-33ff9da0ce46', 'he', 'general', 'light', 'נעלי ריצה, פנסי רחוב, יוצאים לדרך', 'מרוץ הלילה בחיפה חוזר. מי שלא רץ יכול לעודד, ומי שנוהג כדאי שיעקוף: סגירות בין 19:30–23:00.'),
  ('7dc5f40a-f4ea-517b-887a-afddeb4821bf', 'he', 'general', 'calm', 'לילות קרירים יותר הלילה', 'הטמפרטורות בלילה יירדו בכמה מעלות, בעיקר בהרים. ביום יהיה נעים עד חם, ללא שינוי מיוחד.'),
  ('7dc5f40a-f4ea-517b-887a-afddeb4821bf', 'he', 'general', 'human', 'בירושלים כבר מוציאים שמיכה דקה', '"בלילה פתחתי חלון והרגשתי את הסתיו", מספר תושב. הלילה הלילות יהיו קרירים יותר, בעיקר בהרים.'),
  ('7dc5f40a-f4ea-517b-887a-afddeb4821bf', 'he', 'general', 'informative', 'תחזית: ירידה בטמפרטורות הלילה הלילה', 'בהרים ירדו הטמפרטורות בלילה ל־16–18 מעלות, ובמישור החוף ל־21–23. ביום: נאה עד חם. אין צפי לגשם.'),
  ('7dc5f40a-f4ea-517b-887a-afddeb4821bf', 'he', 'general', 'light', 'הסתיו שולח הודעה ראשונה', 'הלילה הלילות יהיו קרירים יותר, בעיקר בהרים. זה הרגע להוציא את השמיכה הדקה מהארון.'),
  ('95166b23-a8ae-576d-8b85-01a60b2ee83b', 'he', 'general', 'calm', 'מרוץ לילה בבאר שבע: כבישים ייסגרו בערב', 'אלפי רצים ישתתפו במרוץ העירוני. רחובות במרכז העיר ייסגרו בין 19:00–22:30, ומומלץ להגיע ברגל או בתחבורה ציבורית.'),
  ('95166b23-a8ae-576d-8b85-01a60b2ee83b', 'he', 'general', 'human', 'רצים חובבים מתכוננים למרוץ הלילה בבאר שבע', '"אני רצה לכבוד אבא שלי, זו השנה הראשונה שלי", מספרת משתתפת. המרוץ יתקיים הערב, וחלק מהרחובות ייסגרו בין 19:00–22:30.'),
  ('95166b23-a8ae-576d-8b85-01a60b2ee83b', 'he', 'general', 'informative', 'באר שבע: סגירת רחובות בין 19:00–22:30 בשל מרוץ לילה', 'המרוץ העירוני יתקיים במקצים של 5, 10 ו־21 ק״מ. מפת הסגירות מתפרסמת באתר העירייה. קווי אוטובוס יוסטו למסלולים חלופיים.'),
  ('95166b23-a8ae-576d-8b85-01a60b2ee83b', 'he', 'general', 'light', 'נעלי ריצה, פנסי רחוב, יוצאים לדרך', 'מרוץ הלילה בבאר שבע חוזר. מי שלא רץ יכול לעודד, ומי שנוהג כדאי שיעקוף: סגירות בין 19:00–22:30.'),
  ('e0fe82be-8044-57fe-bd05-9fb50e548a1c', 'he', 'general', 'calm', 'לילות קרירים יותר מחר', 'הטמפרטורות בלילה יירדו בכמה מעלות, בעיקר בהרים. ביום יהיה נעים עד חם, ללא שינוי מיוחד.'),
  ('e0fe82be-8044-57fe-bd05-9fb50e548a1c', 'he', 'general', 'human', 'בירושלים כבר מוציאים שמיכה דקה', '"בלילה פתחתי חלון והרגשתי את הסתיו", מספר תושב. מחר הלילות יהיו קרירים יותר, בעיקר בהרים.'),
  ('e0fe82be-8044-57fe-bd05-9fb50e548a1c', 'he', 'general', 'informative', 'תחזית: ירידה בטמפרטורות הלילה מחר', 'בהרים ירדו הטמפרטורות בלילה ל־16–18 מעלות, ובמישור החוף ל־21–23. ביום: נאה עד חם. אין צפי לגשם.'),
  ('e0fe82be-8044-57fe-bd05-9fb50e548a1c', 'he', 'general', 'light', 'הסתיו שולח הודעה ראשונה', 'מחר הלילות יהיו קרירים יותר, בעיקר בהרים. זה הרגע להוציא את השמיכה הדקה מהארון.'),
  ('37e9234a-8e0b-5573-b7fa-5d7bb927ef93', 'he', 'general', 'calm', 'תרגיל של פיקוד העורף באזור הנגב: הצופר הוא חלק מהתרגיל', 'מחר בשעה 11:30 יישמע צופר באזור הנגב במסגרת תרגיל מתוכנן. אין צורך לעשות דבר מלבד להמשיך בשגרה. בתי הספר ישתתפו בתרגיל.'),
  ('37e9234a-8e0b-5573-b7fa-5d7bb927ef93', 'he', 'general', 'human', 'גננות ומורים באזור הנגב מכינים את הילדים לתרגיל', '"הסברנו מראש שזה רק תרגול, והילדים התייחסו לזה כמו למשחק", מספרת גננת. מחר בשעה 11:30 יישמע צופר כחלק מתרגיל מתוכנן.'),
  ('37e9234a-8e0b-5573-b7fa-5d7bb927ef93', 'he', 'general', 'informative', 'מחר ב־11:30: צופר תרגיל באזור הנגב', 'פיקוד העורף יקיים תרגיל מתוכנן באזור הנגב, כולל הפעלת צופר בשעה 11:30. אין הנחיות מיוחדות לציבור. מוסדות החינוך יתרגלו כניסה למרחב מוגן.'),
  ('37e9234a-8e0b-5573-b7fa-5d7bb927ef93', 'he', 'general', 'light', 'תרגיל של פיקוד העורף באזור הנגב: הצופר הוא חלק מהתרגיל', 'מחר בשעה 11:30 יישמע צופר במסגרת תרגיל מתוכנן. אין צורך לעשות דבר מלבד להמשיך בשגרה.'),
  ('9f1afc2b-ea6e-52a1-984c-f8179f072b4a', 'he', 'general', 'calm', 'כדאי לבדוק את דמי הניהול בקרן הפנסיה', 'הבדל קטן בדמי הניהול מצטבר לסכום משמעותי לאורך השנים. אפשר לבדוק אותם בדוח השנתי ולבקש הנחה בשיחת טלפון.'),
  ('9f1afc2b-ea6e-52a1-984c-f8179f072b4a', 'he', 'general', 'human', '"שיחה אחת של עשר דקות חסכה לי אלפי שקלים"', 'שכיר מהמרכז גילה שהוא משלם דמי ניהול גבוהים מהממוצע, והתקשר לבקש הנחה. יועצים ממליצים לכולם לבדוק את הדוח השנתי.'),
  ('9f1afc2b-ea6e-52a1-984c-f8179f072b4a', 'he', 'general', 'informative', 'איך בודקים את דמי הניהול בפנסיה', 'בדוח השנתי מופיעים שני שיעורים: מההפקדה ומהצבירה. אפשר להשוות לממוצע באתר רשות שוק ההון ולבקש הפחתה מהקרן או לעבור קרן.'),
  ('9f1afc2b-ea6e-52a1-984c-f8179f072b4a', 'he', 'general', 'light', 'עשר דקות שוות הרבה כסף', 'בודקים בדוח השנתי כמה משלמים דמי ניהול, מתקשרים לקרן ומבקשים הנחה. ההבדל מצטבר לסכום יפה.'),
  ('f5389dbd-03e8-5c77-9438-e8564bebe924', 'he', 'general', 'calm', 'ועדה בכנסת תדון ברפורמה בתחבורה הציבורית', 'הדיון יעסוק בתדירות הקווים בפריפריה ובתחבורה ציבורית בסופי שבוע באזורים מסוימים. הוא פתוח לציבור בשידור.'),
  ('f5389dbd-03e8-5c77-9438-e8564bebe924', 'he', 'general', 'human', 'נוסעים מהפריפריה יציגו את עמדתם בכנסת', '"אנחנו מחכים שעה לאוטובוס בערב", אומרת נציגת נוסעים שתופיע בדיון. הוועדה תדון ברפורמה בתחבורה הציבורית.'),
  ('f5389dbd-03e8-5c77-9438-e8564bebe924', 'he', 'general', 'informative', 'הכנסת: דיון ברפורמה בתחבורה הציבורית', 'על הפרק: תדירות קווים בפריפריה, תחבורה בסופי שבוע באזורים מסוימים ותמחור הכרטיסים. הדיון ישודר בערוץ הכנסת.'),
  ('f5389dbd-03e8-5c77-9438-e8564bebe924', 'he', 'general', 'light', 'האוטובוס מגיע לכנסת', 'ועדה בכנסת תדון ברפורמה בתחבורה הציבורית, מתדירות הקווים בפריפריה ועד מחירי הכרטיסים.'),
  ('dc1eea0b-8f34-5c3c-9c10-ab157b630e87', 'he', 'general', 'calm', 'עבודות הרכבת הקלה בירושלים: שינויי תנועה בציר הקו הכחול', 'במשך שלושה שבועות יוצר נתיב אחד בכל כיוון בציר הקו הכחול. קווי האוטובוס ממשיכים לפעול, עם תחנות זמניות מסומנות.'),
  ('dc1eea0b-8f34-5c3c-9c10-ab157b630e87', 'he', 'general', 'human', 'סוחרים בציר הקו הכחול מקווים שהעבודות יסתיימו מהר', '"הלקוחות הקבועים מגיעים גם ברגל", מספר בעל חנות. עבודות הרכבת הקלה בירושלים יצמצמו את התנועה בציר הקו הכחול במשך שלושה שבועות.'),
  ('dc1eea0b-8f34-5c3c-9c10-ab157b630e87', 'he', 'general', 'informative', 'ירושלים: צמצום נתיבים בציר הקו הכחול ל־שלושה שבועות', 'בשל עבודות הרכבת הקלה יפעל נתיב אחד בכל כיוון. תחנות אוטובוס יועתקו זמנית. מומלץ להשתמש בצירים חלופיים בשעות העומס.'),
  ('dc1eea0b-8f34-5c3c-9c10-ab157b630e87', 'he', 'general', 'light', 'ציר הקו הכחול על דיאטת נתיבים', 'במשך שלושה שבועות ייסגר נתיב בכל כיוון בגלל עבודות הרכבת הקלה בירושלים. אופניים וקורקינטים, זה הזמן שלכם.'),
  ('4db66d0b-0d97-504b-bb8f-5f5390b9c561', 'he', 'general', 'calm', 'לוח זמנים חדש לפינוי גזם ופסולת גושית', 'מהשבוע הבא יתבצע הפינוי בשכונת קטמונים פעמיים בשבוע. את לוח הזמנים המלא אפשר למצוא באתר העירייה.'),
  ('4db66d0b-0d97-504b-bb8f-5f5390b9c561', 'he', 'general', 'informative', 'שכונת קטמונים: פינוי גזם בימים שני וחמישי', 'העירייה מעדכנת את מועדי פינוי הגזם והפסולת הגושית. יש להוציא את הפסולת עד 07:00 בבוקר יום הפינוי.'),
  ('c08ee7cc-4d80-5c30-8abf-724481274e54', 'he', 'general', 'calm', 'שיבושים בקווי אוטובוס בחיפה עד 11:00', 'בעקבות מחלוקת עבודה אצל אחד המפעילים, חלק מהקווים בחיפה לא יפעלו הבוקר עד 11:00. הרכבת והקווים של שאר המפעילים פועלים כרגיל.'),
  ('c08ee7cc-4d80-5c30-8abf-724481274e54', 'he', 'general', 'human', 'נוסעים בחיפה מחפשים דרך אחרת לעבודה', 'בתחנות מתארגנים לנסיעות משותפות ולקורקינטים. "יצאתי חצי שעה מוקדם, זה עובד", מספרת סטודנטית. חלק מהקווים לא יפעלו עד 11:00.'),
  ('c08ee7cc-4d80-5c30-8abf-724481274e54', 'he', 'general', 'informative', 'חיפה: חלק מקווי האוטובוס מושבתים עד 11:00', 'מחלוקת עבודה אצל מפעיל אחד משביתה חלק מהקווים בחיפה עד 11:00. רשימת הקווים באפליקציות התחבורה. הרכבת ושאר המפעילים פועלים כסדרם.'),
  ('c08ee7cc-4d80-5c30-8abf-724481274e54', 'he', 'general', 'light', 'שיבושים בקווי אוטובוס בחיפה עד 11:00', 'חלק מהקווים של אחד המפעילים לא יפעלו הבוקר עד 11:00. כדאי לבדוק באפליקציית התחבורה לפני היציאה.'),
  ('9854ee61-1342-568d-9fcd-8d2c6be6bbcc', 'he', 'general', 'calm', 'ליגת העל בכדורגל: המחזור השלישי הושלם', 'שלוש הקבוצות המובילות ניצחו, והפער בצמרת נשאר נקודה אחת. המחזור הבא ייערך אחרי החג.'),
  ('9854ee61-1342-568d-9fcd-8d2c6be6bbcc', 'he', 'general', 'human', 'אוהדים חזרו מהמגרש עם חיוך, ועם צרידות', '"שרנו תשעים דקות, שווה כל רגע", מספר אוהד. במחזור השלישי של ליגת העל ניצחו כל הקבוצות המובילות, והצמרת צפופה.'),
  ('9854ee61-1342-568d-9fcd-8d2c6be6bbcc', 'he', 'general', 'informative', 'ליגת העל: סיכום המחזור השלישי', 'הקבוצות המובילות ניצחו, והפער בין המקום הראשון לשלישי עומד על נקודה אחת. נכבשו 21 שערים במחזור. המחזור הבא אחרי החג.'),
  ('9854ee61-1342-568d-9fcd-8d2c6be6bbcc', 'he', 'general', 'light', 'הצמרת צפופה כמו תור לפלאפל', 'במחזור השלישי ניצחו כל המובילות, ורק נקודה אחת מפרידה בין שלוש הראשונות. אחרי החג ממשיכים.'),
  ('6ed52f5f-135c-5028-8315-10501b101827', 'he', 'general', 'calm', 'חם מהרגיל מחר, ובערב נעים יותר', 'הטמפרטורות יגיעו לכ־34 מעלות בשרון ובשפלה. מספיק לשתות מים ולהישאר בצל בשעות הצהריים. בערב צפויה הקלה.'),
  ('6ed52f5f-135c-5028-8315-10501b101827', 'he', 'general', 'human', 'מי שעובד בחוץ ירגיש את החום מחר', 'פועלי בניין, שליחים וחקלאים בשרון ובשפלה יפגשו כ־34 מעלות. "אנחנו מתחילים מוקדם ומסיימים לפני הצהריים", מספר מנהל עבודה. בערב צפויה הקלה.'),
  ('6ed52f5f-135c-5028-8315-10501b101827', 'he', 'general', 'informative', '34 מעלות בשרון ובשפלה מחר, הקלה בערב', 'עומס חום בינוני בשרון ובשפלה: עד 34 מעלות בשעות הצהריים. משרד הבריאות ממליץ לשתות באופן קבוע ולהימנע ממאמץ בשמש בין 11:00 ל־16:00.'),
  ('6ed52f5f-135c-5028-8315-10501b101827', 'he', 'general', 'light', 'הכובע והבקבוק חוזרים לתיק', 'מחר יהיה חם, עד 34 מעלות בשרון ובשפלה. מים קרים, צל טוב ומזגן בטמפרטורה סבירה, והערב כבר יהיה נעים יותר.'),
  ('b4b8b1fd-3d32-5e5f-b316-cd1a0d1ccb37', 'he', 'general', 'calm', 'הודעות מזויפות על קנס חניה: לא לשלם דרך קישור', 'מתקבלות הודעות SMS שמבקשות תשלום קטן על קנס חניה. גופים רשמיים לא מבקשים פרטי אשראי בהודעה. אם יש ספק, נכנסים לאתר הרשמי ישירות.'),
  ('b4b8b1fd-3d32-5e5f-b316-cd1a0d1ccb37', 'he', 'general', 'human', '"כמעט שילמתי 12 שקלים על חבילה שלא הזמנתי"', 'גמלאית מהמרכז קיבלה הודעה על קנס חניה ועצרה רגע לפני התשלום. המשטרה מזכירה: לא לוחצים על קישורים בהודעות כאלה.'),
  ('b4b8b1fd-3d32-5e5f-b316-cd1a0d1ccb37', 'he', 'general', 'informative', 'אזהרה: הודעות SMS מתחזות בנושא קנס חניה', 'הונאה חוזרת: הודעה עם קישור לתשלום קטן על קנס חניה. הקישור מוביל לאתר מתחזה שאוסף פרטי אשראי. מי שמסר פרטים צריך לפנות מיד לחברת האשראי.'),
  ('b4b8b1fd-3d32-5e5f-b316-cd1a0d1ccb37', 'he', 'general', 'light', 'הודעה על קנס חניה? קודם נושמים', 'נוכלים שולחים הודעות עם קישור לתשלום קטן על קנס חניה. הכלל פשוט: לא לוחצים, נכנסים לבד לאתר הרשמי.'),
  ('1c092c44-c93b-568e-96a0-471a016c6339', 'he', 'general', 'calm', 'בית משפט: ספקית אינטרנט תחזיר ללקוחות חיובים כפולים', 'בית המשפט אישר הסדר בתביעה ייצוגית. הלקוחות שחויבו פעמיים יקבלו זיכוי אוטומטי בחשבון הבא, בלי צורך לפנות.'),
  ('1c092c44-c93b-568e-96a0-471a016c6339', 'he', 'general', 'human', 'לקוחה שגילתה חיוב כפול: "חשבתי שזה רק אצלי"', 'בדיקה שגרתית של דף האשראי הובילה לתביעה ייצוגית. עכשיו אישר בית המשפט הסדר: ספקית אינטרנט תחזיר את הכסף לכל מי שחויב פעמיים.'),
  ('1c092c44-c93b-568e-96a0-471a016c6339', 'he', 'general', 'informative', 'הסדר ייצוגי: ספקית אינטרנט תזכה לקוחות על חיובים כפולים', 'בית המשפט המחוזי אישר את ההסדר. הזיכוי יינתן אוטומטית בחשבון הקרוב. לקוחות לשעבר יקבלו החזר בהעברה בנקאית תוך 90 יום.'),
  ('1c092c44-c93b-568e-96a0-471a016c6339', 'he', 'general', 'light', 'חויבתם פעמיים? הכסף חוזר', 'בית משפט אישר הסדר שבו ספקית אינטרנט מחזירה ללקוחות חיובים כפולים. לא צריך לעשות כלום, רק לבדוק את החשבון הבא.'),
  ('d5314c80-8d4b-59cc-9a05-c68af6000be0', 'he', 'general', 'calm', 'טיפת חלב חדשה נפתחה במרכז העיר', 'התחנה החדשה משרתת משפחות מהשכונות הסמוכות. אפשר לקבוע תור בטלפון או באתר משרד הבריאות.'),
  ('d5314c80-8d4b-59cc-9a05-c68af6000be0', 'he', 'general', 'informative', 'מרכז העיר: נפתחה תחנת טיפת חלב חדשה', 'התחנה פועלת בימים א׳–ה׳ בין 08:00 ל־14:00, ובימי שלישי גם אחר הצהריים. התורים באתר משרד הבריאות.'),
  ('765a20d1-a256-5cd6-8041-b4a7c88d5d74', 'he', 'general', 'calm', 'ההרשמה לגני טרום חובה לשנה הבאה תיפתח אחרי החגים', 'הרשויות המקומיות יפרסמו בקרוב את מועדי ההרשמה לגני טרום חובה. אין צורך למהר: ההרשמה נמשכת כמה שבועות ונעשית באתר הרשות.'),
  ('765a20d1-a256-5cd6-8041-b4a7c88d5d74', 'he', 'general', 'human', 'הורים מתכוננים להרשמה לגני טרום חובה', 'בקבוצות ההורים כבר שואלים על מועדים ומסמכים. "הכנתי צילום תעודת זהות מראש", מספר אב לשלושה. ההרשמה תיפתח אחרי החגים באתרי הרשויות.'),
  ('765a20d1-a256-5cd6-8041-b4a7c88d5d74', 'he', 'general', 'informative', 'הרשמה לגני טרום חובה: תיפתח אחרי החגים באתרי הרשויות', 'ההרשמה לגני טרום חובה לשנת הלימודים הבאה תתקיים באתרי הרשויות המקומיות ותימשך כמה שבועות. נדרשים ספח תעודת זהות ואישור כתובת.'),
  ('765a20d1-a256-5cd6-8041-b4a7c88d5d74', 'he', 'general', 'light', 'הורים, יומן ביד: ההרשמה לגני טרום חובה מתקרבת', 'אחרי החגים נפתחת ההרשמה לגני טרום חובה באתרי הרשויות. מכינים ספח תעודת זהות ואישור כתובת, ומסיימים בכמה דקות.'),
  ('f333b144-c5e3-591d-9064-d7a0e2b2a502', 'he', 'general', 'calm', 'עבודות הרכבת הקלה בתל אביב־יפו: שינויי תנועה ברחוב אבן גבירול', 'במשך חודש יוצר נתיב אחד בכל כיוון ברחוב אבן גבירול. קווי האוטובוס ממשיכים לפעול, עם תחנות זמניות מסומנות.'),
  ('f333b144-c5e3-591d-9064-d7a0e2b2a502', 'he', 'general', 'human', 'סוחרים ברחוב אבן גבירול מקווים שהעבודות יסתיימו מהר', '"הלקוחות הקבועים מגיעים גם ברגל", מספר בעל חנות. עבודות הרכבת הקלה בתל אביב־יפו יצמצמו את התנועה ברחוב אבן גבירול במשך חודש.'),
  ('f333b144-c5e3-591d-9064-d7a0e2b2a502', 'he', 'general', 'informative', 'תל אביב־יפו: צמצום נתיבים ברחוב אבן גבירול ל־חודש', 'בשל עבודות הרכבת הקלה יפעל נתיב אחד בכל כיוון. תחנות אוטובוס יועתקו זמנית. מומלץ להשתמש בצירים חלופיים בשעות העומס.'),
  ('f333b144-c5e3-591d-9064-d7a0e2b2a502', 'he', 'general', 'light', 'רחוב אבן גבירול על דיאטת נתיבים', 'במשך חודש ייסגר נתיב בכל כיוון בגלל עבודות הרכבת הקלה בתל אביב־יפו. אופניים וקורקינטים, זה הזמן שלכם.'),
  ('99c130f5-caf2-566f-b815-944fe674cb9b', 'he', 'general', 'calm', 'ספורטאית פראלימפית צעירה זכתה במדליה בריצה', 'בתחרות בינלאומית זכתה ספורטאית בת 19 במדליית כסף בריצה. היא מתאמנת במרכז הספורט הפראלימפי כבר שש שנים.'),
  ('99c130f5-caf2-566f-b815-944fe674cb9b', 'he', 'general', 'human', '"חלמתי על הרגע הזה מגיל 13"', 'ספורטאית פראלימפית בת 19 זכתה במדליית כסף בריצה בתחרות בינלאומית. המאמנת שלה סיפרה שהיא מתאמנת כל בוקר לפני הלימודים.'),
  ('99c130f5-caf2-566f-b815-944fe674cb9b', 'he', 'general', 'informative', 'מדליית כסף לספורטאית פראלימפית בריצה', 'הספורטאית, בת 19, סיימה במקום השני בתחרות בינלאומית, בתוצאה אישית הטובה ביותר שלה. זו המדליה הבינלאומית הראשונה שלה.'),
  ('99c130f5-caf2-566f-b815-944fe674cb9b', 'he', 'general', 'light', 'כסף שמרגיש כמו זהב', 'ספורטאית פראלימפית בת 19 זכתה במדליית כסף בריצה ושברה שיא אישי. הבוקר שלה מתחיל באימון, והשאר היסטוריה.'),
  ('82eb8663-af96-5be1-95d8-2bd7af1e1248', 'he', 'general', 'calm', 'עבודות מתוכננות: הפסקת מים לילית בעפולה', 'בשכונות אחדות בעפולה לא יהיו מים הלילה בין 00:00–05:00, בשל החלפת צנרת. בבוקר האספקה תחזור כרגיל.'),
  ('82eb8663-af96-5be1-95d8-2bd7af1e1248', 'he', 'general', 'human', 'תושבי עפולה ממלאים קומקום לפני השינה', '"שמתי בקבוק ליד המיטה ומילאתי קומקום לקפה של הבוקר", מספר תושב. בשכונות אחדות לא יהיו מים הלילה בין 00:00–05:00.'),
  ('82eb8663-af96-5be1-95d8-2bd7af1e1248', 'he', 'general', 'informative', 'עפולה: הפסקת מים מתוכננת בין 00:00–05:00', 'תאגיד המים מחליף צנרת ראשית. ההפסקה הלילה תחול על כמה שכונות, והרשימה המלאה באתר התאגיד. אחרי החידוש ייתכן צבע עכור במים לכמה דקות.'),
  ('82eb8663-af96-5be1-95d8-2bd7af1e1248', 'he', 'general', 'light', 'מקלחת מוקדמת הערב, תושבי עפולה', 'בשכונות אחדות לא יהיו מים הלילה בין 00:00–05:00, כי מחליפים צנרת. ממלאים קומקום, והבוקר הכל זורם.'),
  ('ee0e1296-6627-5e8e-be95-114bfbc5ca1f', 'he', 'general', 'calm', 'חם מהרגיל מחר, ובערב נעים יותר', 'הטמפרטורות יגיעו לכ־32 מעלות באזור ההר. מספיק לשתות מים ולהישאר בצל בשעות הצהריים. בערב צפויה הקלה.'),
  ('ee0e1296-6627-5e8e-be95-114bfbc5ca1f', 'he', 'general', 'human', 'מי שעובד בחוץ ירגיש את החום מחר', 'פועלי בניין, שליחים וחקלאים באזור ההר יפגשו כ־32 מעלות. "אנחנו מתחילים מוקדם ומסיימים לפני הצהריים", מספר מנהל עבודה. בערב צפויה הקלה.'),
  ('ee0e1296-6627-5e8e-be95-114bfbc5ca1f', 'he', 'general', 'informative', '32 מעלות באזור ההר מחר, הקלה בערב', 'עומס חום בינוני באזור ההר: עד 32 מעלות בשעות הצהריים. משרד הבריאות ממליץ לשתות באופן קבוע ולהימנע ממאמץ בשמש בין 11:00 ל־16:00.'),
  ('ee0e1296-6627-5e8e-be95-114bfbc5ca1f', 'he', 'general', 'light', 'הכובע והבקבוק חוזרים לתיק', 'מחר יהיה חם, עד 32 מעלות באזור ההר. מים קרים, צל טוב ומזגן בטמפרטורה סבירה, והערב כבר יהיה נעים יותר.'),
  ('93d5bdcf-5a14-54fb-b282-070b3da25dd3', 'he', 'general', 'calm', 'תרגיל של פיקוד העורף באזור השרון: הצופר הוא חלק מהתרגיל', 'מחר בשעה 10:00 יישמע צופר באזור השרון במסגרת תרגיל מתוכנן. אין צורך לעשות דבר מלבד להמשיך בשגרה. בתי הספר ישתתפו בתרגיל.'),
  ('93d5bdcf-5a14-54fb-b282-070b3da25dd3', 'he', 'general', 'human', 'גננות ומורים באזור השרון מכינים את הילדים לתרגיל', '"הסברנו מראש שזה רק תרגול, והילדים התייחסו לזה כמו למשחק", מספרת גננת. מחר בשעה 10:00 יישמע צופר כחלק מתרגיל מתוכנן.'),
  ('93d5bdcf-5a14-54fb-b282-070b3da25dd3', 'he', 'general', 'informative', 'מחר ב־10:00: צופר תרגיל באזור השרון', 'פיקוד העורף יקיים תרגיל מתוכנן באזור השרון, כולל הפעלת צופר בשעה 10:00. אין הנחיות מיוחדות לציבור. מוסדות החינוך יתרגלו כניסה למרחב מוגן.'),
  ('93d5bdcf-5a14-54fb-b282-070b3da25dd3', 'he', 'general', 'light', 'תרגיל של פיקוד העורף באזור השרון: הצופר הוא חלק מהתרגיל', 'מחר בשעה 10:00 יישמע צופר במסגרת תרגיל מתוכנן. אין צורך לעשות דבר מלבד להמשיך בשגרה.'),
  ('99b45ea1-b5c4-581a-a953-1c06af5541d5', 'he', 'general', 'calm', 'שדרות רוטשילד נפתח מחדש אחרי שיפוץ', 'בפארק נוספו מתקני משחק מוצלים, ברזיות ושבילי הליכה מוארים. הוא פתוח מהבוקר ועד חצות.'),
  ('99b45ea1-b5c4-581a-a953-1c06af5541d5', 'he', 'general', 'informative', 'שדרות רוטשילד: הפארק נפתח אחרי שיפוץ של חצי שנה', 'נוספו מתקני משחק מוצלים, ברזיות, תאורה בשבילים ופינת כושר. שעות הפעילות: 06:00–24:00.'),
  ('318c2e30-de3d-5a06-954f-8a5bf09229a9', 'he', 'general', 'calm', 'נבחרת הנוער בשחייה עלתה לגמר באליפות אירופה', 'הנבחרת ניצחה אתמול בשני משחקים רצופים. המשחק הבא ישודר בערוצי הספורט, והשחקנים מספרים שהם ממוקדים ורגועים.'),
  ('318c2e30-de3d-5a06-954f-8a5bf09229a9', 'he', 'general', 'human', 'ההורים ביציע לא הפסיקו לשיר', 'נבחרת הנוער בשחייה עלתה לגמר באליפות אירופה. "הם שיחקו בשביל החברים שלהם בבית", אמר המאמן אחרי הניצחון.'),
  ('318c2e30-de3d-5a06-954f-8a5bf09229a9', 'he', 'general', 'informative', 'נבחרת הנוער בשחייה: עלייה לגמר באליפות אירופה', 'אחרי שני ניצחונות רצופים הבטיחה הנבחרת את מקומה לגמר. המשחק הבא בסוף השבוע ישודר בשידור חי.'),
  ('318c2e30-de3d-5a06-954f-8a5bf09229a9', 'he', 'general', 'light', 'הנוער שלנו בשחייה ממשיך לטפס', 'עוד ניצחון, ועוד שלב: נבחרת הנוער בשחייה עלתה לגמר באליפות אירופה. הדגלים כבר במרפסות.'),
  ('bb22e8bc-de6d-5f9b-9c09-d20b8e6daeb7', 'he', 'general', 'calm', 'גשם ראשון בדרך לצפון', 'צפויות טפטופות וממטרים קלים בגליל המערבי בסוף השבוע הבא. אין צורך בהיערכות מיוחדת, רק מטרייה קרובה.'),
  ('bb22e8bc-de6d-5f9b-9c09-d20b8e6daeb7', 'he', 'general', 'human', 'בצפון מחכים לגשם הראשון, ובעיקר החקלאים', 'ממטרים קלים צפויים בגליל המערבי בסוף השבוע הבא. "זה בדיוק מה שהאדמה צריכה אחרי הקיץ", אומר מגדל תפוחים מהאזור.'),
  ('bb22e8bc-de6d-5f9b-9c09-d20b8e6daeb7', 'he', 'general', 'informative', 'תחזית: ממטרים ראשונים בגליל המערבי בסוף השבוע הבא', 'ממטרים קלים ומקומיים צפויים בגליל המערבי בסוף השבוע הבא, עם ירידה של 3–4 מעלות בטמפרטורות. בשאר הארץ יהיה מעונן חלקית.'),
  ('bb22e8bc-de6d-5f9b-9c09-d20b8e6daeb7', 'he', 'general', 'light', 'הוציאו את המטריות מהבוידעם', 'הגשם הראשון של העונה מגיע בגליל המערבי בסוף השבוע הבא. לא מבול, אבל מספיק כדי להריח את הסתיו.'),
  ('2dddc47e-13b8-55cc-b9a8-9159ae833ace', 'he', 'general', 'calm', 'הפסקת חשמל יזומה באילת ביום רביעי בבוקר', 'חברת החשמל תבצע עבודות תחזוקה בכמה רחובות באילת בין 06:00–09:00. הלקוחות ברחובות האלה קיבלו הודעה, והזרם יחזור בסיום העבודות.'),
  ('2dddc47e-13b8-55cc-b9a8-9159ae833ace', 'he', 'general', 'human', 'עסקים קטנים באילת נערכים לבוקר בלי חשמל', '"נפתח שעתיים אחר כך, זה בסדר", אומרת בעלת בית קפה. חברת החשמל תבצע ביום רביעי עבודות תחזוקה בכמה רחובות בין 06:00–09:00.'),
  ('2dddc47e-13b8-55cc-b9a8-9159ae833ace', 'he', 'general', 'informative', 'אילת: הפסקת חשמל מתוכננת ביום רביעי בין 06:00–09:00', 'העבודות נועדו לשדרג את רשת החשמל לקראת החורף. רשימת הרחובות באתר חברת החשמל. מומלץ לנתק מכשירים רגישים לפני ההפסקה.'),
  ('2dddc47e-13b8-55cc-b9a8-9159ae833ace', 'he', 'general', 'light', 'ביום רביעי בבוקר: קפה בחוץ, תושבי אילת', 'חברת החשמל משדרגת את הרשת בכמה רחובות בין 06:00–09:00. מנתקים מחשבים רגישים, ובצהריים הכל דולק שוב.'),
  ('86561e53-1fbb-588c-bf4f-09f09eba5b43', 'he', 'general', 'calm', 'עבודות תחזוקה ברכבת בין בית שמש לירושלים בלילה שבין חמישי לשישי', 'הרכבות בין בית שמש לירושלים לא יפעלו בלילה שבין חמישי לשישי אחרי 22:00. יופעלו אוטובוסים חלופיים מהתחנות, ובבוקר התנועה תחזור לשגרה.'),
  ('86561e53-1fbb-588c-bf4f-09f09eba5b43', 'he', 'general', 'human', 'נוסעי הלילה בין בית שמש לירושלים יעברו לאוטובוסים', 'מי שחוזר מאוחר מהעבודה יצטרך לתכנן מחדש בלילה שבין חמישי לשישי. "העיקר שיש הסעה חלופית", אומר נוסע קבוע. הרכבות יחזרו לפעול בבוקר.'),
  ('86561e53-1fbb-588c-bf4f-09f09eba5b43', 'he', 'general', 'informative', 'הרכבת בין בית שמש לירושלים: הפסקת תנועה בלילה שבין חמישי לשישי מ־22:00', 'בשל עבודות תחזוקה לא יפעלו רכבות בין בית שמש לירושלים בלילה שבין חמישי לשישי מ־22:00 ועד תחילת השירות בבוקר. אוטובוסים חלופיים ייצאו מהתחנות כל 20 דקות.'),
  ('86561e53-1fbb-588c-bf4f-09f09eba5b43', 'he', 'general', 'light', 'הרכבת לוקחת כמה לילות לטיפוח', 'עבודות תחזוקה בין בית שמש לירושלים בלילה שבין חמישי לשישי: אחרי 22:00 עוברים לאוטובוסים החלופיים. בבוקר הכל חוזר למסלול.'),
  ('a10e9184-34ac-55eb-bc0f-2ab20cc57878', 'he', 'general', 'calm', 'תרגיל של פיקוד העורף באזור ירושלים: הצופר הוא חלק מהתרגיל', 'מחר בשעה 10:00 יישמע צופר באזור ירושלים במסגרת תרגיל מתוכנן. אין צורך לעשות דבר מלבד להמשיך בשגרה. בתי הספר ישתתפו בתרגיל.'),
  ('a10e9184-34ac-55eb-bc0f-2ab20cc57878', 'he', 'general', 'human', 'גננות ומורים באזור ירושלים מכינים את הילדים לתרגיל', '"הסברנו מראש שזה רק תרגול, והילדים התייחסו לזה כמו למשחק", מספרת גננת. מחר בשעה 10:00 יישמע צופר כחלק מתרגיל מתוכנן.'),
  ('a10e9184-34ac-55eb-bc0f-2ab20cc57878', 'he', 'general', 'informative', 'מחר ב־10:00: צופר תרגיל באזור ירושלים', 'פיקוד העורף יקיים תרגיל מתוכנן באזור ירושלים, כולל הפעלת צופר בשעה 10:00. אין הנחיות מיוחדות לציבור. מוסדות החינוך יתרגלו כניסה למרחב מוגן.'),
  ('a10e9184-34ac-55eb-bc0f-2ab20cc57878', 'he', 'general', 'light', 'תרגיל של פיקוד העורף באזור ירושלים: הצופר הוא חלק מהתרגיל', 'מחר בשעה 10:00 יישמע צופר במסגרת תרגיל מתוכנן. אין צורך לעשות דבר מלבד להמשיך בשגרה.'),
  ('9c84ab94-d617-5763-8cb2-44a30f5414e2', 'he', 'general', 'calm', 'לוח זמנים חדש לפינוי גזם ופסולת גושית', 'מהשבוע הבא יתבצע הפינוי בפארק המסילה פעמיים בשבוע. את לוח הזמנים המלא אפשר למצוא באתר העירייה.'),
  ('9c84ab94-d617-5763-8cb2-44a30f5414e2', 'he', 'general', 'informative', 'פארק המסילה: פינוי גזם בימים שני וחמישי', 'העירייה מעדכנת את מועדי פינוי הגזם והפסולת הגושית. יש להוציא את הפסולת עד 07:00 בבוקר יום הפינוי.'),
  ('43aa1bd5-57ad-5bf1-b307-1a41d7503e61', 'he', 'general', 'calm', 'עבודות מתוכננות: הפסקת מים לילית ברמת גן', 'בשכונות אחדות ברמת גן לא יהיו מים הלילה בין 23:00–05:00, בשל החלפת צנרת. בבוקר האספקה תחזור כרגיל.'),
  ('43aa1bd5-57ad-5bf1-b307-1a41d7503e61', 'he', 'general', 'human', 'תושבי רמת גן ממלאים קומקום לפני השינה', '"שמתי בקבוק ליד המיטה ומילאתי קומקום לקפה של הבוקר", מספר תושב. בשכונות אחדות לא יהיו מים הלילה בין 23:00–05:00.'),
  ('43aa1bd5-57ad-5bf1-b307-1a41d7503e61', 'he', 'general', 'informative', 'רמת גן: הפסקת מים מתוכננת בין 23:00–05:00', 'תאגיד המים מחליף צנרת ראשית. ההפסקה הלילה תחול על כמה שכונות, והרשימה המלאה באתר התאגיד. אחרי החידוש ייתכן צבע עכור במים לכמה דקות.'),
  ('43aa1bd5-57ad-5bf1-b307-1a41d7503e61', 'he', 'general', 'light', 'מקלחת מוקדמת הערב, תושבי רמת גן', 'בשכונות אחדות לא יהיו מים הלילה בין 23:00–05:00, כי מחליפים צנרת. ממלאים קומקום, והבוקר הכל זורם.'),
  ('1a9a7153-2b6c-55a1-be6a-45a4fc4ec628', 'he', 'general', 'calm', 'עבודות תחזוקה ברכבת בין נהריה לעכו בשני הלילות הקרובים', 'הרכבות בין נהריה לעכו לא יפעלו בשני הלילות הקרובים אחרי 22:00. יופעלו אוטובוסים חלופיים מהתחנות, ובבוקר התנועה תחזור לשגרה.'),
  ('1a9a7153-2b6c-55a1-be6a-45a4fc4ec628', 'he', 'general', 'human', 'נוסעי הלילה בין נהריה לעכו יעברו לאוטובוסים', 'מי שחוזר מאוחר מהעבודה יצטרך לתכנן מחדש בשני הלילות הקרובים. "העיקר שיש הסעה חלופית", אומר נוסע קבוע. הרכבות יחזרו לפעול בבוקר.'),
  ('1a9a7153-2b6c-55a1-be6a-45a4fc4ec628', 'he', 'general', 'informative', 'הרכבת בין נהריה לעכו: הפסקת תנועה בשני הלילות הקרובים מ־22:00', 'בשל עבודות תחזוקה לא יפעלו רכבות בין נהריה לעכו בשני הלילות הקרובים מ־22:00 ועד תחילת השירות בבוקר. אוטובוסים חלופיים ייצאו מהתחנות כל 20 דקות.'),
  ('1a9a7153-2b6c-55a1-be6a-45a4fc4ec628', 'he', 'general', 'light', 'הרכבת לוקחת כמה לילות לטיפוח', 'עבודות תחזוקה בין נהריה לעכו בשני הלילות הקרובים: אחרי 22:00 עוברים לאוטובוסים החלופיים. בבוקר הכל חוזר למסלול.'),
  ('4dfc8a27-0b29-5564-995b-d9de978140be', 'he', 'general', 'calm', 'טלסקופ חלל צילם ענן גז בצורת עין', 'התמונה החדשה מראה ערפילית שבה נולדים כוכבים, במרחק אלפי שנות אור. החוקרים ישתמשו בה כדי להבין איך נוצרות מערכות שמש.'),
  ('4dfc8a27-0b29-5564-995b-d9de978140be', 'he', 'general', 'human', 'אסטרונומית: "ישבתי מול התמונה דקות ארוכות"', 'חוקרים ברחבי העולם התרגשו מתמונה חדשה של ענן גז בצורת עין, שבו נולדים כוכבים. "זה מזכיר לנו כמה היקום יפה", אמרה אחת מהן.'),
  ('4dfc8a27-0b29-5564-995b-d9de978140be', 'he', 'general', 'informative', 'תמונה חדשה: ערפילית בצורת עין במרחק אלפי שנות אור', 'טלסקופ חלל צילם ענן גז ואבק שבו נוצרים כוכבים חדשים. הנתונים יסייעו לחקר היווצרות מערכות שמש. התמונה פורסמה לציבור.'),
  ('4dfc8a27-0b29-5564-995b-d9de978140be', 'he', 'general', 'light', 'היקום שלח לנו גלויה', 'טלסקופ חלל צילם ענן גז בצורת עין, ובתוכו נולדים כוכבים. שווה לחפש את התמונה ולהגדיל על המסך.'),
  ('19a97369-066a-57cd-92a4-f6711f5ea979', 'he', 'general', 'calm', 'ספורטאית פראלימפית צעירה זכתה במדליה בשחייה', 'בתחרות בינלאומית זכתה ספורטאית בת 19 במדליית כסף בשחייה. היא מתאמנת במרכז הספורט הפראלימפי כבר שש שנים.'),
  ('19a97369-066a-57cd-92a4-f6711f5ea979', 'he', 'general', 'human', '"חלמתי על הרגע הזה מגיל 13"', 'ספורטאית פראלימפית בת 19 זכתה במדליית כסף בשחייה בתחרות בינלאומית. המאמנת שלה סיפרה שהיא מתאמנת כל בוקר לפני הלימודים.'),
  ('19a97369-066a-57cd-92a4-f6711f5ea979', 'he', 'general', 'informative', 'מדליית כסף לספורטאית פראלימפית בשחייה', 'הספורטאית, בת 19, סיימה במקום השני בתחרות בינלאומית, בתוצאה אישית הטובה ביותר שלה. זו המדליה הבינלאומית הראשונה שלה.'),
  ('19a97369-066a-57cd-92a4-f6711f5ea979', 'he', 'general', 'light', 'כסף שמרגיש כמו זהב', 'ספורטאית פראלימפית בת 19 זכתה במדליית כסף בשחייה ושברה שיא אישי. הבוקר שלה מתחיל באימון, והשאר היסטוריה.'),
  ('4a6242ca-35d4-5fab-906a-972c720f68cd', 'he', 'general', 'calm', 'כנס בינלאומי על מים וחקלאות נפתח השבוע', 'משלחות מעשרות מדינות דנות בדרכים לחסוך במים בחקלאות. גם חוקרים מישראל מציגים פיתוחים בתחום ההשקיה.'),
  ('4a6242ca-35d4-5fab-906a-972c720f68cd', 'he', 'general', 'human', 'חקלאית מאפריקה: "באתי ללמוד איך משקים בטפטוף"', 'בכנס הבינלאומי על מים וחקלאות נפגשים חקלאים וחוקרים מעשרות מדינות. גם פיתוחים ישראליים בהשקיה מוצגים בו.'),
  ('4a6242ca-35d4-5fab-906a-972c720f68cd', 'he', 'general', 'informative', 'עשרות מדינות בכנס על מחסור במים בחקלאות', 'הכנס עוסק בהשקיה חכמה, בהתפלה ובשימוש חוזר במים. הצהרת סיכום צפויה בסוף השבוע. חברות וחוקרים מישראל מציגים פתרונות השקיה.'),
  ('4a6242ca-35d4-5fab-906a-972c720f68cd', 'he', 'general', 'light', 'העולם צמא לרעיונות', 'בכנס בינלאומי על מים וחקלאות מחפשים איך לגדל יותר עם פחות. גם הטפטפת הישראלית מככבת שם.'),
  ('40f096ad-43c5-535a-a905-e714ef65455d', 'he', 'general', 'calm', 'עבודות תשתית במרכז העיר: שינויים קלים בתנועה', 'העירייה מחליפה צנרת ומדרכות במרכז העיר. הרחוב פתוח להולכי רגל, והתנועה מוסטת לנתיב אחד עד סוף השבוע.'),
  ('40f096ad-43c5-535a-a905-e714ef65455d', 'he', 'general', 'informative', 'מרכז העיר: נתיב אחד סגור עד סוף השבוע', 'עבודות החלפת צנרת ומדרכות. הגישה לחניונים ולבתי העסק נשמרת. העבודות מתבצעות בין 07:00 ל־17:00.'),
  ('64933d61-d50d-584b-90ec-9b1730739155', 'he', 'general', 'calm', 'שיבוש באספקת המים בשכונות המזרחיות של נתניה עד 14:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 14:00. תאגיד המים מציב נקודות חלוקה, והצוותים כבר עובדים בשטח.'),
  ('64933d61-d50d-584b-90ec-9b1730739155', 'he', 'general', 'human', 'תושבים בשכונות המזרחיות של נתניה בלי לחץ מים עד 14:00', 'משפחות בכמה שכונות מתארגנות עם בקבוקים ושכנים. "מילאנו סירים מראש, יהיה בסדר", מספרת תושבת. תאגיד המים מציב נקודות חלוקה.'),
  ('64933d61-d50d-584b-90ec-9b1730739155', 'he', 'general', 'informative', 'נתניה: לחץ מים נמוך בשכונות המזרחיות עד 14:00', 'תקלה בצנרת ראשית פוגעת באספקת המים בשכונות המזרחיות. התיקון צפוי להסתיים עד 14:00. נקודות חלוקת מים פועלות, והפרטים באתר תאגיד המים.'),
  ('64933d61-d50d-584b-90ec-9b1730739155', 'he', 'general', 'light', 'שיבוש באספקת המים בשכונות המזרחיות של נתניה עד 14:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 14:00. תאגיד המים מציב נקודות חלוקה ומעדכן באתר.'),
  ('7cbec8af-46cd-52e4-91a9-08eedc878a18', 'he', 'general', 'calm', 'כביש 90 ייסגר בלילה בין עין גדי לנווה זוהר', 'בגלל עבודות גישור כביש 90 ייסגר הלילה בין עין גדי לנווה זוהר בין 21:00–05:00. התנועה תופנה לדרכים חלופיות מסומנות, ובבוקר הכביש ייפתח כרגיל.'),
  ('7cbec8af-46cd-52e4-91a9-08eedc878a18', 'he', 'general', 'human', 'נהגי המשאיות מתכננים מסלול אחר הלילה', 'כביש 90 ייסגר בין עין גדי לנווה זוהר בין 21:00–05:00. "נצא שעה מוקדם יותר ונעבור בדרך החלופית", אומר נהג הובלות. בבוקר הכביש ייפתח.'),
  ('7cbec8af-46cd-52e4-91a9-08eedc878a18', 'he', 'general', 'informative', 'כביש 90 ייסגר בין עין גדי לנווה זוהר בין 21:00–05:00', 'סגירה לילית לצורך עבודות גישור. התנועה תופנה לדרכים חלופיות עם שילוט. צפויים עיכובים של 15–20 דקות. הפתיחה לפני שעות העומס של הבוקר.'),
  ('7cbec8af-46cd-52e4-91a9-08eedc878a18', 'he', 'general', 'light', 'נהגי לילה, שימו לב: עוקפים הלילה', 'כביש 90 ייסגר בין עין גדי לנווה זוהר בין 21:00–05:00. השלטים יובילו אתכם בדרך חלופית, והבוקר ייפתח בזמן לפקקים הרגילים.'),
  ('dce6a35f-b7db-58cc-a8d9-2c1cac382f66', 'he', 'general', 'calm', 'חם מהרגיל היום, ובערב נעים יותר', 'הטמפרטורות יגיעו לכ־37 מעלות בבקעת הירדן. מספיק לשתות מים ולהישאר בצל בשעות הצהריים. בערב צפויה הקלה.'),
  ('dce6a35f-b7db-58cc-a8d9-2c1cac382f66', 'he', 'general', 'human', 'מי שעובד בחוץ ירגיש את החום היום', 'פועלי בניין, שליחים וחקלאים בבקעת הירדן יפגשו כ־37 מעלות. "אנחנו מתחילים מוקדם ומסיימים לפני הצהריים", מספר מנהל עבודה. בערב צפויה הקלה.'),
  ('dce6a35f-b7db-58cc-a8d9-2c1cac382f66', 'he', 'general', 'informative', '37 מעלות בבקעת הירדן היום, הקלה בערב', 'עומס חום בינוני בבקעת הירדן: עד 37 מעלות בשעות הצהריים. משרד הבריאות ממליץ לשתות באופן קבוע ולהימנע ממאמץ בשמש בין 11:00 ל־16:00.'),
  ('dce6a35f-b7db-58cc-a8d9-2c1cac382f66', 'he', 'general', 'light', 'הכובע והבקבוק חוזרים לתיק', 'היום יהיה חם, עד 37 מעלות בבקעת הירדן. מים קרים, צל טוב ומזגן בטמפרטורה סבירה, והערב כבר יהיה נעים יותר.'),
  ('8acb114a-3f55-50b9-b8b3-b60fa8571933', 'he', 'general', 'calm', 'ספורטאית פראלימפית צעירה זכתה במדליה בחתירה', 'בתחרות בינלאומית זכתה ספורטאית בת 19 במדליית כסף בחתירה. היא מתאמנת במרכז הספורט הפראלימפי כבר שש שנים.'),
  ('8acb114a-3f55-50b9-b8b3-b60fa8571933', 'he', 'general', 'human', '"חלמתי על הרגע הזה מגיל 13"', 'ספורטאית פראלימפית בת 19 זכתה במדליית כסף בחתירה בתחרות בינלאומית. המאמנת שלה סיפרה שהיא מתאמנת כל בוקר לפני הלימודים.'),
  ('8acb114a-3f55-50b9-b8b3-b60fa8571933', 'he', 'general', 'informative', 'מדליית כסף לספורטאית פראלימפית בחתירה', 'הספורטאית, בת 19, סיימה במקום השני בתחרות בינלאומית, בתוצאה אישית הטובה ביותר שלה. זו המדליה הבינלאומית הראשונה שלה.'),
  ('8acb114a-3f55-50b9-b8b3-b60fa8571933', 'he', 'general', 'light', 'כסף שמרגיש כמו זהב', 'ספורטאית פראלימפית בת 19 זכתה במדליית כסף בחתירה ושברה שיא אישי. הבוקר שלה מתחיל באימון, והשאר היסטוריה.'),
  ('b9ecf1e8-d559-5c6c-8e53-53c99740ef47', 'he', 'general', 'calm', 'בית משפט: רשת מרכולים תחזיר ללקוחות חיובים כפולים', 'בית המשפט אישר הסדר בתביעה ייצוגית. הלקוחות שחויבו פעמיים יקבלו זיכוי אוטומטי בחשבון הבא, בלי צורך לפנות.'),
  ('b9ecf1e8-d559-5c6c-8e53-53c99740ef47', 'he', 'general', 'human', 'לקוחה שגילתה חיוב כפול: "חשבתי שזה רק אצלי"', 'בדיקה שגרתית של דף האשראי הובילה לתביעה ייצוגית. עכשיו אישר בית המשפט הסדר: רשת מרכולים תחזיר את הכסף לכל מי שחויב פעמיים.'),
  ('b9ecf1e8-d559-5c6c-8e53-53c99740ef47', 'he', 'general', 'informative', 'הסדר ייצוגי: רשת מרכולים תזכה לקוחות על חיובים כפולים', 'בית המשפט המחוזי אישר את ההסדר. הזיכוי יינתן אוטומטית בחשבון הקרוב. לקוחות לשעבר יקבלו החזר בהעברה בנקאית תוך 90 יום.'),
  ('b9ecf1e8-d559-5c6c-8e53-53c99740ef47', 'he', 'general', 'light', 'חויבתם פעמיים? הכסף חוזר', 'בית משפט אישר הסדר שבו רשת מרכולים מחזירה ללקוחות חיובים כפולים. לא צריך לעשות כלום, רק לבדוק את החשבון הבא.'),
  ('673ddf33-4c82-5c86-b50e-6fe652fee796', 'he', 'general', 'calm', 'ההרשמה לחטיבות הביניים לשנה הבאה תיפתח אחרי החגים', 'הרשויות המקומיות יפרסמו בקרוב את מועדי ההרשמה לחטיבות הביניים. אין צורך למהר: ההרשמה נמשכת כמה שבועות ונעשית באתר הרשות.'),
  ('673ddf33-4c82-5c86-b50e-6fe652fee796', 'he', 'general', 'human', 'הורים מתכוננים להרשמה לחטיבות הביניים', 'בקבוצות ההורים כבר שואלים על מועדים ומסמכים. "הכנתי צילום תעודת זהות מראש", מספר אב לשלושה. ההרשמה תיפתח אחרי החגים באתרי הרשויות.'),
  ('673ddf33-4c82-5c86-b50e-6fe652fee796', 'he', 'general', 'informative', 'הרשמה לחטיבות הביניים: תיפתח אחרי החגים באתרי הרשויות', 'ההרשמה לחטיבות הביניים לשנת הלימודים הבאה תתקיים באתרי הרשויות המקומיות ותימשך כמה שבועות. נדרשים ספח תעודת זהות ואישור כתובת.'),
  ('673ddf33-4c82-5c86-b50e-6fe652fee796', 'he', 'general', 'light', 'הורים, יומן ביד: ההרשמה לחטיבות הביניים מתקרבת', 'אחרי החגים נפתחת ההרשמה לחטיבות הביניים באתרי הרשויות. מכינים ספח תעודת זהות ואישור כתובת, ומסיימים בכמה דקות.'),
  ('f3134d5d-310e-5923-8bc8-897ee91b7e49', 'he', 'general', 'calm', 'תזכורת: טיפולי שיניים לילדים ניתנים בסל הבריאות', 'עד גיל 18 טיפולי שיניים בסיסיים ניתנים בקופות החולים בהשתתפות עצמית נמוכה. אפשר לקבוע תור בחופשה.'),
  ('f3134d5d-310e-5923-8bc8-897ee91b7e49', 'he', 'general', 'human', 'רופאת שיניים: "בחופש ההורים סוף סוף מגיעים"', 'החופשה היא זמן טוב לבדיקה. עד גיל 18 טיפולי שיניים בסיסיים כלולים בסל הבריאות, בהשתתפות עצמית נמוכה.'),
  ('f3134d5d-310e-5923-8bc8-897ee91b7e49', 'he', 'general', 'informative', 'טיפולי שיניים עד גיל 18: מה כלול בסל', 'בדיקות, צילומים, שיננית וסתימות ניתנים בקופות בהשתתפות עצמית נמוכה. יישור שיניים אינו כלול. התור נקבע דרך אתר הקופה.'),
  ('f3134d5d-310e-5923-8bc8-897ee91b7e49', 'he', 'general', 'light', 'החופש הגדול של השיניים', 'עד גיל 18 בדיקה, ניקוי וסתימות כלולים בסל הבריאות. בחופשה יש תורים פנויים, וגם תירוצים פחות טובים.'),
  ('af2f7a2a-5bcd-515e-8e27-afa03ed27d60', 'he', 'general', 'calm', 'הספרייה העירונית בשדרות רוטשילד מוסיפה שעות', 'הספרייה תהיה פתוחה גם בימי שישי בבוקר, ותציע שעת סיפור לילדים בכל יום רביעי.'),
  ('af2f7a2a-5bcd-515e-8e27-afa03ed27d60', 'he', 'general', 'informative', 'שדרות רוטשילד: הספרייה פתוחה גם בשישי, 09:00–12:00', 'השינוי נכנס לתוקף מהשבוע הבא. בנוסף: שעת סיפור לגילאי 3–6 בכל יום רביעי ב־17:00.'),
  ('81383ea2-26ff-548e-81a4-029a2ab10b75', 'he', 'general', 'calm', 'נבחרת הנוער בכדורגל עלתה לשלב הבא באליפות אירופה', 'הנבחרת ניצחה אתמול בשני משחקים רצופים. המשחק הבא ישודר בערוצי הספורט, והשחקנים מספרים שהם ממוקדים ורגועים.'),
  ('81383ea2-26ff-548e-81a4-029a2ab10b75', 'he', 'general', 'human', 'ההורים ביציע לא הפסיקו לשיר', 'נבחרת הנוער בכדורגל עלתה לשלב הבא באליפות אירופה. "הם שיחקו בשביל החברים שלהם בבית", אמר המאמן אחרי הניצחון.'),
  ('81383ea2-26ff-548e-81a4-029a2ab10b75', 'he', 'general', 'informative', 'נבחרת הנוער בכדורגל: עלייה לשלב הבא באליפות אירופה', 'אחרי שני ניצחונות רצופים הבטיחה הנבחרת את מקומה לשלב הבא. המשחק הבא בסוף השבוע ישודר בשידור חי.'),
  ('81383ea2-26ff-548e-81a4-029a2ab10b75', 'he', 'general', 'light', 'הנוער שלנו בכדורגל ממשיך לטפס', 'עוד ניצחון, ועוד שלב: נבחרת הנוער בכדורגל עלתה לשלב הבא באליפות אירופה. הדגלים כבר במרפסות.'),
  ('151317af-ef72-50e0-8788-56405e2ad4d4', 'he', 'general', 'calm', 'הפסקת חשמל יזומה בהרצליה מחר בבוקר', 'חברת החשמל תבצע עבודות תחזוקה בכמה רחובות בהרצליה בין 09:30–12:30. הלקוחות ברחובות האלה קיבלו הודעה, והזרם יחזור בסיום העבודות.'),
  ('151317af-ef72-50e0-8788-56405e2ad4d4', 'he', 'general', 'human', 'עסקים קטנים בהרצליה נערכים לבוקר בלי חשמל', '"נפתח שעתיים אחר כך, זה בסדר", אומרת בעלת בית קפה. חברת החשמל תבצע מחר עבודות תחזוקה בכמה רחובות בין 09:30–12:30.'),
  ('151317af-ef72-50e0-8788-56405e2ad4d4', 'he', 'general', 'informative', 'הרצליה: הפסקת חשמל מתוכננת מחר בין 09:30–12:30', 'העבודות נועדו לשדרג את רשת החשמל לקראת החורף. רשימת הרחובות באתר חברת החשמל. מומלץ לנתק מכשירים רגישים לפני ההפסקה.'),
  ('151317af-ef72-50e0-8788-56405e2ad4d4', 'he', 'general', 'light', 'מחר בבוקר: קפה בחוץ, תושבי הרצליה', 'חברת החשמל משדרגת את הרשת בכמה רחובות בין 09:30–12:30. מנתקים מחשבים רגישים, ובצהריים הכל דולק שוב.'),
  ('4c6991f2-8d9d-505c-8375-b644b97a4d63', 'he', 'general', 'calm', 'גלים גבוהים בשבת: הרחצה בחופים אסורה', 'הים סוער, והמצילים לא יאפשרו כניסה למים. אפשר ליהנות מהחוף מבחוץ, ומחר צפוי שיפור.'),
  ('4c6991f2-8d9d-505c-8375-b644b97a4d63', 'he', 'general', 'human', 'מציל ותיק: "גם שחיינים טובים לא נכנסים היום"', 'הים סוער בשבת, והרחצה בחופים אסורה. "אנחנו על הכיסאות, אבל לא נותנים להיכנס", הוא אומר.'),
  ('4c6991f2-8d9d-505c-8375-b644b97a4d63', 'he', 'general', 'informative', 'בשבת: גובה גלים 2–3 מטרים, איסור רחצה', 'רשות הספנות והנמלים מדווחת על ים גבוה. הרחצה אסורה בכל החופים, והמעגנות סגורות לכלי שיט קטנים.'),
  ('4c6991f2-8d9d-505c-8375-b644b97a4d63', 'he', 'general', 'light', 'הים עושה גלים, אנחנו נשארים על החול', 'גלים של 2–3 מטרים בשבת, והרחצה אסורה. תביאו ספר, תשאירו את הגלשן בבית.'),
  ('11ce1fc7-5206-590c-9b40-546703c57ecd', 'he', 'general', 'calm', 'שנת הלימודים האקדמית תיפתח אחרי החגים', 'האוניברסיטאות והמכללות פותחות את הסמסטר אחרי סוכות. מערכות השעות כבר פורסמו, ורוב הקורסים יתקיימו בקמפוס.'),
  ('11ce1fc7-5206-590c-9b40-546703c57ecd', 'he', 'general', 'human', 'סטודנטים חדשים מחפשים שותפים לדירה', '"פרסמתי בקבוצה ותוך יום היו לי שלוש הצעות", מספרת סטודנטית שנה א׳. הסמסטר נפתח אחרי סוכות.'),
  ('11ce1fc7-5206-590c-9b40-546703c57ecd', 'he', 'general', 'informative', 'הסמסטר האקדמי ייפתח אחרי סוכות', 'מערכות השעות פורסמו באתרי המוסדות. מלגות ומעונות: מועדי הגשה אחרונים בשבועות הקרובים. ימי אוריינטציה לסטודנטים חדשים בשבוע שלפני הפתיחה.'),
  ('11ce1fc7-5206-590c-9b40-546703c57ecd', 'he', 'general', 'light', 'מחברות חדשות, קפה בקמפוס', 'הסמסטר נפתח אחרי סוכות. מי שעוד לא הגיש בקשה למלגה או למעונות, זה הזמן.'),
  ('c7395c31-1c1a-5fd5-8cc7-ede21f2e2774', 'he', 'general', 'calm', 'עבודות הרכבת הקלה בחיפה: שינויי תנועה בשדרות ההסתדרות', 'במשך שבועיים יוצר נתיב אחד בכל כיוון בשדרות ההסתדרות. קווי האוטובוס ממשיכים לפעול, עם תחנות זמניות מסומנות.'),
  ('c7395c31-1c1a-5fd5-8cc7-ede21f2e2774', 'he', 'general', 'human', 'סוחרים בשדרות ההסתדרות מקווים שהעבודות יסתיימו מהר', '"הלקוחות הקבועים מגיעים גם ברגל", מספר בעל חנות. עבודות הרכבת הקלה בחיפה יצמצמו את התנועה בשדרות ההסתדרות במשך שבועיים.'),
  ('c7395c31-1c1a-5fd5-8cc7-ede21f2e2774', 'he', 'general', 'informative', 'חיפה: צמצום נתיבים בשדרות ההסתדרות ל־שבועיים', 'בשל עבודות הרכבת הקלה יפעל נתיב אחד בכל כיוון. תחנות אוטובוס יועתקו זמנית. מומלץ להשתמש בצירים חלופיים בשעות העומס.'),
  ('c7395c31-1c1a-5fd5-8cc7-ede21f2e2774', 'he', 'general', 'light', 'שדרות ההסתדרות על דיאטת נתיבים', 'במשך שבועיים ייסגר נתיב בכל כיוון בגלל עבודות הרכבת הקלה בחיפה. אופניים וקורקינטים, זה הזמן שלכם.'),
  ('628344e3-b3da-5211-911b-c10c003212be', 'he', 'general', 'calm', 'תרגיל מילואים בצפון הסתיים; התנועה בכבישים חוזרת לשגרה', 'התרגיל תוכנן מראש ונמשך שלושה ימים. תנועת כלים צבאיים בכבישי הצפון הסתיימה.'),
  ('628344e3-b3da-5211-911b-c10c003212be', 'he', 'general', 'human', 'משרתי מילואים חזרו הביתה אחרי תרגיל של שלושה ימים', '"הילדים חיכו בשער", מספר משרת מילואים. התרגיל בצפון הסתיים, ותנועת הכלים הצבאיים בכבישים פסקה.'),
  ('628344e3-b3da-5211-911b-c10c003212be', 'he', 'general', 'informative', 'הצבא: תרגיל מילואים מתוכנן בצפון הסתיים', 'התרגיל נמשך שלושה ימים ותרגל מוכנות של יחידות מילואים. תנועת כלים צבאיים בכבישים 90 ו־99 חזרה לשגרה.'),
  ('628344e3-b3da-5211-911b-c10c003212be', 'he', 'general', 'light', 'תרגיל מילואים בצפון הסתיים; התנועה בכבישים חוזרת לשגרה', 'התרגיל תוכנן מראש ונמשך שלושה ימים. תנועת כלים צבאיים בכבישי הצפון הסתיימה.'),
  ('436e836b-0779-58ba-ae07-5fa3fcd9a379', 'he', 'general', 'calm', 'טלסקופ חלל צילם ענן גז בצורת סוס ים', 'התמונה החדשה מראה ערפילית שבה נולדים כוכבים, במרחק אלפי שנות אור. החוקרים ישתמשו בה כדי להבין איך נוצרות מערכות שמש.'),
  ('436e836b-0779-58ba-ae07-5fa3fcd9a379', 'he', 'general', 'human', 'אסטרונומית: "ישבתי מול התמונה דקות ארוכות"', 'חוקרים ברחבי העולם התרגשו מתמונה חדשה של ענן גז בצורת סוס ים, שבו נולדים כוכבים. "זה מזכיר לנו כמה היקום יפה", אמרה אחת מהן.'),
  ('436e836b-0779-58ba-ae07-5fa3fcd9a379', 'he', 'general', 'informative', 'תמונה חדשה: ערפילית בצורת סוס ים במרחק אלפי שנות אור', 'טלסקופ חלל צילם ענן גז ואבק שבו נוצרים כוכבים חדשים. הנתונים יסייעו לחקר היווצרות מערכות שמש. התמונה פורסמה לציבור.'),
  ('436e836b-0779-58ba-ae07-5fa3fcd9a379', 'he', 'general', 'light', 'היקום שלח לנו גלויה', 'טלסקופ חלל צילם ענן גז בצורת סוס ים, ובתוכו נולדים כוכבים. שווה לחפש את התמונה ולהגדיל על המסך.'),
  ('1f64ad75-bc5c-5f19-8790-b29439dc8ff4', 'he', 'general', 'calm', 'טיפת חלב חדשה נפתחה בשכונה ד׳', 'התחנה החדשה משרתת משפחות מהשכונות הסמוכות. אפשר לקבוע תור בטלפון או באתר משרד הבריאות.'),
  ('1f64ad75-bc5c-5f19-8790-b29439dc8ff4', 'he', 'general', 'informative', 'שכונה ד׳: נפתחה תחנת טיפת חלב חדשה', 'התחנה פועלת בימים א׳–ה׳ בין 08:00 ל־14:00, ובימי שלישי גם אחר הצהריים. התורים באתר משרד הבריאות.'),
  ('087082b4-603b-5b4c-a4fa-d6263c28b886', 'he', 'general', 'calm', 'יום הכיפורים: התחבורה הציבורית תופסק בצהריים', 'האוטובוסים והרכבות יפסיקו לפעול בשעות הצהריים ויחזרו לפעול אחרי צאת הצום. הכבישים יהיו ריקים, ומומלץ לתכנן את הנסיעות מוקדם.'),
  ('087082b4-603b-5b4c-a4fa-d6263c28b886', 'he', 'general', 'human', 'נהגי האוטובוסים יוצאים לסיבוב האחרון לפני החג', '"זה הסיבוב הכי שקט בשנה, כולם אומרים גמר חתימה טובה", מספר נהג. התחבורה הציבורית תופסק בצהריים ותחזור אחרי צאת הצום.'),
  ('087082b4-603b-5b4c-a4fa-d6263c28b886', 'he', 'general', 'informative', 'יום הכיפורים: הרכבות והאוטובוסים עוצרים בצהריים', 'הרכבת האחרונה תצא בסביבות 14:00, והאוטובוסים יפסיקו לפעול בהדרגה עד 15:00. השירות יתחדש במוצאי החג, כשעה אחרי צאת הצום.'),
  ('087082b4-603b-5b4c-a4fa-d6263c28b886', 'he', 'general', 'light', 'יום הכיפורים: התחבורה הציבורית תופסק בצהריים', 'הרכבות והאוטובוסים יפסיקו לפעול בצהריים ויחזרו אחרי צאת הצום. כדאי לתכנן את הנסיעות מוקדם.'),
  ('456ada7b-b86e-5888-a856-f374193e4625', 'he', 'general', 'calm', 'לקראת הצום: מי צריך להתייעץ עם רופא', 'חולים כרוניים, נשים בהריון ומי שנוטל תרופות באופן קבוע מתבקשים להתייעץ עם רופא לפני הצום. לכל השאר: לשתות הרבה היום ולאכול ארוחה מאוזנת.'),
  ('456ada7b-b86e-5888-a856-f374193e4625', 'he', 'general', 'human', 'רופאת משפחה: "הרבה מטופלים שואלים אותי השבוע על הצום"', '"אני מסבירה שבריאות קודמת לכל, ושיש פתרונות לכל מצב", היא אומרת. משרד הבריאות ממליץ לחולים כרוניים להתייעץ עם רופא לפני הצום.'),
  ('456ada7b-b86e-5888-a856-f374193e4625', 'he', 'general', 'informative', 'משרד הבריאות: הנחיות לקראת צום יום הכיפורים', 'להרבות בשתייה היום, לאכול ארוחה מפסקת מאוזנת ולהימנע ממאכלים מלוחים. חולי סוכרת, לב וכליות ונשים בהריון צריכים להתייעץ עם רופא.'),
  ('456ada7b-b86e-5888-a856-f374193e4625', 'he', 'general', 'light', 'לקראת הצום: מי צריך להתייעץ עם רופא', 'חולים כרוניים, נשים בהריון ומי שנוטל תרופות באופן קבוע מתבקשים להתייעץ עם רופא לפני הצום. לכל השאר: לשתות הרבה היום.'),
  ('d00306b4-094b-51a9-911f-7b7ca4e2546a', 'he', 'general', 'calm', 'שיבוש באספקת המים במרכז העיר של פתח תקווה עד 15:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 15:00. תאגיד המים מציב נקודות חלוקה, והצוותים כבר עובדים בשטח.'),
  ('d00306b4-094b-51a9-911f-7b7ca4e2546a', 'he', 'general', 'human', 'תושבים במרכז העיר של פתח תקווה בלי לחץ מים עד 15:00', 'משפחות בכמה שכונות מתארגנות עם בקבוקים ושכנים. "מילאנו סירים מראש, יהיה בסדר", מספרת תושבת. תאגיד המים מציב נקודות חלוקה.'),
  ('d00306b4-094b-51a9-911f-7b7ca4e2546a', 'he', 'general', 'informative', 'פתח תקווה: לחץ מים נמוך במרכז העיר עד 15:00', 'תקלה בצנרת ראשית פוגעת באספקת המים במרכז העיר. התיקון צפוי להסתיים עד 15:00. נקודות חלוקת מים פועלות, והפרטים באתר תאגיד המים.'),
  ('d00306b4-094b-51a9-911f-7b7ca4e2546a', 'he', 'general', 'light', 'שיבוש באספקת המים במרכז העיר של פתח תקווה עד 15:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 15:00. תאגיד המים מציב נקודות חלוקה ומעדכן באתר.'),
  ('2701ccc7-77f0-58df-a500-69ce98a9b3ba', 'he', 'general', 'calm', 'מחקר: בינה מלאכותית מזהה מוקדם שינויים בבדיקות עיניים', 'המערכת נבדקה על אלפי צילומי רשתית וזיהתה שינויים מוקדמים בדיוק גבוה. היא לא מחליפה רופא, אלא עוזרת לו להחליט מהר יותר.'),
  ('2701ccc7-77f0-58df-a500-69ce98a9b3ba', 'he', 'general', 'human', 'רופא עיניים: "זה כמו עוד זוג עיניים בחדר"', 'מערכת בינה מלאכותית שנבדקה על אלפי צילומי רשתית עוזרת לזהות שינויים מוקדם. ההחלטה נשארת אצל הרופא.'),
  ('2701ccc7-77f0-58df-a500-69ce98a9b3ba', 'he', 'general', 'informative', 'בינה מלאכותית בבדיקות רשתית: דיוק גבוה בזיהוי מוקדם', 'המחקר בדק אלפי צילומים ומצא שהמערכת מזהה סימנים מוקדמים למחלות עיניים בדיוק דומה לרופאים מומחים. השלב הבא: ניסוי במרפאות.'),
  ('2701ccc7-77f0-58df-a500-69ce98a9b3ba', 'he', 'general', 'light', 'המחשב שרואה טוב', 'מערכת בינה מלאכותית למדה לזהות שינויים מוקדמים בצילומי עיניים. הרופא עדיין מחליט, אבל עכשיו יש לו עוזר.'),
  ('91cd0518-ca59-577d-ad21-e172f3d4b5d6', 'he', 'general', 'calm', 'ליגת העל בכדורגל: המחזור החמישי הושלם', 'שלוש הקבוצות המובילות ניצחו, והפער בצמרת נשאר נקודה אחת. המחזור הבא ייערך אחרי החג.'),
  ('91cd0518-ca59-577d-ad21-e172f3d4b5d6', 'he', 'general', 'human', 'אוהדים חזרו מהמגרש עם חיוך, ועם צרידות', '"שרנו תשעים דקות, שווה כל רגע", מספר אוהד. במחזור החמישי של ליגת העל ניצחו כל הקבוצות המובילות, והצמרת צפופה.'),
  ('91cd0518-ca59-577d-ad21-e172f3d4b5d6', 'he', 'general', 'informative', 'ליגת העל: סיכום המחזור החמישי', 'הקבוצות המובילות ניצחו, והפער בין המקום הראשון לשלישי עומד על נקודה אחת. נכבשו 21 שערים במחזור. המחזור הבא אחרי החג.'),
  ('91cd0518-ca59-577d-ad21-e172f3d4b5d6', 'he', 'general', 'light', 'הצמרת צפופה כמו תור לפלאפל', 'במחזור החמישי ניצחו כל המובילות, ורק נקודה אחת מפרידה בין שלוש הראשונות. אחרי החג ממשיכים.'),
  ('27e8c776-2aeb-5f6e-bb99-fc165e2e5eef', 'he', 'general', 'calm', 'גלים גבוהים מחר: הרחצה בחופים אסורה', 'הים סוער, והמצילים לא יאפשרו כניסה למים. אפשר ליהנות מהחוף מבחוץ, ומחר צפוי שיפור.'),
  ('27e8c776-2aeb-5f6e-bb99-fc165e2e5eef', 'he', 'general', 'human', 'מציל ותיק: "גם שחיינים טובים לא נכנסים היום"', 'הים סוער מחר, והרחצה בחופים אסורה. "אנחנו על הכיסאות, אבל לא נותנים להיכנס", הוא אומר.'),
  ('27e8c776-2aeb-5f6e-bb99-fc165e2e5eef', 'he', 'general', 'informative', 'מחר: גובה גלים 2–3 מטרים, איסור רחצה', 'רשות הספנות והנמלים מדווחת על ים גבוה. הרחצה אסורה בכל החופים, והמעגנות סגורות לכלי שיט קטנים.'),
  ('27e8c776-2aeb-5f6e-bb99-fc165e2e5eef', 'he', 'general', 'light', 'הים עושה גלים, אנחנו נשארים על החול', 'גלים של 2–3 מטרים מחר, והרחצה אסורה. תביאו ספר, תשאירו את הגלשן בבית.'),
  ('dcad61b4-3379-5aef-9a66-dcf9e8221fa3', 'he', 'general', 'calm', 'גן סאקר נפתח מחדש אחרי שיפוץ', 'בפארק נוספו מתקני משחק מוצלים, ברזיות ושבילי הליכה מוארים. הוא פתוח מהבוקר ועד חצות.'),
  ('dcad61b4-3379-5aef-9a66-dcf9e8221fa3', 'he', 'general', 'informative', 'גן סאקר: הפארק נפתח אחרי שיפוץ של חצי שנה', 'נוספו מתקני משחק מוצלים, ברזיות, תאורה בשבילים ופינת כושר. שעות הפעילות: 06:00–24:00.'),
  ('9d030992-c310-5eca-a1aa-645291bf502c', 'he', 'general', 'calm', 'שיבושים בקווי אוטובוס באשדוד עד 11:30', 'בעקבות מחלוקת עבודה אצל אחד המפעילים, חלק מהקווים באשדוד לא יפעלו הבוקר עד 11:30. הרכבת והקווים של שאר המפעילים פועלים כרגיל.'),
  ('9d030992-c310-5eca-a1aa-645291bf502c', 'he', 'general', 'human', 'נוסעים באשדוד מחפשים דרך אחרת לעבודה', 'בתחנות מתארגנים לנסיעות משותפות ולקורקינטים. "יצאתי חצי שעה מוקדם, זה עובד", מספרת סטודנטית. חלק מהקווים לא יפעלו עד 11:30.'),
  ('9d030992-c310-5eca-a1aa-645291bf502c', 'he', 'general', 'informative', 'אשדוד: חלק מקווי האוטובוס מושבתים עד 11:30', 'מחלוקת עבודה אצל מפעיל אחד משביתה חלק מהקווים באשדוד עד 11:30. רשימת הקווים באפליקציות התחבורה. הרכבת ושאר המפעילים פועלים כסדרם.'),
  ('9d030992-c310-5eca-a1aa-645291bf502c', 'he', 'general', 'light', 'שיבושים בקווי אוטובוס באשדוד עד 11:30', 'חלק מהקווים של אחד המפעילים לא יפעלו הבוקר עד 11:30. כדאי לבדוק באפליקציית התחבורה לפני היציאה.'),
  ('49a76d5b-147e-5e64-a66a-1d26dc0dfd31', 'he', 'general', 'calm', 'עבודות מתוכננות: הפסקת מים לילית בנתניה', 'בשכונות אחדות בנתניה לא יהיו מים הלילה בין 00:00–05:00, בשל החלפת צנרת. בבוקר האספקה תחזור כרגיל.'),
  ('49a76d5b-147e-5e64-a66a-1d26dc0dfd31', 'he', 'general', 'human', 'תושבי נתניה ממלאים קומקום לפני השינה', '"שמתי בקבוק ליד המיטה ומילאתי קומקום לקפה של הבוקר", מספר תושב. בשכונות אחדות לא יהיו מים הלילה בין 00:00–05:00.'),
  ('49a76d5b-147e-5e64-a66a-1d26dc0dfd31', 'he', 'general', 'informative', 'נתניה: הפסקת מים מתוכננת בין 00:00–05:00', 'תאגיד המים מחליף צנרת ראשית. ההפסקה הלילה תחול על כמה שכונות, והרשימה המלאה באתר התאגיד. אחרי החידוש ייתכן צבע עכור במים לכמה דקות.'),
  ('49a76d5b-147e-5e64-a66a-1d26dc0dfd31', 'he', 'general', 'light', 'מקלחת מוקדמת הערב, תושבי נתניה', 'בשכונות אחדות לא יהיו מים הלילה בין 00:00–05:00, כי מחליפים צנרת. ממלאים קומקום, והבוקר הכל זורם.'),
  ('86c9bd1a-d04c-5025-b5cd-b2e3ae20af9c', 'he', 'general', 'calm', 'גלים גבוהים היום: הרחצה בחופים אסורה', 'הים סוער, והמצילים לא יאפשרו כניסה למים. אפשר ליהנות מהחוף מבחוץ, ומחר צפוי שיפור.'),
  ('86c9bd1a-d04c-5025-b5cd-b2e3ae20af9c', 'he', 'general', 'human', 'מציל ותיק: "גם שחיינים טובים לא נכנסים היום"', 'הים סוער היום, והרחצה בחופים אסורה. "אנחנו על הכיסאות, אבל לא נותנים להיכנס", הוא אומר.'),
  ('86c9bd1a-d04c-5025-b5cd-b2e3ae20af9c', 'he', 'general', 'informative', 'היום: גובה גלים 2–3 מטרים, איסור רחצה', 'רשות הספנות והנמלים מדווחת על ים גבוה. הרחצה אסורה בכל החופים, והמעגנות סגורות לכלי שיט קטנים.'),
  ('86c9bd1a-d04c-5025-b5cd-b2e3ae20af9c', 'he', 'general', 'light', 'הים עושה גלים, אנחנו נשארים על החול', 'גלים של 2–3 מטרים היום, והרחצה אסורה. תביאו ספר, תשאירו את הגלשן בבית.'),
  ('f20a1c7e-9baf-57ac-adbf-3415d43b6e58', 'he', 'general', 'calm', 'ספורטאית פראלימפית צעירה זכתה במדליה באופניים', 'בתחרות בינלאומית זכתה ספורטאית בת 19 במדליית כסף באופניים. היא מתאמנת במרכז הספורט הפראלימפי כבר שש שנים.'),
  ('f20a1c7e-9baf-57ac-adbf-3415d43b6e58', 'he', 'general', 'human', '"חלמתי על הרגע הזה מגיל 13"', 'ספורטאית פראלימפית בת 19 זכתה במדליית כסף באופניים בתחרות בינלאומית. המאמנת שלה סיפרה שהיא מתאמנת כל בוקר לפני הלימודים.'),
  ('f20a1c7e-9baf-57ac-adbf-3415d43b6e58', 'he', 'general', 'informative', 'מדליית כסף לספורטאית פראלימפית באופניים', 'הספורטאית, בת 19, סיימה במקום השני בתחרות בינלאומית, בתוצאה אישית הטובה ביותר שלה. זו המדליה הבינלאומית הראשונה שלה.'),
  ('f20a1c7e-9baf-57ac-adbf-3415d43b6e58', 'he', 'general', 'light', 'כסף שמרגיש כמו זהב', 'ספורטאית פראלימפית בת 19 זכתה במדליית כסף באופניים ושברה שיא אישי. הבוקר שלה מתחיל באימון, והשאר היסטוריה.'),
  ('94e84537-80ba-5102-9de5-6685432a3560', 'he', 'general', 'calm', 'נפתחה ההרשמה למועד החורף של בחינות הבגרות', 'ההרשמה נעשית דרך בית הספר או באתר משרד החינוך לנבחנים אקסטרניים, ונמשכת כמה שבועות.'),
  ('94e84537-80ba-5102-9de5-6685432a3560', 'he', 'general', 'human', 'תלמידת י״ב: "אני משפרת ציון, והפעם בלי לחץ"', 'מועד החורף מאפשר לשפר ציונים בלי לחכות לקיץ. ההרשמה נפתחה, דרך בית הספר או באתר משרד החינוך.'),
  ('94e84537-80ba-5102-9de5-6685432a3560', 'he', 'general', 'informative', 'בגרות: ההרשמה למועד החורף פתוחה', 'מועד החורף מיועד לשיפור ציונים ולנבחנים אקסטרניים. ההרשמה דרך בית הספר או באתר משרד החינוך. הבחינות ייערכו בינואר ובפברואר.'),
  ('94e84537-80ba-5102-9de5-6685432a3560', 'he', 'general', 'light', 'רוצים לשפר ציון? החורף מחכה', 'ההרשמה למועד החורף של הבגרות פתוחה. יש זמן להתכונן, ואפילו תה חם בזמן הלמידה.'),
  ('96201bc0-9f78-5134-a7ad-b9aae9b2f279', 'he', 'general', 'calm', 'בית משפט: חברת ביטוח תחזיר ללקוחות חיובים כפולים', 'בית המשפט אישר הסדר בתביעה ייצוגית. הלקוחות שחויבו פעמיים יקבלו זיכוי אוטומטי בחשבון הבא, בלי צורך לפנות.'),
  ('96201bc0-9f78-5134-a7ad-b9aae9b2f279', 'he', 'general', 'human', 'לקוחה שגילתה חיוב כפול: "חשבתי שזה רק אצלי"', 'בדיקה שגרתית של דף האשראי הובילה לתביעה ייצוגית. עכשיו אישר בית המשפט הסדר: חברת ביטוח תחזיר את הכסף לכל מי שחויב פעמיים.'),
  ('96201bc0-9f78-5134-a7ad-b9aae9b2f279', 'he', 'general', 'informative', 'הסדר ייצוגי: חברת ביטוח תזכה לקוחות על חיובים כפולים', 'בית המשפט המחוזי אישר את ההסדר. הזיכוי יינתן אוטומטית בחשבון הקרוב. לקוחות לשעבר יקבלו החזר בהעברה בנקאית תוך 90 יום.'),
  ('96201bc0-9f78-5134-a7ad-b9aae9b2f279', 'he', 'general', 'light', 'חויבתם פעמיים? הכסף חוזר', 'בית משפט אישר הסדר שבו חברת ביטוח מחזירה ללקוחות חיובים כפולים. לא צריך לעשות כלום, רק לבדוק את החשבון הבא.'),
  ('77af7da8-c50e-5f3c-b969-65d479933ac8', 'he', 'general', 'calm', 'מחקר: 15 דקות הליכה ביום עושות הבדל', 'חוקרים שעקבו אחר אלפי משתתפים מצאו שהליכה קלה של 15 דקות ביום קשורה לשינה טובה יותר ולמצב רוח יציב. לא צריך ציוד, רק לצאת מהבית.'),
  ('77af7da8-c50e-5f3c-b969-65d479933ac8', 'he', 'general', 'human', '"התחלתי ללכת עם השכנה, ועכשיו אני ישנה טוב יותר"', 'מחקר חדש מאשר את מה שהרבה הולכי ערב מרגישים: 15 דקות הליכה ביום קשורות לשינה טובה ולמצב רוח יציב יותר.'),
  ('77af7da8-c50e-5f3c-b969-65d479933ac8', 'he', 'general', 'informative', 'מחקר: 15 דקות הליכה ביום משפרות שינה', 'במחקר שעקב אחר אלפי מבוגרים במשך שנה, הליכה יומית של 15 דקות נקשרה לשיפור באיכות השינה ולירידה בדיווחים על מתח. הממצאים פורסמו בכתב עת רפואי.'),
  ('77af7da8-c50e-5f3c-b969-65d479933ac8', 'he', 'general', 'light', 'הנעליים כבר ליד הדלת', 'מחקר חדש מצא ש־15 דקות הליכה ביום עוזרות לישון טוב יותר. סיבוב סביב הבלוק נחשב, גם עם עצירה לגלידה.'),
  ('77af7da8-c50e-5f3c-b969-65d479933ac8', 'en', 'general', 'informative', 'Study: 15 minutes of walking a day improves sleep', 'In a study that followed thousands of adults for a year, a daily 15-minute walk was linked to better sleep quality and fewer reports of stress. The findings appeared in a medical journal.'),
  ('77af7da8-c50e-5f3c-b969-65d479933ac8', 'en', 'general', 'calm', 'A short daily walk may help you sleep', 'Researchers found that an easy 15-minute walk each day is linked to better sleep and a steadier mood. No equipment needed.'),
  ('77af7da8-c50e-5f3c-b969-65d479933ac8', 'fr', 'general', 'informative', 'Étude : 15 minutes de marche par jour améliorent le sommeil', 'Selon une étude qui a suivi des milliers d’adultes pendant un an, une marche quotidienne de 15 minutes est associée à un meilleur sommeil et à moins de stress. Les résultats ont paru dans une revue médicale.'),
  ('77af7da8-c50e-5f3c-b969-65d479933ac8', 'fr', 'general', 'calm', 'Une courte marche quotidienne aide à mieux dormir', 'Des chercheurs ont constaté qu’une marche tranquille de 15 minutes par jour va de pair avec un meilleur sommeil et une humeur plus stable.'),
  ('77af7da8-c50e-5f3c-b969-65d479933ac8', 'he', 'youth', 'light', 'סיבוב קטן, שינה גדולה', 'חוקרים מצאו ש־15 דקות הליכה ביום עוזרות לישון טוב יותר. אפשר ללכת עם חברים, עם הכלב או עם מוזיקה.'),
  ('77af7da8-c50e-5f3c-b969-65d479933ac8', 'he', 'youth', 'calm', 'הליכה קצרה עוזרת לישון טוב', 'מחקר חדש מצא שהליכה של 15 דקות ביום קשורה לשינה טובה יותר ולמצב רוח טוב.'),
  ('36cdb547-a853-5306-bd6b-efe34b2e5b12', 'he', 'general', 'calm', 'אחרי הצום: התחבורה הציבורית חוזרת לפעול', 'האוטובוסים והרכבות חוזרים לפעול בהדרגה. בשעה הקרובה צפוי עומס ביציאות מהערים הגדולות, ואחר כך התנועה תחזור לשגרה.'),
  ('36cdb547-a853-5306-bd6b-efe34b2e5b12', 'he', 'general', 'human', 'משפחות חוזרות הביתה אחרי החג', 'בתחנות מתמלאים שוב נוסעים עם תיקים, ובתחנות הדלק תורים קצרים. "צום קל עבר, עכשיו ארוחה", אומר נוסע. התחבורה הציבורית חוזרת בהדרגה.'),
  ('36cdb547-a853-5306-bd6b-efe34b2e5b12', 'he', 'general', 'informative', 'מוצאי יום הכיפורים: חידוש התחבורה הציבורית', 'הרכבות יחזרו לפעול כשעה אחרי צאת הצום, והאוטובוסים בהדרגה. צפוי עומס בכניסות לערים עד 22:00.'),
  ('36cdb547-a853-5306-bd6b-efe34b2e5b12', 'he', 'general', 'light', 'הכבישים מתעוררים', 'התחבורה הציבורית חוזרת לפעול בהדרגה, והכבישים מתמלאים. מי שלא ממהר, יכול לחכות שעה ולנסוע בנחת.'),
  ('d36a1045-f33a-5efe-9922-4a61f32cc2b5', 'he', 'general', 'calm', 'שיבוש באספקת המים בשכונות המערביות של רחובות עד 19:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 19:00. תאגיד המים מציב נקודות חלוקה, והצוותים כבר עובדים בשטח.'),
  ('d36a1045-f33a-5efe-9922-4a61f32cc2b5', 'he', 'general', 'human', 'תושבים בשכונות המערביות של רחובות בלי לחץ מים עד 19:00', 'משפחות בכמה שכונות מתארגנות עם בקבוקים ושכנים. "מילאנו סירים מראש, יהיה בסדר", מספרת תושבת. תאגיד המים מציב נקודות חלוקה.'),
  ('d36a1045-f33a-5efe-9922-4a61f32cc2b5', 'he', 'general', 'informative', 'רחובות: לחץ מים נמוך בשכונות המערביות עד 19:00', 'תקלה בצנרת ראשית פוגעת באספקת המים בשכונות המערביות. התיקון צפוי להסתיים עד 19:00. נקודות חלוקת מים פועלות, והפרטים באתר תאגיד המים.'),
  ('d36a1045-f33a-5efe-9922-4a61f32cc2b5', 'he', 'general', 'light', 'שיבוש באספקת המים בשכונות המערביות של רחובות עד 19:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 19:00. תאגיד המים מציב נקודות חלוקה ומעדכן באתר.'),
  ('08fcd53b-2ed5-5052-b2ec-ef491d7bf944', 'he', 'general', 'calm', 'בית משפט: חברת סלולר תחזיר ללקוחות חיובים כפולים', 'בית המשפט אישר הסדר בתביעה ייצוגית. הלקוחות שחויבו פעמיים יקבלו זיכוי אוטומטי בחשבון הבא, בלי צורך לפנות.'),
  ('08fcd53b-2ed5-5052-b2ec-ef491d7bf944', 'he', 'general', 'human', 'לקוחה שגילתה חיוב כפול: "חשבתי שזה רק אצלי"', 'בדיקה שגרתית של דף האשראי הובילה לתביעה ייצוגית. עכשיו אישר בית המשפט הסדר: חברת סלולר תחזיר את הכסף לכל מי שחויב פעמיים.'),
  ('08fcd53b-2ed5-5052-b2ec-ef491d7bf944', 'he', 'general', 'informative', 'הסדר ייצוגי: חברת סלולר תזכה לקוחות על חיובים כפולים', 'בית המשפט המחוזי אישר את ההסדר. הזיכוי יינתן אוטומטית בחשבון הקרוב. לקוחות לשעבר יקבלו החזר בהעברה בנקאית תוך 90 יום.'),
  ('08fcd53b-2ed5-5052-b2ec-ef491d7bf944', 'he', 'general', 'light', 'חויבתם פעמיים? הכסף חוזר', 'בית משפט אישר הסדר שבו חברת סלולר מחזירה ללקוחות חיובים כפולים. לא צריך לעשות כלום, רק לבדוק את החשבון הבא.'),
  ('165a2800-94e5-50b5-83f2-b57259b9b061', 'he', 'general', 'calm', 'לילות קרירים יותר בסוף השבוע', 'הטמפרטורות בלילה יירדו בכמה מעלות, בעיקר בהרים. ביום יהיה נעים עד חם, ללא שינוי מיוחד.'),
  ('165a2800-94e5-50b5-83f2-b57259b9b061', 'he', 'general', 'human', 'בירושלים כבר מוציאים שמיכה דקה', '"בלילה פתחתי חלון והרגשתי את הסתיו", מספר תושב. בסוף השבוע הלילות יהיו קרירים יותר, בעיקר בהרים.'),
  ('165a2800-94e5-50b5-83f2-b57259b9b061', 'he', 'general', 'informative', 'תחזית: ירידה בטמפרטורות הלילה בסוף השבוע', 'בהרים ירדו הטמפרטורות בלילה ל־16–18 מעלות, ובמישור החוף ל־21–23. ביום: נאה עד חם. אין צפי לגשם.'),
  ('165a2800-94e5-50b5-83f2-b57259b9b061', 'he', 'general', 'light', 'הסתיו שולח הודעה ראשונה', 'בסוף השבוע הלילות יהיו קרירים יותר, בעיקר בהרים. זה הרגע להוציא את השמיכה הדקה מהארון.'),
  ('3b11ad65-55cc-56a2-9c12-7e9fe748f2b5', 'he', 'general', 'calm', 'ליגת העל בכדורגל: המחזור הרביעי הושלם', 'שלוש הקבוצות המובילות ניצחו, והפער בצמרת נשאר נקודה אחת. המחזור הבא ייערך אחרי החג.'),
  ('3b11ad65-55cc-56a2-9c12-7e9fe748f2b5', 'he', 'general', 'human', 'אוהדים חזרו מהמגרש עם חיוך, ועם צרידות', '"שרנו תשעים דקות, שווה כל רגע", מספר אוהד. במחזור הרביעי של ליגת העל ניצחו כל הקבוצות המובילות, והצמרת צפופה.'),
  ('3b11ad65-55cc-56a2-9c12-7e9fe748f2b5', 'he', 'general', 'informative', 'ליגת העל: סיכום המחזור הרביעי', 'הקבוצות המובילות ניצחו, והפער בין המקום הראשון לשלישי עומד על נקודה אחת. נכבשו 21 שערים במחזור. המחזור הבא אחרי החג.'),
  ('3b11ad65-55cc-56a2-9c12-7e9fe748f2b5', 'he', 'general', 'light', 'הצמרת צפופה כמו תור לפלאפל', 'במחזור הרביעי ניצחו כל המובילות, ורק נקודה אחת מפרידה בין שלוש הראשונות. אחרי החג ממשיכים.'),
  ('345a8246-7d1c-51e1-b93c-f7e6f7fd0b88', 'he', 'general', 'calm', 'מחיר הדלק יירד מעט בתחילת החודש', 'השינוי קטן, כמה אגורות לליטר. אין סיבה לרוץ לתחנה: ההבדל במילוי מיכל ממוצע הוא שקלים בודדים.'),
  ('345a8246-7d1c-51e1-b93c-f7e6f7fd0b88', 'he', 'general', 'human', 'נהגי מוניות עוקבים אחרי מחיר הדלק', 'בתחילת החודש מחיר הדלק יירד בכמה אגורות. "כל אגורה מורגשת בסוף החודש", אומר נהג מונית ותיק.'),
  ('345a8246-7d1c-51e1-b93c-f7e6f7fd0b88', 'he', 'general', 'informative', 'מחיר בנזין 95 יירד בכמה אגורות לליטר', 'העדכון החודשי נכנס לתוקף בחצות שבין החודשים. השינוי נובע ממחירי הנפט העולמיים ומשער החליפין. המחיר בשירות מלא גבוה יותר.'),
  ('345a8246-7d1c-51e1-b93c-f7e6f7fd0b88', 'he', 'general', 'light', 'הדלק זז קצת, הכיס כמעט לא מרגיש', 'בתחילת החודש מחיר הבנזין יירד בכמה אגורות. במיכל מלא מדובר בשקלים בודדים, בערך מחיר של קפה קטן.'),
  ('345a8246-7d1c-51e1-b93c-f7e6f7fd0b88', 'en', 'general', 'informative', 'Petrol price will fall by a few agorot a litre', 'The monthly update takes effect at midnight at the start of the month and reflects world oil prices and the exchange rate. Full-service prices are higher.'),
  ('345a8246-7d1c-51e1-b93c-f7e6f7fd0b88', 'en', 'general', 'calm', 'A small change in fuel prices', 'The price of petrol will fall slightly next month, by a few agorot a litre. For a full tank that means just a few shekels.'),
  ('345a8246-7d1c-51e1-b93c-f7e6f7fd0b88', 'fr', 'general', 'informative', 'Le prix de l’essence baissera de quelques agorot', 'La mise à jour mensuelle entre en vigueur à minuit en début de mois et suit les cours du pétrole et du change. Le service complet est plus cher.'),
  ('345a8246-7d1c-51e1-b93c-f7e6f7fd0b88', 'fr', 'general', 'calm', 'Léger changement du prix de l’essence', 'Le prix de l’essence baissera légèrement le mois prochain, de quelques agorot par litre : quelques shekels pour un plein.'),
  ('81dc4fdc-f18d-5faf-9cd4-f3ed9fdada49', 'he', 'general', 'calm', 'מבצע החיסונים לשפעת נפתח בקופות החולים', 'אפשר לקבוע תור לחיסון בקופות ובחלק מבתי המרקחת, בלי תשלום. החיסון מומלץ לכל הגילים, ובעיקר לבני 65 ומעלה ולמי שיש לו מחלה כרונית.'),
  ('81dc4fdc-f18d-5faf-9cd4-f3ed9fdada49', 'he', 'general', 'human', 'בני 65 ומעלה כבר עומדים בתור לחיסון השפעת', '"אני מתחסנת כל שנה לפני החגים, ככה אני רגועה ליד הנכדים", אומרת גמלאית. המבצע נפתח בכל הקופות, והחיסון ניתן בלי תשלום.'),
  ('81dc4fdc-f18d-5faf-9cd4-f3ed9fdada49', 'he', 'general', 'informative', 'נפתח מבצע חיסוני השפעת לעונת החורף', 'החיסון ניתן בחינם בכל קופות החולים ובבתי מרקחת נבחרים. משרד הבריאות ממליץ להתחסן מגיל חצי שנה, ובמיוחד לבני 65+, להריוניות ולחולים כרוניים.'),
  ('81dc4fdc-f18d-5faf-9cd4-f3ed9fdada49', 'he', 'general', 'light', 'החורף מגיע, וגם חיסון השפעת', 'המבצע נפתח: קובעים תור בקופה או בבית המרקחת, דקה של עקיצה, וחורף רגוע יותר. בלי תשלום.'),
  ('81dc4fdc-f18d-5faf-9cd4-f3ed9fdada49', 'en', 'general', 'informative', 'Flu vaccine campaign opens at the health funds', 'Flu shots are free at all of Israel’s health funds (kupot holim) and at selected pharmacies. The Health Ministry recommends them from six months of age, especially for people over 65, pregnant women and the chronically ill.'),
  ('81dc4fdc-f18d-5faf-9cd4-f3ed9fdada49', 'en', 'general', 'calm', 'Flu shots are now available', 'You can book a free flu vaccine at your health fund or at some pharmacies. It is recommended for everyone, and especially for older adults.'),
  ('81dc4fdc-f18d-5faf-9cd4-f3ed9fdada49', 'fr', 'general', 'informative', 'La campagne de vaccination contre la grippe commence', 'Le vaccin est gratuit dans toutes les caisses maladie (koupot holim) et dans certaines pharmacies. Le ministère de la Santé le recommande dès six mois, surtout après 65 ans, pendant la grossesse et en cas de maladie chronique.'),
  ('81dc4fdc-f18d-5faf-9cd4-f3ed9fdada49', 'fr', 'general', 'calm', 'Le vaccin contre la grippe est disponible', 'Vous pouvez prendre rendez-vous gratuitement auprès de votre caisse maladie ou dans certaines pharmacies. Il est conseillé à tous, en particulier aux seniors.'),
  ('3fd4983f-48b1-5b52-af38-622d7c357125', 'he', 'general', 'calm', 'עבודות מתוכננות: הפסקת מים לילית ברעננה', 'בשכונות אחדות ברעננה לא יהיו מים בלילה שבין שלישי לרביעי בין 22:30–04:30, בשל החלפת צנרת. בבוקר האספקה תחזור כרגיל.'),
  ('3fd4983f-48b1-5b52-af38-622d7c357125', 'he', 'general', 'human', 'תושבי רעננה ממלאים קומקום לפני השינה', '"שמתי בקבוק ליד המיטה ומילאתי קומקום לקפה של הבוקר", מספר תושב. בשכונות אחדות לא יהיו מים בלילה שבין שלישי לרביעי בין 22:30–04:30.'),
  ('3fd4983f-48b1-5b52-af38-622d7c357125', 'he', 'general', 'informative', 'רעננה: הפסקת מים מתוכננת בין 22:30–04:30', 'תאגיד המים מחליף צנרת ראשית. ההפסקה בלילה שבין שלישי לרביעי תחול על כמה שכונות, והרשימה המלאה באתר התאגיד. אחרי החידוש ייתכן צבע עכור במים לכמה דקות.'),
  ('3fd4983f-48b1-5b52-af38-622d7c357125', 'he', 'general', 'light', 'מקלחת מוקדמת הערב, תושבי רעננה', 'בשכונות אחדות לא יהיו מים בלילה שבין שלישי לרביעי בין 22:30–04:30, כי מחליפים צנרת. ממלאים קומקום, והבוקר הכל זורם.'),
  ('7107fc76-da5a-551c-828d-ae337fb98dfd', 'he', 'general', 'calm', 'אובך קל עד בינוני היום', 'ריכוזי אבק גבוהים מהרגיל צפויים בדרום ובמרכז. לרוב האנשים אין צורך לשנות תוכניות; לרגישים מומלץ להפחית מאמץ בחוץ.'),
  ('7107fc76-da5a-551c-828d-ae337fb98dfd', 'he', 'general', 'human', 'אמא לילד עם אסתמה: "היום נשחק בבית"', 'אובך קל עד בינוני צפוי היום בדרום ובמרכז. המשרד להגנת הסביבה ממליץ לרגישים, לחולי לב ולילדים להפחית פעילות בחוץ.'),
  ('7107fc76-da5a-551c-828d-ae337fb98dfd', 'he', 'general', 'informative', 'היום: אובך בדרום ובמרכז, המלצה לרגישים', 'המשרד להגנת הסביבה צופה ריכוזי אבק גבוהים עד שעות הערב. חולי לב, ריאה, מבוגרים וילדים מתבקשים להימנע ממאמץ בחוץ.'),
  ('7107fc76-da5a-551c-828d-ae337fb98dfd', 'he', 'general', 'light', 'השמיים קצת צהובים היום', 'אובך קל עד בינוני בדרום ובמרכז. מי שרגיש, ישחק היום בבית; לכל השאר: לשטוף את הרכב אחר כך.'),
  ('45dde368-5950-5518-8489-bf34b257d8d5', 'he', 'general', 'calm', 'עבודות הרכבת הקלה בתל אביב־יפו: שינויי תנועה בדרך בגין', 'במשך שלושה שבועות יוצר נתיב אחד בכל כיוון בדרך בגין. קווי האוטובוס ממשיכים לפעול, עם תחנות זמניות מסומנות.'),
  ('45dde368-5950-5518-8489-bf34b257d8d5', 'he', 'general', 'human', 'סוחרים בדרך בגין מקווים שהעבודות יסתיימו מהר', '"הלקוחות הקבועים מגיעים גם ברגל", מספר בעל חנות. עבודות הרכבת הקלה בתל אביב־יפו יצמצמו את התנועה בדרך בגין במשך שלושה שבועות.'),
  ('45dde368-5950-5518-8489-bf34b257d8d5', 'he', 'general', 'informative', 'תל אביב־יפו: צמצום נתיבים בדרך בגין ל־שלושה שבועות', 'בשל עבודות הרכבת הקלה יפעל נתיב אחד בכל כיוון. תחנות אוטובוס יועתקו זמנית. מומלץ להשתמש בצירים חלופיים בשעות העומס.'),
  ('45dde368-5950-5518-8489-bf34b257d8d5', 'he', 'general', 'light', 'דרך בגין על דיאטת נתיבים', 'במשך שלושה שבועות ייסגר נתיב בכל כיוון בגלל עבודות הרכבת הקלה בתל אביב־יפו. אופניים וקורקינטים, זה הזמן שלכם.'),
  ('ce5b2372-04d0-561d-97d5-a90767daf565', 'he', 'general', 'calm', 'מרוץ לילה בירושלים: כבישים ייסגרו בערב', 'אלפי רצים ישתתפו במרוץ העירוני. רחובות במרכז העיר ייסגרו בין 19:00–23:00, ומומלץ להגיע ברגל או בתחבורה ציבורית.'),
  ('ce5b2372-04d0-561d-97d5-a90767daf565', 'he', 'general', 'human', 'רצים חובבים מתכוננים למרוץ הלילה בירושלים', '"אני רצה לכבוד אבא שלי, זו השנה הראשונה שלי", מספרת משתתפת. המרוץ יתקיים הערב, וחלק מהרחובות ייסגרו בין 19:00–23:00.'),
  ('ce5b2372-04d0-561d-97d5-a90767daf565', 'he', 'general', 'informative', 'ירושלים: סגירת רחובות בין 19:00–23:00 בשל מרוץ לילה', 'המרוץ העירוני יתקיים במקצים של 5, 10 ו־21 ק״מ. מפת הסגירות מתפרסמת באתר העירייה. קווי אוטובוס יוסטו למסלולים חלופיים.'),
  ('ce5b2372-04d0-561d-97d5-a90767daf565', 'he', 'general', 'light', 'נעלי ריצה, פנסי רחוב, יוצאים לדרך', 'מרוץ הלילה בירושלים חוזר. מי שלא רץ יכול לעודד, ומי שנוהג כדאי שיעקוף: סגירות בין 19:00–23:00.'),
  ('d9f93a58-271e-5d16-a5a6-4c78de35cf11', 'he', 'general', 'calm', 'מוזיאונים יפתחו בחינם בחלק מימי החג', 'מוזיאונים רבים יציעו כניסה חופשית או מוזלת בחול המועד, עם פעילויות לילדים. מומלץ להזמין מקום מראש.'),
  ('d9f93a58-271e-5d16-a5a6-4c78de35cf11', 'he', 'general', 'human', 'משפחות מתכננות סיור מוזיאונים בחג', '"הילדים בוחרים מוזיאון, ואנחנו מביאים סנדוויצ׳ים", מספר אב. מוזיאונים רבים יפתחו בחינם או בהנחה בחול המועד.'),
  ('d9f93a58-271e-5d16-a5a6-4c78de35cf11', 'he', 'general', 'informative', 'חול המועד: כניסה חופשית או מוזלת למוזיאונים', 'רשימת המוזיאונים המשתתפים מתפרסמת באתר משרד התרבות. ברובם נדרשת הזמנה מראש. שעות הפתיחה מורחבות עד 19:00.'),
  ('d9f93a58-271e-5d16-a5a6-4c78de35cf11', 'he', 'general', 'light', 'תרבות בחינם, מזגן כלול', 'מוזיאונים רבים פותחים דלתות בחינם או בהנחה בחג. מזמינים מראש, ומגלים שגם ילדים אוהבים פסלים.'),
  ('cb42e65e-71b9-57fc-be64-568103206e2c', 'he', 'general', 'calm', 'ההרשמה לכיתות א׳ לשנה הבאה תיפתח אחרי החגים', 'הרשויות המקומיות יפרסמו בקרוב את מועדי ההרשמה לכיתות א׳. אין צורך למהר: ההרשמה נמשכת כמה שבועות ונעשית באתר הרשות.'),
  ('cb42e65e-71b9-57fc-be64-568103206e2c', 'he', 'general', 'human', 'הורים מתכוננים להרשמה לכיתות א׳', 'בקבוצות ההורים כבר שואלים על מועדים ומסמכים. "הכנתי צילום תעודת זהות מראש", מספר אב לשלושה. ההרשמה תיפתח אחרי החגים באתרי הרשויות.'),
  ('cb42e65e-71b9-57fc-be64-568103206e2c', 'he', 'general', 'informative', 'הרשמה לכיתות א׳: תיפתח אחרי החגים באתרי הרשויות', 'ההרשמה לכיתות א׳ לשנת הלימודים הבאה תתקיים באתרי הרשויות המקומיות ותימשך כמה שבועות. נדרשים ספח תעודת זהות ואישור כתובת.'),
  ('cb42e65e-71b9-57fc-be64-568103206e2c', 'he', 'general', 'light', 'הורים, יומן ביד: ההרשמה לכיתות א׳ מתקרבת', 'אחרי החגים נפתחת ההרשמה לכיתות א׳ באתרי הרשויות. מכינים ספח תעודת זהות ואישור כתובת, ומסיימים בכמה דקות.'),
  ('cb42e65e-71b9-57fc-be64-568103206e2c', 'en', 'general', 'informative', 'Registration for first grade opens after the holidays', 'Registration for first grade for next school year will take place on local authority websites and run for several weeks. Parents need the ID appendix (sefach) and proof of address.'),
  ('cb42e65e-71b9-57fc-be64-568103206e2c', 'en', 'general', 'calm', 'School registration for first grade is coming up', 'Local authorities will soon announce registration dates for first grade. There is no need to rush: registration stays open for several weeks.'),
  ('cb42e65e-71b9-57fc-be64-568103206e2c', 'fr', 'general', 'informative', 'Inscriptions pour l’entrée en primaire : ouverture après les fêtes', 'Les inscriptions pour l’entrée en primaire pour l’an prochain se feront sur les sites des municipalités pendant plusieurs semaines. Il faut l’annexe de la carte d’identité (sefah) et un justificatif de domicile.'),
  ('cb42e65e-71b9-57fc-be64-568103206e2c', 'fr', 'general', 'calm', 'Les inscriptions pour l’entrée en primaire approchent', 'Les municipalités annonceront bientôt les dates d’inscription pour l’entrée en primaire. Rien ne presse : elles restent ouvertes plusieurs semaines.'),
  ('0e9e7efd-95a5-580b-8b14-3c15a4b75b7f', 'he', 'general', 'calm', 'ערב קהילתי בגן סאקר: הופעה וסדנאות לילדים', 'המתנ״ס מזמין את התושבים לערב פתוח עם מוזיקה, דוכני יצירה ופינת קפה. הכניסה חופשית.'),
  ('0e9e7efd-95a5-580b-8b14-3c15a4b75b7f', 'he', 'general', 'informative', 'גן סאקר: ערב קהילתי פתוח ביום חמישי ב־18:00', 'בתוכנית: הופעה של להקה מקומית, סדנאות יצירה לילדים ודוכנים של עסקים מהשכונה. כניסה חופשית, ללא הרשמה.'),
  ('521e91f0-0eef-577f-a277-cd55a516eaca', 'he', 'general', 'calm', 'שיבוש באספקת המים בשכונות הוותיקות של בית שמש עד 18:30', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 18:30. תאגיד המים מציב נקודות חלוקה, והצוותים כבר עובדים בשטח.'),
  ('521e91f0-0eef-577f-a277-cd55a516eaca', 'he', 'general', 'human', 'תושבים בשכונות הוותיקות של בית שמש בלי לחץ מים עד 18:30', 'משפחות בכמה שכונות מתארגנות עם בקבוקים ושכנים. "מילאנו סירים מראש, יהיה בסדר", מספרת תושבת. תאגיד המים מציב נקודות חלוקה.'),
  ('521e91f0-0eef-577f-a277-cd55a516eaca', 'he', 'general', 'informative', 'בית שמש: לחץ מים נמוך בשכונות הוותיקות עד 18:30', 'תקלה בצנרת ראשית פוגעת באספקת המים בשכונות הוותיקות. התיקון צפוי להסתיים עד 18:30. נקודות חלוקת מים פועלות, והפרטים באתר תאגיד המים.'),
  ('521e91f0-0eef-577f-a277-cd55a516eaca', 'he', 'general', 'light', 'שיבוש באספקת המים בשכונות הוותיקות של בית שמש עד 18:30', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 18:30. תאגיד המים מציב נקודות חלוקה ומעדכן באתר.'),
  ('deb02445-c922-5291-8821-fdad19ebd757', 'he', 'general', 'calm', 'חם מהרגיל היום, ובערב נעים יותר', 'הטמפרטורות יגיעו לכ־38 מעלות בערבה ובאילת. מספיק לשתות מים ולהישאר בצל בשעות הצהריים. בערב צפויה הקלה.'),
  ('deb02445-c922-5291-8821-fdad19ebd757', 'he', 'general', 'human', 'מי שעובד בחוץ ירגיש את החום היום', 'פועלי בניין, שליחים וחקלאים בערבה ובאילת יפגשו כ־38 מעלות. "אנחנו מתחילים מוקדם ומסיימים לפני הצהריים", מספר מנהל עבודה. בערב צפויה הקלה.'),
  ('deb02445-c922-5291-8821-fdad19ebd757', 'he', 'general', 'informative', '38 מעלות בערבה ובאילת היום, הקלה בערב', 'עומס חום בינוני בערבה ובאילת: עד 38 מעלות בשעות הצהריים. משרד הבריאות ממליץ לשתות באופן קבוע ולהימנע ממאמץ בשמש בין 11:00 ל־16:00.'),
  ('deb02445-c922-5291-8821-fdad19ebd757', 'he', 'general', 'light', 'הכובע והבקבוק חוזרים לתיק', 'היום יהיה חם, עד 38 מעלות בערבה ובאילת. מים קרים, צל טוב ומזגן בטמפרטורה סבירה, והערב כבר יהיה נעים יותר.'),
  ('91819efd-5d39-5703-b507-3d4118212424', 'he', 'general', 'calm', 'אכיפה מוגברת בכבישים לקראת החגים', 'המשטרה תציב יותר ניידות ומצלמות בכבישים הבין־עירוניים. מומלץ לצאת מוקדם, לעצור למנוחה ולהקפיד על מרחק.'),
  ('91819efd-5d39-5703-b507-3d4118212424', 'he', 'general', 'human', 'שוטר תנועה: "המטרה שכולם יגיעו לארוחת החג"', 'לקראת נסיעות החג המשטרה מגבירה את האכיפה. "אנחנו רואים הרבה עייפות בנסיעות ארוכות", הוא אומר. מומלץ לעצור למנוחה.'),
  ('91819efd-5d39-5703-b507-3d4118212424', 'he', 'general', 'informative', 'המשטרה: מבצע אכיפה בכבישים בתקופת החגים', 'יוצבו ניידות ומצלמות מהירות נוספות בכבישים הבין־עירוניים. דגש על מהירות, שמירת מרחק ושימוש בטלפון בזמן נהיגה.'),
  ('91819efd-5d39-5703-b507-3d4118212424', 'he', 'general', 'light', 'בדרך לסבתא, בלי למהר', 'המשטרה מגבירה אכיפה בכבישים לקראת החגים. יוצאים מוקדם, עוצרים לקפה, ומגיעים בזמן לקידוש.'),
  ('8001f63e-e8d0-5b48-9c24-7b4fd38b0306', 'he', 'general', 'calm', 'ליגת העל בכדורגל: המחזור השני הושלם', 'שלוש הקבוצות המובילות ניצחו, והפער בצמרת נשאר נקודה אחת. המחזור הבא ייערך אחרי החג.'),
  ('8001f63e-e8d0-5b48-9c24-7b4fd38b0306', 'he', 'general', 'human', 'אוהדים חזרו מהמגרש עם חיוך, ועם צרידות', '"שרנו תשעים דקות, שווה כל רגע", מספר אוהד. במחזור השני של ליגת העל ניצחו כל הקבוצות המובילות, והצמרת צפופה.'),
  ('8001f63e-e8d0-5b48-9c24-7b4fd38b0306', 'he', 'general', 'informative', 'ליגת העל: סיכום המחזור השני', 'הקבוצות המובילות ניצחו, והפער בין המקום הראשון לשלישי עומד על נקודה אחת. נכבשו 21 שערים במחזור. המחזור הבא אחרי החג.'),
  ('8001f63e-e8d0-5b48-9c24-7b4fd38b0306', 'he', 'general', 'light', 'הצמרת צפופה כמו תור לפלאפל', 'במחזור השני ניצחו כל המובילות, ורק נקודה אחת מפרידה בין שלוש הראשונות. אחרי החג ממשיכים.'),
  ('bd172465-2216-5aa6-b89a-289476164532', 'he', 'general', 'calm', 'ההרשמה לגני הילדים לשנה הבאה תיפתח אחרי החגים', 'הרשויות המקומיות יפרסמו בקרוב את מועדי ההרשמה לגני הילדים. אין צורך למהר: ההרשמה נמשכת כמה שבועות ונעשית באתר הרשות.'),
  ('bd172465-2216-5aa6-b89a-289476164532', 'he', 'general', 'human', 'הורים מתכוננים להרשמה לגני הילדים', 'בקבוצות ההורים כבר שואלים על מועדים ומסמכים. "הכנתי צילום תעודת זהות מראש", מספר אב לשלושה. ההרשמה תיפתח אחרי החגים באתרי הרשויות.'),
  ('bd172465-2216-5aa6-b89a-289476164532', 'he', 'general', 'informative', 'הרשמה לגני הילדים: תיפתח אחרי החגים באתרי הרשויות', 'ההרשמה לגני הילדים לשנת הלימודים הבאה תתקיים באתרי הרשויות המקומיות ותימשך כמה שבועות. נדרשים ספח תעודת זהות ואישור כתובת.'),
  ('bd172465-2216-5aa6-b89a-289476164532', 'he', 'general', 'light', 'הורים, יומן ביד: ההרשמה לגני הילדים מתקרבת', 'אחרי החגים נפתחת ההרשמה לגני הילדים באתרי הרשויות. מכינים ספח תעודת זהות ואישור כתובת, ומסיימים בכמה דקות.'),
  ('bd172465-2216-5aa6-b89a-289476164532', 'en', 'general', 'informative', 'Registration for municipal kindergartens opens after the holidays', 'Registration for municipal kindergartens for next school year will take place on local authority websites and run for several weeks. Parents need the ID appendix (sefach) and proof of address.'),
  ('bd172465-2216-5aa6-b89a-289476164532', 'en', 'general', 'calm', 'School registration for municipal kindergartens is coming up', 'Local authorities will soon announce registration dates for municipal kindergartens. There is no need to rush: registration stays open for several weeks.'),
  ('bd172465-2216-5aa6-b89a-289476164532', 'fr', 'general', 'informative', 'Inscriptions pour les jardins d’enfants municipaux : ouverture après les fêtes', 'Les inscriptions pour les jardins d’enfants municipaux pour l’an prochain se feront sur les sites des municipalités pendant plusieurs semaines. Il faut l’annexe de la carte d’identité (sefah) et un justificatif de domicile.'),
  ('bd172465-2216-5aa6-b89a-289476164532', 'fr', 'general', 'calm', 'Les inscriptions pour les jardins d’enfants municipaux approchent', 'Les municipalités annonceront bientôt les dates d’inscription pour les jardins d’enfants municipaux. Rien ne presse : elles restent ouvertes plusieurs semaines.'),
  ('d9086ecb-0b66-55c3-b008-53eeb8732b9a', 'he', 'general', 'calm', 'ליגת העל בכדורגל: המחזור השישי הושלם', 'שלוש הקבוצות המובילות ניצחו, והפער בצמרת נשאר נקודה אחת. המחזור הבא ייערך אחרי החג.'),
  ('d9086ecb-0b66-55c3-b008-53eeb8732b9a', 'he', 'general', 'human', 'אוהדים חזרו מהמגרש עם חיוך, ועם צרידות', '"שרנו תשעים דקות, שווה כל רגע", מספר אוהד. במחזור השישי של ליגת העל ניצחו כל הקבוצות המובילות, והצמרת צפופה.'),
  ('d9086ecb-0b66-55c3-b008-53eeb8732b9a', 'he', 'general', 'informative', 'ליגת העל: סיכום המחזור השישי', 'הקבוצות המובילות ניצחו, והפער בין המקום הראשון לשלישי עומד על נקודה אחת. נכבשו 21 שערים במחזור. המחזור הבא אחרי החג.'),
  ('d9086ecb-0b66-55c3-b008-53eeb8732b9a', 'he', 'general', 'light', 'הצמרת צפופה כמו תור לפלאפל', 'במחזור השישי ניצחו כל המובילות, ורק נקודה אחת מפרידה בין שלוש הראשונות. אחרי החג ממשיכים.'),
  ('1e7b5467-5b9d-51e2-8107-f864affa314a', 'he', 'general', 'calm', 'כביש 4 ייסגר בלילה בין אשדוד לגן יבנה', 'בגלל עבודות גישור כביש 4 ייסגר הלילה בין אשדוד לגן יבנה בין 22:30–05:00. התנועה תופנה לדרכים חלופיות מסומנות, ובבוקר הכביש ייפתח כרגיל.'),
  ('1e7b5467-5b9d-51e2-8107-f864affa314a', 'he', 'general', 'human', 'נהגי המשאיות מתכננים מסלול אחר הלילה', 'כביש 4 ייסגר בין אשדוד לגן יבנה בין 22:30–05:00. "נצא שעה מוקדם יותר ונעבור בדרך החלופית", אומר נהג הובלות. בבוקר הכביש ייפתח.'),
  ('1e7b5467-5b9d-51e2-8107-f864affa314a', 'he', 'general', 'informative', 'כביש 4 ייסגר בין אשדוד לגן יבנה בין 22:30–05:00', 'סגירה לילית לצורך עבודות גישור. התנועה תופנה לדרכים חלופיות עם שילוט. צפויים עיכובים של 15–20 דקות. הפתיחה לפני שעות העומס של הבוקר.'),
  ('1e7b5467-5b9d-51e2-8107-f864affa314a', 'he', 'general', 'light', 'נהגי לילה, שימו לב: עוקפים הלילה', 'כביש 4 ייסגר בין אשדוד לגן יבנה בין 22:30–05:00. השלטים יובילו אתכם בדרך חלופית, והבוקר ייפתח בזמן לפקקים הרגילים.'),
  ('9eaa9f2a-db8e-54d3-b2a1-f1a24a4fb52e', 'he', 'general', 'calm', 'אובך קל עד בינוני בשעות אחר הצהריים', 'ריכוזי אבק גבוהים מהרגיל צפויים בדרום ובמרכז. לרוב האנשים אין צורך לשנות תוכניות; לרגישים מומלץ להפחית מאמץ בחוץ.'),
  ('9eaa9f2a-db8e-54d3-b2a1-f1a24a4fb52e', 'he', 'general', 'human', 'אמא לילד עם אסתמה: "היום נשחק בבית"', 'אובך קל עד בינוני צפוי בשעות אחר הצהריים בדרום ובמרכז. המשרד להגנת הסביבה ממליץ לרגישים, לחולי לב ולילדים להפחית פעילות בחוץ.'),
  ('9eaa9f2a-db8e-54d3-b2a1-f1a24a4fb52e', 'he', 'general', 'informative', 'בשעות אחר הצהריים: אובך בדרום ובמרכז, המלצה לרגישים', 'המשרד להגנת הסביבה צופה ריכוזי אבק גבוהים עד שעות הערב. חולי לב, ריאה, מבוגרים וילדים מתבקשים להימנע ממאמץ בחוץ.'),
  ('9eaa9f2a-db8e-54d3-b2a1-f1a24a4fb52e', 'he', 'general', 'light', 'השמיים קצת צהובים בשעות אחר הצהריים', 'אובך קל עד בינוני בדרום ובמרכז. מי שרגיש, ישחק היום בבית; לכל השאר: לשטוף את הרכב אחר כך.'),
  ('047ac5cd-7b4b-5a44-8cd7-f2c142685429', 'he', 'general', 'calm', 'עבודות מתוכננות: הפסקת מים לילית בהרצליה', 'בשכונות אחדות בהרצליה לא יהיו מים בלילה שבין ראשון לשני בין 22:00–04:30, בשל החלפת צנרת. בבוקר האספקה תחזור כרגיל.'),
  ('047ac5cd-7b4b-5a44-8cd7-f2c142685429', 'he', 'general', 'human', 'תושבי הרצליה ממלאים קומקום לפני השינה', '"שמתי בקבוק ליד המיטה ומילאתי קומקום לקפה של הבוקר", מספר תושב. בשכונות אחדות לא יהיו מים בלילה שבין ראשון לשני בין 22:00–04:30.'),
  ('047ac5cd-7b4b-5a44-8cd7-f2c142685429', 'he', 'general', 'informative', 'הרצליה: הפסקת מים מתוכננת בין 22:00–04:30', 'תאגיד המים מחליף צנרת ראשית. ההפסקה בלילה שבין ראשון לשני תחול על כמה שכונות, והרשימה המלאה באתר התאגיד. אחרי החידוש ייתכן צבע עכור במים לכמה דקות.'),
  ('047ac5cd-7b4b-5a44-8cd7-f2c142685429', 'he', 'general', 'light', 'מקלחת מוקדמת הערב, תושבי הרצליה', 'בשכונות אחדות לא יהיו מים בלילה שבין ראשון לשני בין 22:00–04:30, כי מחליפים צנרת. ממלאים קומקום, והבוקר הכל זורם.'),
  ('cf5060b6-c131-521b-8078-b504fc28233d', 'he', 'general', 'calm', 'חופשת סוכות: הלימודים יתחדשו אחרי שמחת תורה', 'בתי הספר והגנים יוצאים לחופשת החג. במהלכה פועלות ברשויות רבות קייטנות קצרות, והפרטים באתרי הרשויות.'),
  ('cf5060b6-c131-521b-8078-b504fc28233d', 'he', 'general', 'human', 'ילדים בחופש, הורים מחפשים סידורים', 'החופשה ארוכה, וההורים מתחלקים בימים ובסבים. "סידרנו לוח משמרות משפחתי", צוחקת אם לשניים. ברשויות רבות פועלות קייטנות קצרות.'),
  ('cf5060b6-c131-521b-8078-b504fc28233d', 'he', 'general', 'informative', 'חופשת סוכות מתחילה; חזרה ללימודים אחרי שמחת תורה', 'מוסדות החינוך סגורים מערב החג ועד אחרי שמחת תורה. רשויות רבות מפעילות קייטנות חג בימי החול המועד. ההרשמה באתרי הרשויות.'),
  ('cf5060b6-c131-521b-8078-b504fc28233d', 'he', 'general', 'light', 'התיקים הולכים לנוח בארון', 'חופשת סוכות יצאה לדרך: בלי צלצולים עד אחרי שמחת תורה. להורים שמחפשים תוכנית, יש קייטנות חג ברשויות רבות.'),
  ('cf5060b6-c131-521b-8078-b504fc28233d', 'en', 'general', 'informative', 'Sukkot school break begins; classes resume after Simchat Torah', 'Schools and kindergartens are closed from the eve of Sukkot until after Simchat Torah. Many local authorities run short holiday day camps during the intermediate days.'),
  ('cf5060b6-c131-521b-8078-b504fc28233d', 'en', 'general', 'calm', 'Schools are on Sukkot break', 'Classes resume after Simchat Torah. Many towns offer short holiday day camps; details are on the local authority websites.'),
  ('cf5060b6-c131-521b-8078-b504fc28233d', 'fr', 'general', 'informative', 'Vacances de Souccot : reprise après Simhat Torah', 'Écoles et jardins d’enfants ferment de la veille de Souccot jusqu’après Simhat Torah. De nombreuses municipalités proposent des centres de loisirs pendant les demi-fêtes.'),
  ('cf5060b6-c131-521b-8078-b504fc28233d', 'fr', 'general', 'calm', 'Les écoles sont en vacances de Souccot', 'Les cours reprennent après Simhat Torah. Beaucoup de villes organisent de courts centres de loisirs ; les détails sont sur leurs sites.'),
  ('cf5060b6-c131-521b-8078-b504fc28233d', 'he', 'youth', 'light', 'חופש! נתראה אחרי שמחת תורה', 'חופשת סוכות התחילה. זה זמן טוב לקשט סוכה, לפגוש חברים ולישון קצת יותר בבוקר.'),
  ('cf5060b6-c131-521b-8078-b504fc28233d', 'he', 'youth', 'calm', 'חופשת סוכות התחילה', 'אין לימודים עד אחרי שמחת תורה. ברשויות רבות יש קייטנות קצרות בחול המועד.'),
  ('79d5ff4d-6c7b-57c5-a5c9-ce68e00dc6a3', 'he', 'general', 'calm', 'עבודות תשתית בשכונת קטמונים: שינויים קלים בתנועה', 'העירייה מחליפה צנרת ומדרכות בשכונת קטמונים. הרחוב פתוח להולכי רגל, והתנועה מוסטת לנתיב אחד עד סוף השבוע.'),
  ('79d5ff4d-6c7b-57c5-a5c9-ce68e00dc6a3', 'he', 'general', 'informative', 'שכונת קטמונים: נתיב אחד סגור עד סוף השבוע', 'עבודות החלפת צנרת ומדרכות. הגישה לחניונים ולבתי העסק נשמרת. העבודות מתבצעות בין 07:00 ל־17:00.'),
  ('af52179f-8533-5b9a-bec8-a6fcfd4841c6', 'he', 'general', 'calm', 'עבודות תשתית ברחוב יפו: שינויים קלים בתנועה', 'העירייה מחליפה צנרת ומדרכות ברחוב יפו. הרחוב פתוח להולכי רגל, והתנועה מוסטת לנתיב אחד עד סוף השבוע.'),
  ('af52179f-8533-5b9a-bec8-a6fcfd4841c6', 'he', 'general', 'informative', 'רחוב יפו: נתיב אחד סגור עד סוף השבוע', 'עבודות החלפת צנרת ומדרכות. הגישה לחניונים ולבתי העסק נשמרת. העבודות מתבצעות בין 07:00 ל־17:00.'),
  ('ee3fadca-88ee-543d-9660-791a231fe477', 'he', 'general', 'calm', 'שיבוש באספקת המים בשכונות הכרמל של חיפה עד 16:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 16:00. תאגיד המים מציב נקודות חלוקה, והצוותים כבר עובדים בשטח.'),
  ('ee3fadca-88ee-543d-9660-791a231fe477', 'he', 'general', 'human', 'תושבים בשכונות הכרמל של חיפה בלי לחץ מים עד 16:00', 'משפחות בכמה שכונות מתארגנות עם בקבוקים ושכנים. "מילאנו סירים מראש, יהיה בסדר", מספרת תושבת. תאגיד המים מציב נקודות חלוקה.'),
  ('ee3fadca-88ee-543d-9660-791a231fe477', 'he', 'general', 'informative', 'חיפה: לחץ מים נמוך בשכונות הכרמל עד 16:00', 'תקלה בצנרת ראשית פוגעת באספקת המים בשכונות הכרמל. התיקון צפוי להסתיים עד 16:00. נקודות חלוקת מים פועלות, והפרטים באתר תאגיד המים.'),
  ('ee3fadca-88ee-543d-9660-791a231fe477', 'he', 'general', 'light', 'שיבוש באספקת המים בשכונות הכרמל של חיפה עד 16:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 16:00. תאגיד המים מציב נקודות חלוקה ומעדכן באתר.'),
  ('ee3fadca-88ee-543d-9660-791a231fe477', 'en', 'general', 'informative', 'Haifa: low water pressure in the Carmel neighbourhoods until 16:00', 'A fault in a main pipe is disrupting the water supply in the Carmel neighbourhoods. Repairs are expected to finish by 16:00; the municipal water company has set up distribution points.'),
  ('ee3fadca-88ee-543d-9660-791a231fe477', 'en', 'general', 'calm', 'Water supply disrupted in parts of Haifa until 16:00', 'Following a pipe fault, some neighbourhoods in the Carmel neighbourhoods will have low water pressure until 16:00. Crews are on site and water is available at distribution points.'),
  ('ee3fadca-88ee-543d-9660-791a231fe477', 'fr', 'general', 'informative', 'Haïfa : faible pression d’eau dans les quartiers du Carmel jusqu’à 16:00', 'Une panne sur une canalisation principale perturbe l’alimentation en eau dans les quartiers du Carmel. La réparation devrait s’achever vers 16:00 ; des points de distribution sont ouverts.'),
  ('ee3fadca-88ee-543d-9660-791a231fe477', 'fr', 'general', 'calm', 'Perturbation de l’eau à Haïfa jusqu’à 16:00', 'À la suite d’une panne, certains quartiers dans les quartiers du Carmel auront une pression d’eau faible jusqu’à 16:00. Les équipes sont sur place et des points de distribution sont ouverts.'),
  ('72f74623-489a-5623-b2db-7c0135fc329c', 'he', 'general', 'calm', 'פסטיבל סוכות בפארקים של חיפה, בכניסה חופשית', 'בימי חול המועד יתקיימו הופעות, סדנאות ופעילויות לילדים בפארקים בעיר. אין צורך בהרשמה מראש, ומומלץ להגיע בתחבורה ציבורית.'),
  ('72f74623-489a-5623-b2db-7c0135fc329c', 'he', 'general', 'human', 'אמנים מקומיים מכינים את פסטיבל החג בחיפה', '"אנחנו מופיעים בשכונה שבה גדלנו", מספר נגן בלהקה מקומית. בחול המועד יתקיימו הופעות וסדנאות בפארקים, בכניסה חופשית.'),
  ('72f74623-489a-5623-b2db-7c0135fc329c', 'he', 'general', 'informative', 'חיפה: פסטיבל סוכות בפארקים בחול המועד', 'העירייה מפרסמת תוכנייה של הופעות, סדנאות יצירה ופעילויות משפחה בפארקים, בכניסה חופשית. הפעילויות מתקיימות בין 10:00 ל־20:00.'),
  ('72f74623-489a-5623-b2db-7c0135fc329c', 'he', 'general', 'light', 'חול המועד בחיפה: פיקניק, מוזיקה וסדנאות', 'הפארקים בעיר מתמלאים בהופעות ובסדנאות לילדים, בכניסה חופשית. מביאים מחצלת, כובע וסבלנות לחניה.'),
  ('72f74623-489a-5623-b2db-7c0135fc329c', 'en', 'general', 'informative', 'Haifa: free Sukkot festival in the parks', 'The municipality has published a programme of shows, craft workshops and family activities in city parks during the intermediate days of Sukkot, from 10:00 to 20:00. Entry is free.'),
  ('72f74623-489a-5623-b2db-7c0135fc329c', 'en', 'general', 'calm', 'A free Sukkot festival in Haifa', 'Parks across the city will host shows and children’s workshops during the holiday week. No booking is needed; public transport is recommended.'),
  ('72f74623-489a-5623-b2db-7c0135fc329c', 'fr', 'general', 'informative', 'Haïfa : festival de Souccot gratuit dans les parcs', 'La municipalité propose spectacles, ateliers et activités familiales dans les parcs pendant les demi-fêtes de Souccot, de 10 h à 20 h. Entrée libre.'),
  ('72f74623-489a-5623-b2db-7c0135fc329c', 'fr', 'general', 'calm', 'Un festival de Souccot gratuit à Haïfa', 'Les parcs de la ville accueilleront spectacles et ateliers pour enfants pendant la semaine de fête. Sans réservation ; transports en commun conseillés.'),
  ('72f74623-489a-5623-b2db-7c0135fc329c', 'he', 'youth', 'light', 'חול המועד בחיפה: הופעות בפארקים', 'בחופש יהיו בפארקים הופעות, סדנאות ומשחקים, בכניסה חופשית. שווה לתאם עם חברים.'),
  ('72f74623-489a-5623-b2db-7c0135fc329c', 'he', 'youth', 'calm', 'פעילויות חג בפארקים של חיפה', 'בחול המועד יתקיימו הופעות וסדנאות לילדים בפארקים, בלי תשלום.'),
  ('170bd926-1fd7-55c6-8039-aeb2ef701cca', 'he', 'general', 'calm', 'נבחרת הנוער בכדורסל עלתה לשלב הבתים השני באליפות אירופה', 'הנבחרת ניצחה אתמול בשני משחקים רצופים. המשחק הבא ישודר בערוצי הספורט, והשחקנים מספרים שהם ממוקדים ורגועים.'),
  ('170bd926-1fd7-55c6-8039-aeb2ef701cca', 'he', 'general', 'human', 'ההורים ביציע לא הפסיקו לשיר', 'נבחרת הנוער בכדורסל עלתה לשלב הבתים השני באליפות אירופה. "הם שיחקו בשביל החברים שלהם בבית", אמר המאמן אחרי הניצחון.'),
  ('170bd926-1fd7-55c6-8039-aeb2ef701cca', 'he', 'general', 'informative', 'נבחרת הנוער בכדורסל: עלייה לשלב הבתים השני באליפות אירופה', 'אחרי שני ניצחונות רצופים הבטיחה הנבחרת את מקומה לשלב הבתים השני. המשחק הבא בסוף השבוע ישודר בשידור חי.'),
  ('170bd926-1fd7-55c6-8039-aeb2ef701cca', 'he', 'general', 'light', 'הנוער שלנו בכדורסל ממשיך לטפס', 'עוד ניצחון, ועוד שלב: נבחרת הנוער בכדורסל עלתה לשלב הבתים השני באליפות אירופה. הדגלים כבר במרפסות.'),
  ('170bd926-1fd7-55c6-8039-aeb2ef701cca', 'en', 'general', 'informative', 'Israel’s youth basketball team reaches the second group stage', 'After two consecutive wins, the team has secured its place in the second group stage of the European championship. The next match, this weekend, will be broadcast live.'),
  ('170bd926-1fd7-55c6-8039-aeb2ef701cca', 'en', 'general', 'calm', 'Youth basketball team advances in Europe', 'Israel’s youth team has reached the second group stage of the European championship after two wins in a row.'),
  ('170bd926-1fd7-55c6-8039-aeb2ef701cca', 'fr', 'general', 'informative', 'L’équipe israélienne junior de basket-ball en la deuxième phase de groupes', 'Après deux victoires consécutives, l’équipe s’est qualifiée pour la deuxième phase de groupes du championnat d’Europe. Le prochain match, ce week-end, sera diffusé en direct.'),
  ('170bd926-1fd7-55c6-8039-aeb2ef701cca', 'fr', 'general', 'calm', 'L’équipe junior de basket-ball poursuit sa route', 'L’équipe israélienne des jeunes s’est qualifiée pour la deuxième phase de groupes du championnat d’Europe après deux victoires.'),
  ('170bd926-1fd7-55c6-8039-aeb2ef701cca', 'he', 'youth', 'light', 'נבחרת הנוער בכדורסל בדרך למעלה', 'שני ניצחונות ברצף, והנבחרת עלתה לשלב הבתים השני באליפות אירופה. המשחק הבא בסוף השבוע.'),
  ('170bd926-1fd7-55c6-8039-aeb2ef701cca', 'he', 'youth', 'calm', 'הצלחה לנבחרת הנוער בכדורסל', 'הנבחרת עלתה לשלב הבתים השני באליפות אירופה אחרי שני ניצחונות.'),
  ('1f9a7fa7-ce26-50e4-a621-b32eeaa7b8d6', 'he', 'general', 'calm', 'חוקרים בישראל פיתחו חיישן זול לאיתור דליפות מים', 'החיישן מוצמד לצינור ומזהה רעש של דליפה עוד לפני שהיא נראית. הוא נמצא בשלב ניסוי בכמה רשויות, והמטרה היא לחסוך מים בבניינים ישנים.'),
  ('1f9a7fa7-ce26-50e4-a621-b32eeaa7b8d6', 'he', 'general', 'human', 'ועד בית בחולון ניסה את החיישן החדש, ומצא דליפה', '"שנים שילמנו על מים שלא ראינו לאן הם הולכים", מספר חבר ועד. חוקרים ישראלים פיתחו חיישן זול שמזהה דליפות מוקדם.'),
  ('1f9a7fa7-ce26-50e4-a621-b32eeaa7b8d6', 'he', 'general', 'informative', 'חיישן ישראלי מזהה דליפות מים לפי רעש בצנרת', 'המכשיר מבוסס על מיקרופון זעיר ועל תוכנה שמזהה את הצליל של דליפה. הוא נמצא בניסוי בכמה רשויות מקומיות, ועלותו נמוכה מהפתרונות הקיימים.'),
  ('1f9a7fa7-ce26-50e4-a621-b32eeaa7b8d6', 'he', 'general', 'light', 'החיישן ששומע את הצינורות', 'חוקרים ישראלים פיתחו חיישן קטן ש"מקשיב" לצנרת ומגלה דליפות לפני שהתקרה של השכנים מגלה אותן.'),
  ('1f9a7fa7-ce26-50e4-a621-b32eeaa7b8d6', 'en', 'general', 'informative', 'Israeli sensor detects water leaks by sound', 'The device uses a tiny microphone and software that recognises the sound of a leak. It is being piloted by several local authorities and costs less than existing systems.'),
  ('1f9a7fa7-ce26-50e4-a621-b32eeaa7b8d6', 'en', 'general', 'calm', 'A low-cost sensor to find water leaks early', 'Researchers in Israel have developed a small sensor that attaches to a pipe and detects leaks before they become visible. It is being tested in several towns.'),
  ('1f9a7fa7-ce26-50e4-a621-b32eeaa7b8d6', 'fr', 'general', 'informative', 'Un capteur israélien détecte les fuites d’eau au son', 'L’appareil combine un micro miniature et un logiciel qui reconnaît le bruit d’une fuite. Il est testé par plusieurs municipalités et coûte moins cher que les solutions existantes.'),
  ('1f9a7fa7-ce26-50e4-a621-b32eeaa7b8d6', 'fr', 'general', 'calm', 'Un capteur bon marché pour repérer les fuites', 'Des chercheurs en Israël ont mis au point un petit capteur qui se fixe sur un tuyau et détecte les fuites avant qu’elles ne soient visibles.'),
  ('1f9a7fa7-ce26-50e4-a621-b32eeaa7b8d6', 'he', 'youth', 'light', 'המצאה ישראלית: חיישן ששומע דליפות', 'חוקרים בנו חיישן קטן שמקשיב לצינורות ומגלה כשמים בורחים. ככה חוסכים מים, וגם כסף.'),
  ('1f9a7fa7-ce26-50e4-a621-b32eeaa7b8d6', 'he', 'youth', 'calm', 'חיישן חדש שחוסך מים', 'חוקרים בישראל פיתחו חיישן קטן שמזהה דליפות מים בצינורות, עוד לפני שרואים אותן.'),
  ('0099ad03-0d11-5329-9b5f-e2dcb7ec671f', 'he', 'general', 'calm', 'לילות קרירים יותר בשבוע הבא', 'הטמפרטורות בלילה יירדו בכמה מעלות, בעיקר בהרים. ביום יהיה נעים עד חם, ללא שינוי מיוחד.'),
  ('0099ad03-0d11-5329-9b5f-e2dcb7ec671f', 'he', 'general', 'human', 'בירושלים כבר מוציאים שמיכה דקה', '"בלילה פתחתי חלון והרגשתי את הסתיו", מספר תושב. בשבוע הבא הלילות יהיו קרירים יותר, בעיקר בהרים.'),
  ('0099ad03-0d11-5329-9b5f-e2dcb7ec671f', 'he', 'general', 'informative', 'תחזית: ירידה בטמפרטורות הלילה בשבוע הבא', 'בהרים ירדו הטמפרטורות בלילה ל־16–18 מעלות, ובמישור החוף ל־21–23. ביום: נאה עד חם. אין צפי לגשם.'),
  ('0099ad03-0d11-5329-9b5f-e2dcb7ec671f', 'he', 'general', 'light', 'הסתיו שולח הודעה ראשונה', 'בשבוע הבא הלילות יהיו קרירים יותר, בעיקר בהרים. זה הרגע להוציא את השמיכה הדקה מהארון.'),
  ('bc71af52-2c80-5d4e-b3bc-528590d96cfb', 'he', 'general', 'calm', 'רחוב יפו נפתח מחדש אחרי שיפוץ', 'בפארק נוספו מתקני משחק מוצלים, ברזיות ושבילי הליכה מוארים. הוא פתוח מהבוקר ועד חצות.'),
  ('bc71af52-2c80-5d4e-b3bc-528590d96cfb', 'he', 'general', 'informative', 'רחוב יפו: הפארק נפתח אחרי שיפוץ של חצי שנה', 'נוספו מתקני משחק מוצלים, ברזיות, תאורה בשבילים ופינת כושר. שעות הפעילות: 06:00–24:00.'),
  ('92ad4de1-a899-5146-8a11-32129c346230', 'he', 'general', 'calm', 'שווקי ארבעת המינים נפתחו בירושלים', 'הדוכנים פתוחים עד ערב החג. המחירים דומים לשנה שעברה, ומי שמעדיף שקט יכול לקנות בשעות הבוקר המוקדמות.'),
  ('92ad4de1-a899-5146-8a11-32129c346230', 'he', 'general', 'human', 'מוכר אתרוגים ותיק: "כל שנה אותם לקוחות, אותה התרגשות"', 'בשוק ארבעת המינים בירושלים בודקים אתרוגים בזכוכית מגדלת ומתייעצים עם השכנים. הדוכנים פתוחים עד ערב החג.'),
  ('92ad4de1-a899-5146-8a11-32129c346230', 'he', 'general', 'informative', 'ירושלים: שוק ארבעת המינים פתוח עד ערב סוכות', 'עשרות דוכנים פועלים מהבוקר ועד הלילה. סט בסיסי נמכר במחירים דומים לשנה שעברה. בשעות הערב צפוי עומס בכבישי הגישה.'),
  ('92ad4de1-a899-5146-8a11-32129c346230', 'he', 'general', 'light', 'אתרוג, לולב, ובעיקר סבלנות', 'שוק ארבעת המינים בירושלים פתוח. טיפ של ותיקים: מגיעים בבוקר, בודקים בלי לחץ, ומשאירים זמן לקפה.'),
  ('92ad4de1-a899-5146-8a11-32129c346230', 'en', 'general', 'informative', 'Jerusalem: Four Species market open until the eve of Sukkot', 'Dozens of stalls sell the lulav, etrog, myrtle and willow used on Sukkot, from morning to night. Basic sets cost about the same as last year; access roads are busy in the evening.'),
  ('92ad4de1-a899-5146-8a11-32129c346230', 'en', 'general', 'calm', 'Four Species markets open in Jerusalem', 'Stalls selling the traditional Sukkot plants are open until the eve of the holiday. Early mornings are the quietest time to shop.'),
  ('92ad4de1-a899-5146-8a11-32129c346230', 'fr', 'general', 'informative', 'Jérusalem : le marché des quatre espèces ouvert jusqu’à Souccot', 'Des dizaines d’étals vendent loulav, étrog, myrte et saule, du matin au soir. Les prix sont proches de l’an dernier ; routes d’accès chargées le soir.'),
  ('92ad4de1-a899-5146-8a11-32129c346230', 'fr', 'general', 'calm', 'Les marchés des quatre espèces ouvrent à Jérusalem', 'Les étals des plantes traditionnelles de Souccot sont ouverts jusqu’à la veille de la fête. Le matin est le moment le plus calme.'),
  ('92ad4de1-a899-5146-8a11-32129c346230', 'he', 'youth', 'light', 'ארבעת המינים: מי מוצא את האתרוג הכי יפה', 'בשוק בירושלים בודקים אתרוגים בזכוכית מגדלת. אם אתם הולכים עם ההורים, תבקשו להחזיק את הלולב.'),
  ('92ad4de1-a899-5146-8a11-32129c346230', 'he', 'youth', 'calm', 'שוק ארבעת המינים פתוח', 'בשוק בירושלים קונים לולב, אתרוג, הדס וערבה לחג הסוכות. הוא פתוח עד ערב החג.'),
  ('cc7bbfce-1220-5055-868a-6d059a983725', 'he', 'general', 'calm', 'פסטיבל סוכות בפארקים של באר שבע, בכניסה חופשית', 'בימי חול המועד יתקיימו הופעות, סדנאות ופעילויות לילדים בפארקים בעיר. אין צורך בהרשמה מראש, ומומלץ להגיע בתחבורה ציבורית.'),
  ('cc7bbfce-1220-5055-868a-6d059a983725', 'he', 'general', 'human', 'אמנים מקומיים מכינים את פסטיבל החג בבאר שבע', '"אנחנו מופיעים בשכונה שבה גדלנו", מספר נגן בלהקה מקומית. בחול המועד יתקיימו הופעות וסדנאות בפארקים, בכניסה חופשית.'),
  ('cc7bbfce-1220-5055-868a-6d059a983725', 'he', 'general', 'informative', 'באר שבע: פסטיבל סוכות בפארקים בחול המועד', 'העירייה מפרסמת תוכנייה של הופעות, סדנאות יצירה ופעילויות משפחה בפארקים, בכניסה חופשית. הפעילויות מתקיימות בין 10:00 ל־20:00.'),
  ('cc7bbfce-1220-5055-868a-6d059a983725', 'he', 'general', 'light', 'חול המועד בבאר שבע: פיקניק, מוזיקה וסדנאות', 'הפארקים בעיר מתמלאים בהופעות ובסדנאות לילדים, בכניסה חופשית. מביאים מחצלת, כובע וסבלנות לחניה.'),
  ('cc7bbfce-1220-5055-868a-6d059a983725', 'en', 'general', 'informative', 'Beersheba: free Sukkot festival in the parks', 'The municipality has published a programme of shows, craft workshops and family activities in city parks during the intermediate days of Sukkot, from 10:00 to 20:00. Entry is free.'),
  ('cc7bbfce-1220-5055-868a-6d059a983725', 'en', 'general', 'calm', 'A free Sukkot festival in Beersheba', 'Parks across the city will host shows and children’s workshops during the holiday week. No booking is needed; public transport is recommended.'),
  ('cc7bbfce-1220-5055-868a-6d059a983725', 'fr', 'general', 'informative', 'Beer-Sheva : festival de Souccot gratuit dans les parcs', 'La municipalité propose spectacles, ateliers et activités familiales dans les parcs pendant les demi-fêtes de Souccot, de 10 h à 20 h. Entrée libre.'),
  ('cc7bbfce-1220-5055-868a-6d059a983725', 'fr', 'general', 'calm', 'Un festival de Souccot gratuit à Beer-Sheva', 'Les parcs de la ville accueilleront spectacles et ateliers pour enfants pendant la semaine de fête. Sans réservation ; transports en commun conseillés.'),
  ('cc7bbfce-1220-5055-868a-6d059a983725', 'he', 'youth', 'light', 'חול המועד בבאר שבע: הופעות בפארקים', 'בחופש יהיו בפארקים הופעות, סדנאות ומשחקים, בכניסה חופשית. שווה לתאם עם חברים.'),
  ('cc7bbfce-1220-5055-868a-6d059a983725', 'he', 'youth', 'calm', 'פעילויות חג בפארקים של באר שבע', 'בחול המועד יתקיימו הופעות וסדנאות לילדים בפארקים, בלי תשלום.'),
  ('75578962-023a-5679-8de8-6418dfb1c3b4', 'he', 'general', 'calm', 'מרוץ לילה במודיעין: כבישים ייסגרו בערב', 'אלפי רצים ישתתפו במרוץ העירוני. רחובות במרכז העיר ייסגרו בין 18:30–22:30, ומומלץ להגיע ברגל או בתחבורה ציבורית.'),
  ('75578962-023a-5679-8de8-6418dfb1c3b4', 'he', 'general', 'human', 'רצים חובבים מתכוננים למרוץ הלילה במודיעין', '"אני רצה לכבוד אבא שלי, זו השנה הראשונה שלי", מספרת משתתפת. המרוץ יתקיים הערב, וחלק מהרחובות ייסגרו בין 18:30–22:30.'),
  ('75578962-023a-5679-8de8-6418dfb1c3b4', 'he', 'general', 'informative', 'מודיעין: סגירת רחובות בין 18:30–22:30 בשל מרוץ לילה', 'המרוץ העירוני יתקיים במקצים של 5, 10 ו־21 ק״מ. מפת הסגירות מתפרסמת באתר העירייה. קווי אוטובוס יוסטו למסלולים חלופיים.'),
  ('75578962-023a-5679-8de8-6418dfb1c3b4', 'he', 'general', 'light', 'נעלי ריצה, פנסי רחוב, יוצאים לדרך', 'מרוץ הלילה במודיעין חוזר. מי שלא רץ יכול לעודד, ומי שנוהג כדאי שיעקוף: סגירות בין 18:30–22:30.'),
  ('75578962-023a-5679-8de8-6418dfb1c3b4', 'en', 'general', 'informative', 'Modiin: road closures 18:30–22:30 for a night run', 'The city run includes 5, 10 and 21 km races. A closure map is on the municipality’s website, and bus lines will be diverted.'),
  ('75578962-023a-5679-8de8-6418dfb1c3b4', 'en', 'general', 'calm', 'Night run in Modiin this evening', 'Thousands of runners will take part. Some central streets will close between 18:30–22:30; walking or public transport is recommended.'),
  ('75578962-023a-5679-8de8-6418dfb1c3b4', 'fr', 'general', 'informative', 'Modiin : rues fermées de 18:30–22:30 pour une course de nuit', 'La course comprend des épreuves de 5, 10 et 21 km. Le plan des fermetures est sur le site de la mairie ; des lignes de bus seront déviées.'),
  ('75578962-023a-5679-8de8-6418dfb1c3b4', 'fr', 'general', 'calm', 'Course de nuit à Modiin ce soir', 'Des milliers de coureurs y participent. Certaines rues du centre seront fermées de 18:30–22:30 ; privilégiez la marche ou les transports en commun.'),
  ('2c50565c-965e-56f1-81a3-904e57ffaf59', 'he', 'general', 'calm', 'גשם ראשון בדרך לצפון', 'צפויות טפטופות וממטרים קלים בגליל ובגולן בסוף השבוע. אין צורך בהיערכות מיוחדת, רק מטרייה קרובה.'),
  ('2c50565c-965e-56f1-81a3-904e57ffaf59', 'he', 'general', 'human', 'בצפון מחכים לגשם הראשון, ובעיקר החקלאים', 'ממטרים קלים צפויים בגליל ובגולן בסוף השבוע. "זה בדיוק מה שהאדמה צריכה אחרי הקיץ", אומר מגדל תפוחים מהאזור.'),
  ('2c50565c-965e-56f1-81a3-904e57ffaf59', 'he', 'general', 'informative', 'תחזית: ממטרים ראשונים בגליל ובגולן בסוף השבוע', 'ממטרים קלים ומקומיים צפויים בגליל ובגולן בסוף השבוע, עם ירידה של 3–4 מעלות בטמפרטורות. בשאר הארץ יהיה מעונן חלקית.'),
  ('2c50565c-965e-56f1-81a3-904e57ffaf59', 'he', 'general', 'light', 'הוציאו את המטריות מהבוידעם', 'הגשם הראשון של העונה מגיע בגליל ובגולן בסוף השבוע. לא מבול, אבל מספיק כדי להריח את הסתיו.'),
  ('2c50565c-965e-56f1-81a3-904e57ffaf59', 'en', 'general', 'informative', 'Forecast: first showers in the Galilee and the Golan Heights this weekend', 'Light, scattered showers are expected in the Galilee and the Golan Heights this weekend, with temperatures dropping 3–4°C. The rest of the country will be partly cloudy.'),
  ('2c50565c-965e-56f1-81a3-904e57ffaf59', 'en', 'general', 'calm', 'The first rain is on its way north', 'Light showers are expected in the Galilee and the Golan Heights this weekend. No special preparations are needed, just an umbrella nearby.'),
  ('2c50565c-965e-56f1-81a3-904e57ffaf59', 'fr', 'general', 'informative', 'Prévisions : premières averses en Galilée et sur le Golan ce week-end', 'Des averses faibles et locales sont attendues en Galilée et sur le Golan ce week-end, avec une baisse de 3 à 4 °C. Ailleurs, ciel partiellement nuageux.'),
  ('2c50565c-965e-56f1-81a3-904e57ffaf59', 'fr', 'general', 'calm', 'La première pluie arrive dans le Nord', 'De faibles averses sont prévues en Galilée et sur le Golan ce week-end. Aucune préparation particulière : gardez simplement un parapluie à portée de main.'),
  ('2c50565c-965e-56f1-81a3-904e57ffaf59', 'he', 'youth', 'light', 'ריח של סתיו: הגשם הראשון מגיע', 'ממטרים קלים צפויים בגליל ובגולן בסוף השבוע. זה זמן טוב לבדוק איפה המעיל מהשנה שעברה.'),
  ('2c50565c-965e-56f1-81a3-904e57ffaf59', 'he', 'youth', 'calm', 'גשם ראשון בצפון', 'צפויים ממטרים קלים בגליל ובגולן בסוף השבוע. לא צריך להתכונן במיוחד, רק לקחת מעיל דק.'),
  ('f63783f3-fd1f-542e-84ac-f2f351f1a285', 'he', 'general', 'calm', 'כמה צעדים פשוטים יורידו את חשבון החשמל', 'מזגן על 24 מעלות, ניקוי מסננים ותריסים סגורים בצהריים חוסכים עד רבע מצריכת החשמל בקיץ, בלי לוותר על נוחות.'),
  ('f63783f3-fd1f-542e-84ac-f2f351f1a285', 'he', 'general', 'human', 'משפחה מהשרון הורידה את החשבון בלי להזיע', '"ניקינו את המסננים והעלינו את המזגן לעשרים וארבע. אף אחד לא הרגיש", מספרת אם לשלושה. החיסכון: עד רבע מהחשבון.'),
  ('f63783f3-fd1f-542e-84ac-f2f351f1a285', 'he', 'general', 'informative', 'חיסכון בחשמל: מזגן על 24 מעלות ומסננים נקיים', 'לפי רשות החשמל, כל מעלה בקירור חוסכת כ־6% בצריכה. ניקוי מסננים פעם בחודש ותריסים סגורים בצהריים מוסיפים חיסכון.'),
  ('f63783f3-fd1f-542e-84ac-f2f351f1a285', 'he', 'general', 'light', 'המזגן והארנק יכולים להיות חברים', '24 מעלות, מסנן נקי ותריס סגור בצהריים. זה כל הסוד, וזה שווה עד רבע מהחשבון.'),
  ('03cb3d56-68c8-5feb-8d96-86a461c171a8', 'he', 'general', 'calm', 'ערב קהילתי בפארק ענבה: הופעה וסדנאות לילדים', 'המתנ״ס מזמין את התושבים לערב פתוח עם מוזיקה, דוכני יצירה ופינת קפה. הכניסה חופשית.'),
  ('03cb3d56-68c8-5feb-8d96-86a461c171a8', 'he', 'general', 'informative', 'פארק ענבה: ערב קהילתי פתוח ביום חמישי ב־18:00', 'בתוכנית: הופעה של להקה מקומית, סדנאות יצירה לילדים ודוכנים של עסקים מהשכונה. כניסה חופשית, ללא הרשמה.'),
  ('2d8b31b0-845f-56cb-b82d-2796604974f8', 'he', 'general', 'calm', 'שיבוש באספקת המים בשכונות הצפוניות של באר שבע עד 20:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 20:00. תאגיד המים מציב נקודות חלוקה, והצוותים כבר עובדים בשטח.'),
  ('2d8b31b0-845f-56cb-b82d-2796604974f8', 'he', 'general', 'human', 'תושבים בשכונות הצפוניות של באר שבע בלי לחץ מים עד 20:00', 'משפחות בכמה שכונות מתארגנות עם בקבוקים ושכנים. "מילאנו סירים מראש, יהיה בסדר", מספרת תושבת. תאגיד המים מציב נקודות חלוקה.'),
  ('2d8b31b0-845f-56cb-b82d-2796604974f8', 'he', 'general', 'informative', 'באר שבע: לחץ מים נמוך בשכונות הצפוניות עד 20:00', 'תקלה בצנרת ראשית פוגעת באספקת המים בשכונות הצפוניות. התיקון צפוי להסתיים עד 20:00. נקודות חלוקת מים פועלות, והפרטים באתר תאגיד המים.'),
  ('2d8b31b0-845f-56cb-b82d-2796604974f8', 'he', 'general', 'light', 'שיבוש באספקת המים בשכונות הצפוניות של באר שבע עד 20:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 20:00. תאגיד המים מציב נקודות חלוקה ומעדכן באתר.'),
  ('2d8b31b0-845f-56cb-b82d-2796604974f8', 'en', 'general', 'informative', 'Beersheba: low water pressure in the northern neighbourhoods until 20:00', 'A fault in a main pipe is disrupting the water supply in the northern neighbourhoods. Repairs are expected to finish by 20:00; the municipal water company has set up distribution points.'),
  ('2d8b31b0-845f-56cb-b82d-2796604974f8', 'en', 'general', 'calm', 'Water supply disrupted in parts of Beersheba until 20:00', 'Following a pipe fault, some neighbourhoods in the northern neighbourhoods will have low water pressure until 20:00. Crews are on site and water is available at distribution points.'),
  ('2d8b31b0-845f-56cb-b82d-2796604974f8', 'fr', 'general', 'informative', 'Beer-Sheva : faible pression d’eau dans les quartiers nord jusqu’à 20:00', 'Une panne sur une canalisation principale perturbe l’alimentation en eau dans les quartiers nord. La réparation devrait s’achever vers 20:00 ; des points de distribution sont ouverts.'),
  ('2d8b31b0-845f-56cb-b82d-2796604974f8', 'fr', 'general', 'calm', 'Perturbation de l’eau à Beer-Sheva jusqu’à 20:00', 'À la suite d’une panne, certains quartiers dans les quartiers nord auront une pression d’eau faible jusqu’à 20:00. Les équipes sont sur place et des points de distribution sont ouverts.'),
  ('60d3e135-4a0d-507e-8035-d11159cc1621', 'he', 'general', 'calm', 'עבודות תחזוקה ברכבת בין תל אביב לחיפה בשלושת הלילות הקרובים', 'הרכבות בין תל אביב לחיפה לא יפעלו בשלושת הלילות הקרובים אחרי 22:00. יופעלו אוטובוסים חלופיים מהתחנות, ובבוקר התנועה תחזור לשגרה.'),
  ('60d3e135-4a0d-507e-8035-d11159cc1621', 'he', 'general', 'human', 'נוסעי הלילה בין תל אביב לחיפה יעברו לאוטובוסים', 'מי שחוזר מאוחר מהעבודה יצטרך לתכנן מחדש בשלושת הלילות הקרובים. "העיקר שיש הסעה חלופית", אומר נוסע קבוע. הרכבות יחזרו לפעול בבוקר.'),
  ('60d3e135-4a0d-507e-8035-d11159cc1621', 'he', 'general', 'informative', 'הרכבת בין תל אביב לחיפה: הפסקת תנועה בשלושת הלילות הקרובים מ־22:00', 'בשל עבודות תחזוקה לא יפעלו רכבות בין תל אביב לחיפה בשלושת הלילות הקרובים מ־22:00 ועד תחילת השירות בבוקר. אוטובוסים חלופיים ייצאו מהתחנות כל 20 דקות.'),
  ('60d3e135-4a0d-507e-8035-d11159cc1621', 'he', 'general', 'light', 'הרכבת לוקחת כמה לילות לטיפוח', 'עבודות תחזוקה בין תל אביב לחיפה בשלושת הלילות הקרובים: אחרי 22:00 עוברים לאוטובוסים החלופיים. בבוקר הכל חוזר למסלול.'),
  ('60d3e135-4a0d-507e-8035-d11159cc1621', 'en', 'general', 'informative', 'Trains between Tel Aviv and Haifa: no service after 22:00 over the next three nights', 'Because of maintenance works, Israel Railways will not run trains between Tel Aviv and Haifa from 22:00 until the morning service over the next three nights. Replacement buses leave the stations every 20 minutes.'),
  ('60d3e135-4a0d-507e-8035-d11159cc1621', 'en', 'general', 'calm', 'Night maintenance on the railway between Tel Aviv and Haifa', 'Trains between Tel Aviv and Haifa will not run after 22:00 over the next three nights. Replacement buses are available, and service returns to normal in the morning.'),
  ('60d3e135-4a0d-507e-8035-d11159cc1621', 'fr', 'general', 'informative', 'Trains entre Tel-Aviv et Haïfa : pas de service après 22 h les trois prochaines nuits', 'En raison de travaux, les Chemins de fer israéliens n’assureront aucun train entre Tel-Aviv et Haïfa de 22 h jusqu’au premier départ du matin les trois prochaines nuits. Des bus de remplacement partent toutes les 20 minutes.'),
  ('60d3e135-4a0d-507e-8035-d11159cc1621', 'fr', 'general', 'calm', 'Travaux de nuit sur la ligne entre Tel-Aviv et Haïfa', 'Les trains entre Tel-Aviv et Haïfa ne circuleront pas après 22 h les trois prochaines nuits. Des bus de remplacement sont prévus et le service reprend normalement le matin.'),
  ('60d3e135-4a0d-507e-8035-d11159cc1621', 'he', 'youth', 'light', 'הרכבת עושה חופשה קצרה בלילות', 'בגלל עבודות, הרכבות בין תל אביב לחיפה לא ייסעו בשלושת הלילות הקרובים אחרי 22:00. במקומן יהיו אוטובוסים.'),
  ('60d3e135-4a0d-507e-8035-d11159cc1621', 'he', 'youth', 'calm', 'שינוי ברכבת בין תל אביב לחיפה', 'הרכבות בין תל אביב לחיפה לא יפעלו בשלושת הלילות הקרובים אחרי 22:00. יהיו אוטובוסים חלופיים, ובבוקר הכל חוזר לרגיל.'),
  ('8a412aea-a7ba-5a28-8201-9c15dbaf17f1', 'he', 'general', 'calm', 'מחקר: 20 דקות הליכה ביום עושות הבדל', 'חוקרים שעקבו אחר אלפי משתתפים מצאו שהליכה קלה של 20 דקות ביום קשורה לשינה טובה יותר ולמצב רוח יציב. לא צריך ציוד, רק לצאת מהבית.'),
  ('8a412aea-a7ba-5a28-8201-9c15dbaf17f1', 'he', 'general', 'human', '"התחלתי ללכת עם השכנה, ועכשיו אני ישנה טוב יותר"', 'מחקר חדש מאשר את מה שהרבה הולכי ערב מרגישים: 20 דקות הליכה ביום קשורות לשינה טובה ולמצב רוח יציב יותר.'),
  ('8a412aea-a7ba-5a28-8201-9c15dbaf17f1', 'he', 'general', 'informative', 'מחקר: 20 דקות הליכה ביום משפרות שינה', 'במחקר שעקב אחר אלפי מבוגרים במשך שנה, הליכה יומית של 20 דקות נקשרה לשיפור באיכות השינה ולירידה בדיווחים על מתח. הממצאים פורסמו בכתב עת רפואי.'),
  ('8a412aea-a7ba-5a28-8201-9c15dbaf17f1', 'he', 'general', 'light', 'הנעליים כבר ליד הדלת', 'מחקר חדש מצא ש־20 דקות הליכה ביום עוזרות לישון טוב יותר. סיבוב סביב הבלוק נחשב, גם עם עצירה לגלידה.'),
  ('8a412aea-a7ba-5a28-8201-9c15dbaf17f1', 'en', 'general', 'informative', 'Study: 20 minutes of walking a day improves sleep', 'In a study that followed thousands of adults for a year, a daily 20-minute walk was linked to better sleep quality and fewer reports of stress. The findings appeared in a medical journal.'),
  ('8a412aea-a7ba-5a28-8201-9c15dbaf17f1', 'en', 'general', 'calm', 'A short daily walk may help you sleep', 'Researchers found that an easy 20-minute walk each day is linked to better sleep and a steadier mood. No equipment needed.'),
  ('8a412aea-a7ba-5a28-8201-9c15dbaf17f1', 'fr', 'general', 'informative', 'Étude : 20 minutes de marche par jour améliorent le sommeil', 'Selon une étude qui a suivi des milliers d’adultes pendant un an, une marche quotidienne de 20 minutes est associée à un meilleur sommeil et à moins de stress. Les résultats ont paru dans une revue médicale.'),
  ('8a412aea-a7ba-5a28-8201-9c15dbaf17f1', 'fr', 'general', 'calm', 'Une courte marche quotidienne aide à mieux dormir', 'Des chercheurs ont constaté qu’une marche tranquille de 20 minutes par jour va de pair avec un meilleur sommeil et une humeur plus stable.'),
  ('8a412aea-a7ba-5a28-8201-9c15dbaf17f1', 'he', 'youth', 'light', 'סיבוב קטן, שינה גדולה', 'חוקרים מצאו ש־20 דקות הליכה ביום עוזרות לישון טוב יותר. אפשר ללכת עם חברים, עם הכלב או עם מוזיקה.'),
  ('8a412aea-a7ba-5a28-8201-9c15dbaf17f1', 'he', 'youth', 'calm', 'הליכה קצרה עוזרת לישון טוב', 'מחקר חדש מצא שהליכה של 20 דקות ביום קשורה לשינה טובה יותר ולמצב רוח טוב.'),
  ('6ca4bf45-5e9b-53a6-acf0-0fc2052595e3', 'he', 'general', 'calm', 'מחירי השכירות עלו בשנה האחרונה, בקצב מתון יותר', 'לפי נתונים רשמיים, העלייה בשכר הדירה נמשכת אבל מאטה. בערים הגדולות ההתייקרות בולטת יותר, ובפריפריה היא קטנה.'),
  ('6ca4bf45-5e9b-53a6-acf0-0fc2052595e3', 'he', 'general', 'human', 'זוג צעיר מחפש דירה: "למדנו לחפש בשכונות חדשות"', 'העלייה במחירי השכירות מאטה, אבל עדיין מורגשת בערים הגדולות. שוכרים רבים עוברים לשכונות חדשות או לערים סמוכות.'),
  ('6ca4bf45-5e9b-53a6-acf0-0fc2052595e3', 'he', 'general', 'informative', 'נתונים: שכר הדירה עלה בכ־4% בשנה, והקצב מאט', 'העלייה הבולטת נרשמה בערים הגדולות. בחידוש חוזה העלייה נמוכה מאשר בחוזה חדש. הנתונים מבוססים על סקר דירות שנתי.'),
  ('6ca4bf45-5e9b-53a6-acf0-0fc2052595e3', 'he', 'general', 'light', 'שכר הדירה עדיין מטפס, אבל נושם', 'הנתונים מראים שהעלייה במחירי השכירות מאטה. טיפ לשוכרים: בחידוש חוזה יש יותר מקום למשא ומתן.'),
  ('6ca4bf45-5e9b-53a6-acf0-0fc2052595e3', 'en', 'general', 'informative', 'Data: rents up about 4% in a year, growth slowing', 'The sharpest rises were in the large cities. Renewals rose less than new contracts. The figures come from Israel’s annual housing survey.'),
  ('6ca4bf45-5e9b-53a6-acf0-0fc2052595e3', 'en', 'general', 'calm', 'Rents are rising more slowly', 'Official figures show rent increases continuing but slowing, with smaller changes outside the big cities.'),
  ('6ca4bf45-5e9b-53a6-acf0-0fc2052595e3', 'fr', 'general', 'informative', 'Loyers : environ +4 % sur un an, la hausse ralentit', 'Les hausses les plus fortes concernent les grandes villes. Les renouvellements augmentent moins que les nouveaux baux, selon l’enquête annuelle sur le logement.'),
  ('6ca4bf45-5e9b-53a6-acf0-0fc2052595e3', 'fr', 'general', 'calm', 'Les loyers augmentent moins vite', 'Les chiffres officiels montrent une hausse des loyers qui se poursuit mais ralentit, surtout hors des grandes villes.'),
  ('93c0e060-fc1b-5237-b414-8e5d7acde663', 'he', 'general', 'calm', 'חם מהרגיל היום, ובערב נעים יותר', 'הטמפרטורות יגיעו לכ־34 מעלות בשפלה ובעמקים. מספיק לשתות מים ולהישאר בצל בשעות הצהריים. בערב צפויה הקלה.'),
  ('93c0e060-fc1b-5237-b414-8e5d7acde663', 'he', 'general', 'human', 'מי שעובד בחוץ ירגיש את החום היום', 'פועלי בניין, שליחים וחקלאים בשפלה ובעמקים יפגשו כ־34 מעלות. "אנחנו מתחילים מוקדם ומסיימים לפני הצהריים", מספר מנהל עבודה. בערב צפויה הקלה.'),
  ('93c0e060-fc1b-5237-b414-8e5d7acde663', 'he', 'general', 'informative', '34 מעלות בשפלה ובעמקים היום, הקלה בערב', 'עומס חום בינוני בשפלה ובעמקים: עד 34 מעלות בשעות הצהריים. משרד הבריאות ממליץ לשתות באופן קבוע ולהימנע ממאמץ בשמש בין 11:00 ל־16:00.'),
  ('93c0e060-fc1b-5237-b414-8e5d7acde663', 'he', 'general', 'light', 'הכובע והבקבוק חוזרים לתיק', 'היום יהיה חם, עד 34 מעלות בשפלה ובעמקים. מים קרים, צל טוב ומזגן בטמפרטורה סבירה, והערב כבר יהיה נעים יותר.'),
  ('93c0e060-fc1b-5237-b414-8e5d7acde663', 'en', 'general', 'informative', 'Up to 34°C in the lowlands and valleys today', 'A moderate heat load is expected in the lowlands and valleys, peaking around midday. Israel’s Health Ministry advises drinking regularly and avoiding exertion in the sun between 11:00 and 16:00.'),
  ('93c0e060-fc1b-5237-b414-8e5d7acde663', 'en', 'general', 'calm', 'A hot day, with a pleasant evening', 'Temperatures will reach about 34°C in the lowlands and valleys today. Water and some shade at midday are enough; the evening will be cooler.'),
  ('93c0e060-fc1b-5237-b414-8e5d7acde663', 'fr', 'general', 'informative', 'Jusqu’à 34 °C dans la plaine et les vallées aujourd’hui', 'Une chaleur modérée est attendue dans la plaine et les vallées, avec un pic vers midi. Le ministère israélien de la Santé conseille de boire régulièrement et d’éviter l’effort au soleil entre 11 h et 16 h.'),
  ('93c0e060-fc1b-5237-b414-8e5d7acde663', 'fr', 'general', 'calm', 'Une journée chaude, une soirée plus douce', 'Les températures atteindront environ 34 °C dans la plaine et les vallées aujourd’hui. De l’eau et un peu d’ombre à midi suffisent ; la soirée sera plus fraîche.'),
  ('93c0e060-fc1b-5237-b414-8e5d7acde663', 'he', 'youth', 'light', 'יום חם: בקבוק מים הוא החבר הכי טוב שלכם', 'היום החום יגיע לכ־34 מעלות בשפלה ובעמקים. בהפסקות כדאי לשבת בצל ולשתות, גם כשלא מרגישים צמאים.'),
  ('93c0e060-fc1b-5237-b414-8e5d7acde663', 'he', 'youth', 'calm', 'חם היום, ובערב יהיה נעים', 'הטמפרטורות יגיעו לכ־34 מעלות. שותים מים, נשארים בצל בצהריים, ובערב כבר יהיה קריר יותר.'),
  ('fc43d278-0f14-561d-9fc6-344cba9c0fb1', 'he', 'general', 'calm', 'ספורטאית פראלימפית צעירה זכתה במדליה בטניס שולחן', 'בתחרות בינלאומית זכתה ספורטאית בת 19 במדליית כסף בטניס שולחן. היא מתאמנת במרכז הספורט הפראלימפי כבר שש שנים.'),
  ('fc43d278-0f14-561d-9fc6-344cba9c0fb1', 'he', 'general', 'human', '"חלמתי על הרגע הזה מגיל 13"', 'ספורטאית פראלימפית בת 19 זכתה במדליית כסף בטניס שולחן בתחרות בינלאומית. המאמנת שלה סיפרה שהיא מתאמנת כל בוקר לפני הלימודים.'),
  ('fc43d278-0f14-561d-9fc6-344cba9c0fb1', 'he', 'general', 'informative', 'מדליית כסף לספורטאית פראלימפית בטניס שולחן', 'הספורטאית, בת 19, סיימה במקום השני בתחרות בינלאומית, בתוצאה אישית הטובה ביותר שלה. זו המדליה הבינלאומית הראשונה שלה.'),
  ('fc43d278-0f14-561d-9fc6-344cba9c0fb1', 'he', 'general', 'light', 'כסף שמרגיש כמו זהב', 'ספורטאית פראלימפית בת 19 זכתה במדליית כסף בטניס שולחן ושברה שיא אישי. הבוקר שלה מתחיל באימון, והשאר היסטוריה.'),
  ('f19af411-d349-5fad-8f24-fb9ea336138e', 'he', 'general', 'calm', 'חניה חינם בחניונים העירוניים בחול המועד', 'העירייה מודיעה על חניה ללא תשלום בחניונים העירוניים בימי חול המועד, כדי להקל על המבקרים בגן סאקר.'),
  ('f19af411-d349-5fad-8f24-fb9ea336138e', 'he', 'general', 'informative', 'חול המועד: חניה חינם בחניונים העירוניים', 'ההקלה תחול בכל ימי חול המועד בחניונים העירוניים, כולל באזור גן סאקר. בחניונים הפרטיים המחירים לא משתנים.'),
  ('712a2fc0-fdcf-585f-aa07-b0d20fa5eb7e', 'he', 'general', 'calm', 'שיבושים בקווי אוטובוס בירושלים עד 10:00', 'בעקבות מחלוקת עבודה אצל אחד המפעילים, חלק מהקווים בירושלים לא יפעלו הבוקר עד 10:00. הרכבת והקווים של שאר המפעילים פועלים כרגיל.'),
  ('712a2fc0-fdcf-585f-aa07-b0d20fa5eb7e', 'he', 'general', 'human', 'נוסעים בירושלים מחפשים דרך אחרת לעבודה', 'בתחנות מתארגנים לנסיעות משותפות ולקורקינטים. "יצאתי חצי שעה מוקדם, זה עובד", מספרת סטודנטית. חלק מהקווים לא יפעלו עד 10:00.'),
  ('712a2fc0-fdcf-585f-aa07-b0d20fa5eb7e', 'he', 'general', 'informative', 'ירושלים: חלק מקווי האוטובוס מושבתים עד 10:00', 'מחלוקת עבודה אצל מפעיל אחד משביתה חלק מהקווים בירושלים עד 10:00. רשימת הקווים באפליקציות התחבורה. הרכבת ושאר המפעילים פועלים כסדרם.'),
  ('712a2fc0-fdcf-585f-aa07-b0d20fa5eb7e', 'he', 'general', 'light', 'שיבושים בקווי אוטובוס בירושלים עד 10:00', 'חלק מהקווים של אחד המפעילים לא יפעלו הבוקר עד 10:00. כדאי לבדוק באפליקציית התחבורה לפני היציאה.'),
  ('712a2fc0-fdcf-585f-aa07-b0d20fa5eb7e', 'en', 'general', 'informative', 'Jerusalem: some bus lines halted until 10:00', 'A labour dispute at one operator has stopped some bus lines in Jerusalem until 10:00. Trains and other operators run as usual; check your transit app for the affected lines.'),
  ('712a2fc0-fdcf-585f-aa07-b0d20fa5eb7e', 'en', 'general', 'calm', 'Some buses in Jerusalem delayed until 10:00', 'Part of one operator’s lines will not run this morning until 10:00. Trains and other lines are working normally, so most journeys just need a little more time.'),
  ('712a2fc0-fdcf-585f-aa07-b0d20fa5eb7e', 'fr', 'general', 'informative', 'Jérusalem : des lignes de bus à l’arrêt jusqu’à 10:00', 'Un conflit social chez un opérateur interrompt certaines lignes à Jérusalem jusqu’à 10:00. Les trains et les autres opérateurs circulent normalement ; vérifiez votre application de transport.'),
  ('712a2fc0-fdcf-585f-aa07-b0d20fa5eb7e', 'fr', 'general', 'calm', 'Perturbations des bus à Jérusalem jusqu’à 10:00', 'Une partie des lignes d’un opérateur ne circulera pas ce matin jusqu’à 10:00. Les trains et les autres lignes fonctionnent : prévoyez simplement un peu plus de temps.'),
  ('65e97803-eacc-578c-9a8b-37a7bfc4011c', 'he', 'general', 'calm', 'שווקי ארבעת המינים נפתחו בבני ברק', 'הדוכנים פתוחים עד ערב החג. המחירים דומים לשנה שעברה, ומי שמעדיף שקט יכול לקנות בשעות הבוקר המוקדמות.'),
  ('65e97803-eacc-578c-9a8b-37a7bfc4011c', 'he', 'general', 'human', 'מוכר אתרוגים ותיק: "כל שנה אותם לקוחות, אותה התרגשות"', 'בשוק ארבעת המינים בבני ברק בודקים אתרוגים בזכוכית מגדלת ומתייעצים עם השכנים. הדוכנים פתוחים עד ערב החג.'),
  ('65e97803-eacc-578c-9a8b-37a7bfc4011c', 'he', 'general', 'informative', 'בני ברק: שוק ארבעת המינים פתוח עד ערב סוכות', 'עשרות דוכנים פועלים מהבוקר ועד הלילה. סט בסיסי נמכר במחירים דומים לשנה שעברה. בשעות הערב צפוי עומס בכבישי הגישה.'),
  ('65e97803-eacc-578c-9a8b-37a7bfc4011c', 'he', 'general', 'light', 'אתרוג, לולב, ובעיקר סבלנות', 'שוק ארבעת המינים בבני ברק פתוח. טיפ של ותיקים: מגיעים בבוקר, בודקים בלי לחץ, ומשאירים זמן לקפה.'),
  ('65e97803-eacc-578c-9a8b-37a7bfc4011c', 'en', 'general', 'informative', 'Bnei Brak: Four Species market open until the eve of Sukkot', 'Dozens of stalls sell the lulav, etrog, myrtle and willow used on Sukkot, from morning to night. Basic sets cost about the same as last year; access roads are busy in the evening.'),
  ('65e97803-eacc-578c-9a8b-37a7bfc4011c', 'en', 'general', 'calm', 'Four Species markets open in Bnei Brak', 'Stalls selling the traditional Sukkot plants are open until the eve of the holiday. Early mornings are the quietest time to shop.'),
  ('65e97803-eacc-578c-9a8b-37a7bfc4011c', 'fr', 'general', 'informative', 'Bné Brak : le marché des quatre espèces ouvert jusqu’à Souccot', 'Des dizaines d’étals vendent loulav, étrog, myrte et saule, du matin au soir. Les prix sont proches de l’an dernier ; routes d’accès chargées le soir.'),
  ('65e97803-eacc-578c-9a8b-37a7bfc4011c', 'fr', 'general', 'calm', 'Les marchés des quatre espèces ouvrent à Bné Brak', 'Les étals des plantes traditionnelles de Souccot sont ouverts jusqu’à la veille de la fête. Le matin est le moment le plus calme.'),
  ('65e97803-eacc-578c-9a8b-37a7bfc4011c', 'he', 'youth', 'light', 'ארבעת המינים: מי מוצא את האתרוג הכי יפה', 'בשוק בבני ברק בודקים אתרוגים בזכוכית מגדלת. אם אתם הולכים עם ההורים, תבקשו להחזיק את הלולב.'),
  ('65e97803-eacc-578c-9a8b-37a7bfc4011c', 'he', 'youth', 'calm', 'שוק ארבעת המינים פתוח', 'בשוק בבני ברק קונים לולב, אתרוג, הדס וערבה לחג הסוכות. הוא פתוח עד ערב החג.'),
  ('3e4fe478-2d00-55e3-9162-6192828e557d', 'he', 'general', 'calm', 'ספריות עירוניות מאריכות שעות פתיחה בחופשה', 'ספריות ברשויות רבות יהיו פתוחות גם בשעות הערב בחול המועד, עם שעת סיפור לילדים ופינות קריאה בחוץ.'),
  ('3e4fe478-2d00-55e3-9162-6192828e557d', 'he', 'general', 'human', 'ספרנית: "בחופשה הילדים מגלים שספר זה גם כיף"', 'ספריות עירוניות מאריכות את שעות הפתיחה בחופשה ומוסיפות שעות סיפור. "בכל חג יש ילד שיוצא עם ערימה של ספרים", היא מספרת.'),
  ('3e4fe478-2d00-55e3-9162-6192828e557d', 'he', 'general', 'informative', 'ספריות ציבוריות: שעות פתיחה מורחבות בחול המועד', 'ברשויות רבות יפעלו הספריות גם עד 20:00, עם שעות סיפור ופעילויות. ההשאלה בחינם לתושבים. הפרטים באתרי הרשויות.'),
  ('3e4fe478-2d00-55e3-9162-6192828e557d', 'he', 'general', 'light', 'הספרייה פתוחה עד מאוחר, והמזגן עובד', 'בחול המועד ספריות רבות פתוחות עד הערב, עם שעת סיפור לקטנים. מקום מצוין לברוח אליו מהחום.'),
  ('3e4fe478-2d00-55e3-9162-6192828e557d', 'en', 'general', 'informative', 'Public libraries extend opening hours over the holiday', 'In many towns, libraries will stay open until 20:00 during the intermediate days of Sukkot, with story hours and activities. Borrowing is free for residents.'),
  ('3e4fe478-2d00-55e3-9162-6192828e557d', 'en', 'general', 'calm', 'Libraries open later during the holiday', 'Many municipal libraries will open in the evenings this holiday week, with story time for children and outdoor reading corners.'),
  ('3e4fe478-2d00-55e3-9162-6192828e557d', 'fr', 'general', 'informative', 'Les bibliothèques prolongent leurs horaires pendant la fête', 'Dans de nombreuses villes, les bibliothèques resteront ouvertes jusqu’à 20 h pendant les demi-fêtes, avec heures du conte et animations. Le prêt est gratuit pour les résidents.'),
  ('3e4fe478-2d00-55e3-9162-6192828e557d', 'fr', 'general', 'calm', 'Des bibliothèques ouvertes plus tard', 'Beaucoup de bibliothèques municipales ouvriront le soir cette semaine, avec l’heure du conte pour les enfants.'),
  ('3e4fe478-2d00-55e3-9162-6192828e557d', 'he', 'youth', 'light', 'הספרייה פתוחה עד הערב', 'בחופש ספריות רבות פתוחות עד מאוחר, עם פעילויות וסיפורים. מקום טוב למצוא ספר חדש.'),
  ('3e4fe478-2d00-55e3-9162-6192828e557d', 'he', 'youth', 'calm', 'ספריות פתוחות יותר שעות בחופש', 'בחול המועד ספריות רבות פתוחות עד הערב. אפשר לשאול ספרים בחינם.'),
  ('43a3a7b2-1d07-5082-8a7c-e1d8e17c89b6', 'he', 'general', 'calm', 'טלסקופ חלל צילם ענן גז בצורת ורד', 'התמונה החדשה מראה ערפילית שבה נולדים כוכבים, במרחק אלפי שנות אור. החוקרים ישתמשו בה כדי להבין איך נוצרות מערכות שמש.'),
  ('43a3a7b2-1d07-5082-8a7c-e1d8e17c89b6', 'he', 'general', 'human', 'אסטרונומית: "ישבתי מול התמונה דקות ארוכות"', 'חוקרים ברחבי העולם התרגשו מתמונה חדשה של ענן גז בצורת ורד, שבו נולדים כוכבים. "זה מזכיר לנו כמה היקום יפה", אמרה אחת מהן.'),
  ('43a3a7b2-1d07-5082-8a7c-e1d8e17c89b6', 'he', 'general', 'informative', 'תמונה חדשה: ערפילית בצורת ורד במרחק אלפי שנות אור', 'טלסקופ חלל צילם ענן גז ואבק שבו נוצרים כוכבים חדשים. הנתונים יסייעו לחקר היווצרות מערכות שמש. התמונה פורסמה לציבור.'),
  ('43a3a7b2-1d07-5082-8a7c-e1d8e17c89b6', 'he', 'general', 'light', 'היקום שלח לנו גלויה', 'טלסקופ חלל צילם ענן גז בצורת ורד, ובתוכו נולדים כוכבים. שווה לחפש את התמונה ולהגדיל על המסך.'),
  ('43a3a7b2-1d07-5082-8a7c-e1d8e17c89b6', 'en', 'general', 'informative', 'New image: a nebula shaped like a rose', 'A space telescope has photographed a cloud of gas and dust where new stars are forming, thousands of light-years away. The data will help research into how solar systems form.'),
  ('43a3a7b2-1d07-5082-8a7c-e1d8e17c89b6', 'en', 'general', 'calm', 'A space telescope captures a star nursery', 'The new image shows a gas cloud shaped like a rose, where stars are being born. Researchers will use it to learn how solar systems take shape.'),
  ('43a3a7b2-1d07-5082-8a7c-e1d8e17c89b6', 'fr', 'general', 'informative', 'Nouvelle image : une nébuleuse en forme de une rose', 'Un télescope spatial a photographié un nuage de gaz et de poussière où naissent des étoiles, à des milliers d’années-lumière. Les données aideront à comprendre la formation des systèmes solaires.'),
  ('43a3a7b2-1d07-5082-8a7c-e1d8e17c89b6', 'fr', 'general', 'calm', 'Un télescope spatial photographie une pouponnière d’étoiles', 'L’image montre un nuage de gaz en forme de une rose, où naissent des étoiles. Les chercheurs l’étudieront pour comprendre la naissance des systèmes solaires.'),
  ('43a3a7b2-1d07-5082-8a7c-e1d8e17c89b6', 'he', 'youth', 'light', 'ענן בחלל בצורת ורד', 'טלסקופ חלל צילם ענן ענק של גז ואבק, ובתוכו נולדים כוכבים חדשים. חפשו את התמונה, היא מדהימה.'),
  ('43a3a7b2-1d07-5082-8a7c-e1d8e17c89b6', 'he', 'youth', 'calm', 'תמונה חדשה מהחלל', 'טלסקופ צילם ענן גז בצורת ורד שבו נולדים כוכבים. מדענים לומדים ממנו איך נוצרות מערכות שמש.'),
  ('0d76818b-1f5a-531e-aff1-445f4bb5dfb2', 'he', 'general', 'calm', 'עבודות מתוכננות: הפסקת מים לילית בצפת', 'בשכונות אחדות בצפת לא יהיו מים הלילה בין 00:00–05:00, בשל החלפת צנרת. בבוקר האספקה תחזור כרגיל.'),
  ('0d76818b-1f5a-531e-aff1-445f4bb5dfb2', 'he', 'general', 'human', 'תושבי צפת ממלאים קומקום לפני השינה', '"שמתי בקבוק ליד המיטה ומילאתי קומקום לקפה של הבוקר", מספר תושב. בשכונות אחדות לא יהיו מים הלילה בין 00:00–05:00.'),
  ('0d76818b-1f5a-531e-aff1-445f4bb5dfb2', 'he', 'general', 'informative', 'צפת: הפסקת מים מתוכננת בין 00:00–05:00', 'תאגיד המים מחליף צנרת ראשית. ההפסקה הלילה תחול על כמה שכונות, והרשימה המלאה באתר התאגיד. אחרי החידוש ייתכן צבע עכור במים לכמה דקות.'),
  ('0d76818b-1f5a-531e-aff1-445f4bb5dfb2', 'he', 'general', 'light', 'מקלחת מוקדמת הערב, תושבי צפת', 'בשכונות אחדות לא יהיו מים הלילה בין 00:00–05:00, כי מחליפים צנרת. ממלאים קומקום, והבוקר הכל זורם.'),
  ('a1f79cbd-1e73-5b72-b74b-bc2477074974', 'he', 'general', 'calm', 'פארק המסילה נפתח מחדש אחרי שיפוץ', 'בפארק נוספו מתקני משחק מוצלים, ברזיות ושבילי הליכה מוארים. הוא פתוח מהבוקר ועד חצות.'),
  ('a1f79cbd-1e73-5b72-b74b-bc2477074974', 'he', 'general', 'informative', 'פארק המסילה: הפארק נפתח אחרי שיפוץ של חצי שנה', 'נוספו מתקני משחק מוצלים, ברזיות, תאורה בשבילים ופינת כושר. שעות הפעילות: 06:00–24:00.'),
  ('4ad785d9-1179-5dae-9f67-f050c428100f', 'he', 'general', 'calm', 'חם מהרגיל מחר, ובערב נעים יותר', 'הטמפרטורות יגיעו לכ־36 מעלות בבקעת הירדן ובערבה. מספיק לשתות מים ולהישאר בצל בשעות הצהריים. בערב צפויה הקלה.'),
  ('4ad785d9-1179-5dae-9f67-f050c428100f', 'he', 'general', 'human', 'מי שעובד בחוץ ירגיש את החום מחר', 'פועלי בניין, שליחים וחקלאים בבקעת הירדן ובערבה יפגשו כ־36 מעלות. "אנחנו מתחילים מוקדם ומסיימים לפני הצהריים", מספר מנהל עבודה. בערב צפויה הקלה.'),
  ('4ad785d9-1179-5dae-9f67-f050c428100f', 'he', 'general', 'informative', '36 מעלות בבקעת הירדן ובערבה מחר, הקלה בערב', 'עומס חום בינוני בבקעת הירדן ובערבה: עד 36 מעלות בשעות הצהריים. משרד הבריאות ממליץ לשתות באופן קבוע ולהימנע ממאמץ בשמש בין 11:00 ל־16:00.'),
  ('4ad785d9-1179-5dae-9f67-f050c428100f', 'he', 'general', 'light', 'הכובע והבקבוק חוזרים לתיק', 'מחר יהיה חם, עד 36 מעלות בבקעת הירדן ובערבה. מים קרים, צל טוב ומזגן בטמפרטורה סבירה, והערב כבר יהיה נעים יותר.'),
  ('4ad785d9-1179-5dae-9f67-f050c428100f', 'en', 'general', 'informative', 'Up to 36°C in the Jordan Valley and the Arava tomorrow', 'A moderate heat load is expected in the Jordan Valley and the Arava, peaking around midday. Israel’s Health Ministry advises drinking regularly and avoiding exertion in the sun between 11:00 and 16:00.'),
  ('4ad785d9-1179-5dae-9f67-f050c428100f', 'en', 'general', 'calm', 'A hot day, with a pleasant evening', 'Temperatures will reach about 36°C in the Jordan Valley and the Arava tomorrow. Water and some shade at midday are enough; the evening will be cooler.'),
  ('4ad785d9-1179-5dae-9f67-f050c428100f', 'fr', 'general', 'informative', 'Jusqu’à 36 °C dans la vallée du Jourdain et l’Arava demain', 'Une chaleur modérée est attendue dans la vallée du Jourdain et l’Arava, avec un pic vers midi. Le ministère israélien de la Santé conseille de boire régulièrement et d’éviter l’effort au soleil entre 11 h et 16 h.'),
  ('4ad785d9-1179-5dae-9f67-f050c428100f', 'fr', 'general', 'calm', 'Une journée chaude, une soirée plus douce', 'Les températures atteindront environ 36 °C dans la vallée du Jourdain et l’Arava demain. De l’eau et un peu d’ombre à midi suffisent ; la soirée sera plus fraîche.'),
  ('4ad785d9-1179-5dae-9f67-f050c428100f', 'he', 'youth', 'light', 'יום חם: בקבוק מים הוא החבר הכי טוב שלכם', 'מחר החום יגיע לכ־36 מעלות בבקעת הירדן ובערבה. בהפסקות כדאי לשבת בצל ולשתות, גם כשלא מרגישים צמאים.'),
  ('4ad785d9-1179-5dae-9f67-f050c428100f', 'he', 'youth', 'calm', 'חם מחר, ובערב יהיה נעים', 'הטמפרטורות יגיעו לכ־36 מעלות. שותים מים, נשארים בצל בצהריים, ובערב כבר יהיה קריר יותר.'),
  ('99bf6362-4e98-5f90-8e98-a2e069745abb', 'he', 'general', 'calm', 'עבודות תחזוקה ברכבת בין ירושלים לנתב״ג במוצאי השבת הקרובה', 'הרכבות בין ירושלים לנתב״ג לא יפעלו במוצאי השבת הקרובה אחרי 22:00. יופעלו אוטובוסים חלופיים מהתחנות, ובבוקר התנועה תחזור לשגרה.'),
  ('99bf6362-4e98-5f90-8e98-a2e069745abb', 'he', 'general', 'human', 'נוסעי הלילה בין ירושלים לנתב״ג יעברו לאוטובוסים', 'מי שחוזר מאוחר מהעבודה יצטרך לתכנן מחדש במוצאי השבת הקרובה. "העיקר שיש הסעה חלופית", אומר נוסע קבוע. הרכבות יחזרו לפעול בבוקר.'),
  ('99bf6362-4e98-5f90-8e98-a2e069745abb', 'he', 'general', 'informative', 'הרכבת בין ירושלים לנתב״ג: הפסקת תנועה במוצאי השבת הקרובה מ־22:00', 'בשל עבודות תחזוקה לא יפעלו רכבות בין ירושלים לנתב״ג במוצאי השבת הקרובה מ־22:00 ועד תחילת השירות בבוקר. אוטובוסים חלופיים ייצאו מהתחנות כל 20 דקות.'),
  ('99bf6362-4e98-5f90-8e98-a2e069745abb', 'he', 'general', 'light', 'הרכבת לוקחת כמה לילות לטיפוח', 'עבודות תחזוקה בין ירושלים לנתב״ג במוצאי השבת הקרובה: אחרי 22:00 עוברים לאוטובוסים החלופיים. בבוקר הכל חוזר למסלול.'),
  ('99bf6362-4e98-5f90-8e98-a2e069745abb', 'en', 'general', 'informative', 'Trains between Jerusalem and Ben Gurion Airport: no service after 22:00 on Saturday night', 'Because of maintenance works, Israel Railways will not run trains between Jerusalem and Ben Gurion Airport from 22:00 until the morning service on Saturday night. Replacement buses leave the stations every 20 minutes.'),
  ('99bf6362-4e98-5f90-8e98-a2e069745abb', 'en', 'general', 'calm', 'Night maintenance on the railway between Jerusalem and Ben Gurion Airport', 'Trains between Jerusalem and Ben Gurion Airport will not run after 22:00 on Saturday night. Replacement buses are available, and service returns to normal in the morning.'),
  ('99bf6362-4e98-5f90-8e98-a2e069745abb', 'fr', 'general', 'informative', 'Trains entre Jérusalem et l’aéroport Ben-Gourion : pas de service après 22 h samedi soir', 'En raison de travaux, les Chemins de fer israéliens n’assureront aucun train entre Jérusalem et l’aéroport Ben-Gourion de 22 h jusqu’au premier départ du matin samedi soir. Des bus de remplacement partent toutes les 20 minutes.'),
  ('99bf6362-4e98-5f90-8e98-a2e069745abb', 'fr', 'general', 'calm', 'Travaux de nuit sur la ligne entre Jérusalem et l’aéroport Ben-Gourion', 'Les trains entre Jérusalem et l’aéroport Ben-Gourion ne circuleront pas après 22 h samedi soir. Des bus de remplacement sont prévus et le service reprend normalement le matin.'),
  ('99bf6362-4e98-5f90-8e98-a2e069745abb', 'he', 'youth', 'light', 'הרכבת עושה חופשה קצרה בלילות', 'בגלל עבודות, הרכבות בין ירושלים לנתב״ג לא ייסעו במוצאי השבת הקרובה אחרי 22:00. במקומן יהיו אוטובוסים.'),
  ('99bf6362-4e98-5f90-8e98-a2e069745abb', 'he', 'youth', 'calm', 'שינוי ברכבת בין ירושלים לנתב״ג', 'הרכבות בין ירושלים לנתב״ג לא יפעלו במוצאי השבת הקרובה אחרי 22:00. יהיו אוטובוסים חלופיים, ובבוקר הכל חוזר לרגיל.'),
  ('fba3dec4-bb15-5038-b767-84473000091a', 'he', 'general', 'calm', 'מרוץ לילה בתל אביב־יפו: כבישים ייסגרו בערב', 'אלפי רצים ישתתפו במרוץ העירוני. רחובות במרכז העיר ייסגרו בין 19:00–23:30, ומומלץ להגיע ברגל או בתחבורה ציבורית.'),
  ('fba3dec4-bb15-5038-b767-84473000091a', 'he', 'general', 'human', 'רצים חובבים מתכוננים למרוץ הלילה בתל אביב־יפו', '"אני רצה לכבוד אבא שלי, זו השנה הראשונה שלי", מספרת משתתפת. המרוץ יתקיים הערב, וחלק מהרחובות ייסגרו בין 19:00–23:30.'),
  ('fba3dec4-bb15-5038-b767-84473000091a', 'he', 'general', 'informative', 'תל אביב־יפו: סגירת רחובות בין 19:00–23:30 בשל מרוץ לילה', 'המרוץ העירוני יתקיים במקצים של 5, 10 ו־21 ק״מ. מפת הסגירות מתפרסמת באתר העירייה. קווי אוטובוס יוסטו למסלולים חלופיים.'),
  ('fba3dec4-bb15-5038-b767-84473000091a', 'he', 'general', 'light', 'נעלי ריצה, פנסי רחוב, יוצאים לדרך', 'מרוץ הלילה בתל אביב־יפו חוזר. מי שלא רץ יכול לעודד, ומי שנוהג כדאי שיעקוף: סגירות בין 19:00–23:30.'),
  ('fba3dec4-bb15-5038-b767-84473000091a', 'en', 'general', 'informative', 'Tel Aviv-Yafo: road closures 19:00–23:30 for a night run', 'The city run includes 5, 10 and 21 km races. A closure map is on the municipality’s website, and bus lines will be diverted.'),
  ('fba3dec4-bb15-5038-b767-84473000091a', 'en', 'general', 'calm', 'Night run in Tel Aviv-Yafo this evening', 'Thousands of runners will take part. Some central streets will close between 19:00–23:30; walking or public transport is recommended.'),
  ('fba3dec4-bb15-5038-b767-84473000091a', 'fr', 'general', 'informative', 'Tel-Aviv-Jaffa : rues fermées de 19:00–23:30 pour une course de nuit', 'La course comprend des épreuves de 5, 10 et 21 km. Le plan des fermetures est sur le site de la mairie ; des lignes de bus seront déviées.'),
  ('fba3dec4-bb15-5038-b767-84473000091a', 'fr', 'general', 'calm', 'Course de nuit à Tel-Aviv-Jaffa ce soir', 'Des milliers de coureurs y participent. Certaines rues du centre seront fermées de 19:00–23:30 ; privilégiez la marche ou les transports en commun.'),
  ('d29c8a34-5d0b-5b86-b3c5-b7389d4dc37b', 'he', 'general', 'calm', 'תרגיל של פיקוד העורף במחוז הצפון: הצופר הוא חלק מהתרגיל', 'מחר בשעה 11:00 יישמע צופר במחוז הצפון במסגרת תרגיל מתוכנן. אין צורך לעשות דבר מלבד להמשיך בשגרה. בתי הספר ישתתפו בתרגיל.'),
  ('d29c8a34-5d0b-5b86-b3c5-b7389d4dc37b', 'he', 'general', 'human', 'גננות ומורים במחוז הצפון מכינים את הילדים לתרגיל', '"הסברנו מראש שזה רק תרגול, והילדים התייחסו לזה כמו למשחק", מספרת גננת. מחר בשעה 11:00 יישמע צופר כחלק מתרגיל מתוכנן.'),
  ('d29c8a34-5d0b-5b86-b3c5-b7389d4dc37b', 'he', 'general', 'informative', 'מחר ב־11:00: צופר תרגיל במחוז הצפון', 'פיקוד העורף יקיים תרגיל מתוכנן במחוז הצפון, כולל הפעלת צופר בשעה 11:00. אין הנחיות מיוחדות לציבור. מוסדות החינוך יתרגלו כניסה למרחב מוגן.'),
  ('d29c8a34-5d0b-5b86-b3c5-b7389d4dc37b', 'he', 'general', 'light', 'תרגיל של פיקוד העורף במחוז הצפון: הצופר הוא חלק מהתרגיל', 'מחר בשעה 11:00 יישמע צופר במסגרת תרגיל מתוכנן. אין צורך לעשות דבר מלבד להמשיך בשגרה.'),
  ('d29c8a34-5d0b-5b86-b3c5-b7389d4dc37b', 'en', 'general', 'informative', 'Home Front Command drill in the northern district tomorrow at 11:00', 'The Home Front Command, the army body responsible for civil protection, will hold a planned drill in the northern district, including a siren at 11:00. No action is required from the public.'),
  ('d29c8a34-5d0b-5b86-b3c5-b7389d4dc37b', 'en', 'general', 'calm', 'The siren tomorrow in the northern district is only a drill', 'A siren will sound tomorrow at 11:00 as part of a planned Home Front Command drill. There is nothing to do but carry on with your day.'),
  ('d29c8a34-5d0b-5b86-b3c5-b7389d4dc37b', 'fr', 'general', 'informative', 'Exercice du Commandement du front intérieur dans le district Nord demain à 11:00', 'Le Commandement du front intérieur, chargé de la protection civile, organise un exercice dans le district Nord, avec une sirène à 11:00. Aucune consigne particulière pour le public.'),
  ('d29c8a34-5d0b-5b86-b3c5-b7389d4dc37b', 'fr', 'general', 'calm', 'La sirène de demain dans le district Nord n’est qu’un exercice', 'Une sirène retentira demain à 11:00 dans le cadre d’un exercice prévu. Il suffit de poursuivre sa journée normalement.'),
  ('1655cadb-5d04-5136-b250-0bc9c0c49723', 'he', 'general', 'calm', 'הודעות מזויפות על זכייה בהגרלה: לא לשלם דרך קישור', 'מתקבלות הודעות SMS שמבקשות תשלום קטן על זכייה בהגרלה. גופים רשמיים לא מבקשים פרטי אשראי בהודעה. אם יש ספק, נכנסים לאתר הרשמי ישירות.'),
  ('1655cadb-5d04-5136-b250-0bc9c0c49723', 'he', 'general', 'human', '"כמעט שילמתי 12 שקלים על חבילה שלא הזמנתי"', 'גמלאית מהמרכז קיבלה הודעה על זכייה בהגרלה ועצרה רגע לפני התשלום. המשטרה מזכירה: לא לוחצים על קישורים בהודעות כאלה.'),
  ('1655cadb-5d04-5136-b250-0bc9c0c49723', 'he', 'general', 'informative', 'אזהרה: הודעות SMS מתחזות בנושא זכייה בהגרלה', 'הונאה חוזרת: הודעה עם קישור לתשלום קטן על זכייה בהגרלה. הקישור מוביל לאתר מתחזה שאוסף פרטי אשראי. מי שמסר פרטים צריך לפנות מיד לחברת האשראי.'),
  ('1655cadb-5d04-5136-b250-0bc9c0c49723', 'he', 'general', 'light', 'הודעה על זכייה בהגרלה? קודם נושמים', 'נוכלים שולחים הודעות עם קישור לתשלום קטן על זכייה בהגרלה. הכלל פשוט: לא לוחצים, נכנסים לבד לאתר הרשמי.'),
  ('5e89d5c9-ec90-5463-824b-6143fd447824', 'he', 'general', 'calm', 'נבחרת הנוער בכדוריד עלתה לרבע הגמר באליפות אירופה', 'הנבחרת ניצחה אתמול בשני משחקים רצופים. המשחק הבא ישודר בערוצי הספורט, והשחקנים מספרים שהם ממוקדים ורגועים.'),
  ('5e89d5c9-ec90-5463-824b-6143fd447824', 'he', 'general', 'human', 'ההורים ביציע לא הפסיקו לשיר', 'נבחרת הנוער בכדוריד עלתה לרבע הגמר באליפות אירופה. "הם שיחקו בשביל החברים שלהם בבית", אמר המאמן אחרי הניצחון.'),
  ('5e89d5c9-ec90-5463-824b-6143fd447824', 'he', 'general', 'informative', 'נבחרת הנוער בכדוריד: עלייה לרבע הגמר באליפות אירופה', 'אחרי שני ניצחונות רצופים הבטיחה הנבחרת את מקומה לרבע הגמר. המשחק הבא בסוף השבוע ישודר בשידור חי.'),
  ('5e89d5c9-ec90-5463-824b-6143fd447824', 'he', 'general', 'light', 'הנוער שלנו בכדוריד ממשיך לטפס', 'עוד ניצחון, ועוד שלב: נבחרת הנוער בכדוריד עלתה לרבע הגמר באליפות אירופה. הדגלים כבר במרפסות.'),
  ('5e89d5c9-ec90-5463-824b-6143fd447824', 'en', 'general', 'informative', 'Israel’s youth handball team reaches the quarter-finals', 'After two consecutive wins, the team has secured its place in the quarter-finals of the European championship. The next match, this weekend, will be broadcast live.'),
  ('5e89d5c9-ec90-5463-824b-6143fd447824', 'en', 'general', 'calm', 'Youth handball team advances in Europe', 'Israel’s youth team has reached the quarter-finals of the European championship after two wins in a row.'),
  ('5e89d5c9-ec90-5463-824b-6143fd447824', 'fr', 'general', 'informative', 'L’équipe israélienne junior de handball en les quarts de finale', 'Après deux victoires consécutives, l’équipe s’est qualifiée pour les quarts de finale du championnat d’Europe. Le prochain match, ce week-end, sera diffusé en direct.'),
  ('5e89d5c9-ec90-5463-824b-6143fd447824', 'fr', 'general', 'calm', 'L’équipe junior de handball poursuit sa route', 'L’équipe israélienne des jeunes s’est qualifiée pour les quarts de finale du championnat d’Europe après deux victoires.'),
  ('5e89d5c9-ec90-5463-824b-6143fd447824', 'he', 'youth', 'light', 'נבחרת הנוער בכדוריד בדרך למעלה', 'שני ניצחונות ברצף, והנבחרת עלתה לרבע הגמר באליפות אירופה. המשחק הבא בסוף השבוע.'),
  ('5e89d5c9-ec90-5463-824b-6143fd447824', 'he', 'youth', 'calm', 'הצלחה לנבחרת הנוער בכדוריד', 'הנבחרת עלתה לרבע הגמר באליפות אירופה אחרי שני ניצחונות.'),
  ('5c83617c-385b-5126-8408-15ebe087b3f3', 'he', 'general', 'calm', 'טלסקופ חלל צילם ענן גז בצורת פרפר', 'התמונה החדשה מראה ערפילית שבה נולדים כוכבים, במרחק אלפי שנות אור. החוקרים ישתמשו בה כדי להבין איך נוצרות מערכות שמש.'),
  ('5c83617c-385b-5126-8408-15ebe087b3f3', 'he', 'general', 'human', 'אסטרונומית: "ישבתי מול התמונה דקות ארוכות"', 'חוקרים ברחבי העולם התרגשו מתמונה חדשה של ענן גז בצורת פרפר, שבו נולדים כוכבים. "זה מזכיר לנו כמה היקום יפה", אמרה אחת מהן.'),
  ('5c83617c-385b-5126-8408-15ebe087b3f3', 'he', 'general', 'informative', 'תמונה חדשה: ערפילית בצורת פרפר במרחק אלפי שנות אור', 'טלסקופ חלל צילם ענן גז ואבק שבו נוצרים כוכבים חדשים. הנתונים יסייעו לחקר היווצרות מערכות שמש. התמונה פורסמה לציבור.'),
  ('5c83617c-385b-5126-8408-15ebe087b3f3', 'he', 'general', 'light', 'היקום שלח לנו גלויה', 'טלסקופ חלל צילם ענן גז בצורת פרפר, ובתוכו נולדים כוכבים. שווה לחפש את התמונה ולהגדיל על המסך.'),
  ('5c83617c-385b-5126-8408-15ebe087b3f3', 'en', 'general', 'informative', 'New image: a nebula shaped like a butterfly', 'A space telescope has photographed a cloud of gas and dust where new stars are forming, thousands of light-years away. The data will help research into how solar systems form.'),
  ('5c83617c-385b-5126-8408-15ebe087b3f3', 'en', 'general', 'calm', 'A space telescope captures a star nursery', 'The new image shows a gas cloud shaped like a butterfly, where stars are being born. Researchers will use it to learn how solar systems take shape.'),
  ('5c83617c-385b-5126-8408-15ebe087b3f3', 'fr', 'general', 'informative', 'Nouvelle image : une nébuleuse en forme de un papillon', 'Un télescope spatial a photographié un nuage de gaz et de poussière où naissent des étoiles, à des milliers d’années-lumière. Les données aideront à comprendre la formation des systèmes solaires.'),
  ('5c83617c-385b-5126-8408-15ebe087b3f3', 'fr', 'general', 'calm', 'Un télescope spatial photographie une pouponnière d’étoiles', 'L’image montre un nuage de gaz en forme de un papillon, où naissent des étoiles. Les chercheurs l’étudieront pour comprendre la naissance des systèmes solaires.'),
  ('5c83617c-385b-5126-8408-15ebe087b3f3', 'he', 'youth', 'light', 'ענן בחלל בצורת פרפר', 'טלסקופ חלל צילם ענן ענק של גז ואבק, ובתוכו נולדים כוכבים חדשים. חפשו את התמונה, היא מדהימה.'),
  ('5c83617c-385b-5126-8408-15ebe087b3f3', 'he', 'youth', 'calm', 'תמונה חדשה מהחלל', 'טלסקופ צילם ענן גז בצורת פרפר שבו נולדים כוכבים. מדענים לומדים ממנו איך נוצרות מערכות שמש.'),
  ('d85ab7c4-185c-571b-b364-a2c5adb8bf0d', 'he', 'general', 'calm', 'מדינות אירופה מתאמות כללים חדשים לאריזות', 'התוכנית שמתגבשת נועדה להפחית אריזות חד־פעמיות בשנים הקרובות. היא לא משנה דבר בישראל כרגע, אבל יצואנים כבר לומדים את הכללים.'),
  ('d85ab7c4-185c-571b-b364-a2c5adb8bf0d', 'he', 'general', 'human', 'יצרנים קטנים באירופה לומדים לארוז אחרת', 'בעלת מאפייה משפחתית מספרת שעברה לשקיות נייר "והלקוחות אפילו לא שמו לב". מדינות אירופה מתאמות כללים חדשים לצמצום אריזות.'),
  ('d85ab7c4-185c-571b-b364-a2c5adb8bf0d', 'he', 'general', 'informative', 'אירופה: תוכנית משותפת לצמצום אריזות חד־פעמיות', 'המדינות מתאמות יעדים להפחתת אריזות פלסטיק ולהגדלת השימוש החוזר. היעדים ייכנסו בהדרגה בשנים הקרובות, ויחולו גם על מוצרים מיובאים.'),
  ('d85ab7c4-185c-571b-b364-a2c5adb8bf0d', 'he', 'general', 'light', 'אירופה עושה דיאטה לאריזות', 'המדינות מתאמות כללים חדשים שיצמצמו פלסטיק חד־פעמי. אולי בקרוב נפתח חבילה בלי לחפש מספריים.'),
  ('d85ab7c4-185c-571b-b364-a2c5adb8bf0d', 'en', 'general', 'informative', 'Europe coordinates a plan to cut single-use packaging', 'European countries are aligning targets to reduce plastic packaging and expand reuse. The targets will be phased in over the coming years and will also apply to imported products.'),
  ('d85ab7c4-185c-571b-b364-a2c5adb8bf0d', 'en', 'general', 'calm', 'New packaging rules take shape in Europe', 'The plan aims to reduce single-use packaging over the next few years. Nothing changes in Israel for now, though exporters are already studying the rules.'),
  ('d85ab7c4-185c-571b-b364-a2c5adb8bf0d', 'fr', 'general', 'informative', 'L’Europe coordonne un plan contre les emballages jetables', 'Les pays européens harmonisent leurs objectifs pour réduire les emballages plastiques et développer la réutilisation. Ils s’appliqueront progressivement, y compris aux produits importés.'),
  ('d85ab7c4-185c-571b-b364-a2c5adb8bf0d', 'fr', 'general', 'calm', 'De nouvelles règles d’emballage en Europe', 'Le plan vise à réduire les emballages jetables dans les prochaines années. Rien ne change en Israël pour l’instant, mais les exportateurs s’y préparent.'),
  ('d85ab7c4-185c-571b-b364-a2c5adb8bf0d', 'he', 'youth', 'light', 'פחות פלסטיק, יותר ים נקי', 'מדינות אירופה מתכננות כללים שיקטינו את כמות האריזות החד־פעמיות. מי יודע, אולי גם אצלנו.'),
  ('d85ab7c4-185c-571b-b364-a2c5adb8bf0d', 'he', 'youth', 'calm', 'אירופה רוצה פחות אריזות', 'מדינות אירופה מתכננות יחד איך להשתמש בפחות פלסטיק חד־פעמי בשנים הבאות.'),
  ('63db58cc-29e9-50cf-895c-707cbf10c30c', 'he', 'general', 'calm', 'כביש 1 ייסגר בלילה בין שער הגיא למחלף הראל', 'בגלל עבודות גישור כביש 1 ייסגר הלילה בין שער הגיא למחלף הראל בין 22:00–05:00. התנועה תופנה לדרכים חלופיות מסומנות, ובבוקר הכביש ייפתח כרגיל.'),
  ('63db58cc-29e9-50cf-895c-707cbf10c30c', 'he', 'general', 'human', 'נהגי המשאיות מתכננים מסלול אחר הלילה', 'כביש 1 ייסגר בין שער הגיא למחלף הראל בין 22:00–05:00. "נצא שעה מוקדם יותר ונעבור בדרך החלופית", אומר נהג הובלות. בבוקר הכביש ייפתח.'),
  ('63db58cc-29e9-50cf-895c-707cbf10c30c', 'he', 'general', 'informative', 'כביש 1 ייסגר בין שער הגיא למחלף הראל בין 22:00–05:00', 'סגירה לילית לצורך עבודות גישור. התנועה תופנה לדרכים חלופיות עם שילוט. צפויים עיכובים של 15–20 דקות. הפתיחה לפני שעות העומס של הבוקר.'),
  ('63db58cc-29e9-50cf-895c-707cbf10c30c', 'he', 'general', 'light', 'נהגי לילה, שימו לב: עוקפים הלילה', 'כביש 1 ייסגר בין שער הגיא למחלף הראל בין 22:00–05:00. השלטים יובילו אתכם בדרך חלופית, והבוקר ייפתח בזמן לפקקים הרגילים.'),
  ('63db58cc-29e9-50cf-895c-707cbf10c30c', 'en', 'general', 'informative', 'Route 1 closed between Sha’ar HaGai and the Harel interchange overnight, 22:00–05:00', 'An overnight closure for bridge works: traffic will be diverted to signposted alternative roads, with delays of 15–20 minutes. The road reopens before the morning rush.'),
  ('63db58cc-29e9-50cf-895c-707cbf10c30c', 'en', 'general', 'calm', 'Overnight closure on Route 1', 'Route 1 will close between Sha’ar HaGai and the Harel interchange between 22:00–05:00 for bridge works. Diversions are signposted, and the road reopens as usual in the morning.'),
  ('63db58cc-29e9-50cf-895c-707cbf10c30c', 'fr', 'general', 'informative', 'la route 1 fermée entre Shaar HaGaï et l’échangeur Harel cette nuit, 22:00–05:00', 'Fermeture nocturne pour travaux sur un pont : déviation balisée, avec 15 à 20 minutes de retard. Réouverture avant les heures de pointe du matin.'),
  ('63db58cc-29e9-50cf-895c-707cbf10c30c', 'fr', 'general', 'calm', 'Fermeture de nuit sur la route 1', 'la route 1 sera fermée entre Shaar HaGaï et l’échangeur Harel entre 22:00–05:00 pour des travaux. Les déviations sont indiquées et la route rouvre normalement le matin.'),
  ('a572fa95-e4a9-5265-80a9-e1f638b06926', 'he', 'general', 'calm', 'הודעות מזויפות על חוב בחשבון החשמל: לא לשלם דרך קישור', 'מתקבלות הודעות SMS שמבקשות תשלום קטן על חוב בחשבון החשמל. גופים רשמיים לא מבקשים פרטי אשראי בהודעה. אם יש ספק, נכנסים לאתר הרשמי ישירות.'),
  ('a572fa95-e4a9-5265-80a9-e1f638b06926', 'he', 'general', 'human', '"כמעט שילמתי 12 שקלים על חבילה שלא הזמנתי"', 'גמלאית מהמרכז קיבלה הודעה על חוב בחשבון החשמל ועצרה רגע לפני התשלום. המשטרה מזכירה: לא לוחצים על קישורים בהודעות כאלה.'),
  ('a572fa95-e4a9-5265-80a9-e1f638b06926', 'he', 'general', 'informative', 'אזהרה: הודעות SMS מתחזות בנושא חוב בחשבון החשמל', 'הונאה חוזרת: הודעה עם קישור לתשלום קטן על חוב בחשבון החשמל. הקישור מוביל לאתר מתחזה שאוסף פרטי אשראי. מי שמסר פרטים צריך לפנות מיד לחברת האשראי.'),
  ('a572fa95-e4a9-5265-80a9-e1f638b06926', 'he', 'general', 'light', 'הודעה על חוב בחשבון החשמל? קודם נושמים', 'נוכלים שולחים הודעות עם קישור לתשלום קטן על חוב בחשבון החשמל. הכלל פשוט: לא לוחצים, נכנסים לבד לאתר הרשמי.'),
  ('a572fa95-e4a9-5265-80a9-e1f638b06926', 'en', 'general', 'informative', 'Warning: fake text messages about an unpaid electricity bill', 'A recurring scam asks for a small payment for an unpaid electricity bill through a link. The site collects card details. Anyone who entered them should contact their credit card company at once.'),
  ('a572fa95-e4a9-5265-80a9-e1f638b06926', 'en', 'general', 'calm', 'Don’t pay through links in text messages', 'Some people are receiving messages asking for a small payment for an unpaid electricity bill. Official bodies do not ask for card details by SMS; when in doubt, go to the official website directly.'),
  ('a572fa95-e4a9-5265-80a9-e1f638b06926', 'fr', 'general', 'informative', 'Alerte : faux SMS concernant une facture d’électricité impayée', 'Une arnaque récurrente réclame un petit paiement pour une facture d’électricité impayée via un lien. Le site collecte les données de carte. En cas de saisie, contactez immédiatement votre banque.'),
  ('a572fa95-e4a9-5265-80a9-e1f638b06926', 'fr', 'general', 'calm', 'Ne payez pas via un lien reçu par SMS', 'Des messages demandent un petit paiement pour une facture d’électricité impayée. Les organismes officiels ne demandent pas de coordonnées bancaires par SMS ; en cas de doute, allez directement sur le site officiel.'),
  ('a572fa95-e4a9-5265-80a9-e1f638b06926', 'he', 'youth', 'light', 'קיבלתם הודעה מוזרה עם קישור? אל תלחצו', 'נוכלים שולחים הודעות על חוב בחשבון החשמל ומבקשים לשלם. תמיד מראים להורים לפני שלוחצים על משהו.'),
  ('a572fa95-e4a9-5265-80a9-e1f638b06926', 'he', 'youth', 'calm', 'הודעות מזויפות בטלפון', 'יש הודעות שמבקשות לשלם על חוב בחשבון החשמל. לא לוחצים על הקישור ומספרים למבוגר.'),
  ('4ed6602f-44f9-5145-933d-f8f066bf8a99', 'he', 'general', 'calm', 'חם מהרגיל היום, ובערב נעים יותר', 'הטמפרטורות יגיעו לכ־31 מעלות בגליל העליון. מספיק לשתות מים ולהישאר בצל בשעות הצהריים. בערב צפויה הקלה.'),
  ('4ed6602f-44f9-5145-933d-f8f066bf8a99', 'he', 'general', 'human', 'מי שעובד בחוץ ירגיש את החום היום', 'פועלי בניין, שליחים וחקלאים בגליל העליון יפגשו כ־31 מעלות. "אנחנו מתחילים מוקדם ומסיימים לפני הצהריים", מספר מנהל עבודה. בערב צפויה הקלה.'),
  ('4ed6602f-44f9-5145-933d-f8f066bf8a99', 'he', 'general', 'informative', '31 מעלות בגליל העליון היום, הקלה בערב', 'עומס חום בינוני בגליל העליון: עד 31 מעלות בשעות הצהריים. משרד הבריאות ממליץ לשתות באופן קבוע ולהימנע ממאמץ בשמש בין 11:00 ל־16:00.'),
  ('4ed6602f-44f9-5145-933d-f8f066bf8a99', 'he', 'general', 'light', 'הכובע והבקבוק חוזרים לתיק', 'היום יהיה חם, עד 31 מעלות בגליל העליון. מים קרים, צל טוב ומזגן בטמפרטורה סבירה, והערב כבר יהיה נעים יותר.'),
  ('dd5b48ea-5879-51af-9a42-0bf3194809c3', 'he', 'general', 'calm', 'עבודות תשתית בגן סאקר: שינויים קלים בתנועה', 'העירייה מחליפה צנרת ומדרכות בגן סאקר. הרחוב פתוח להולכי רגל, והתנועה מוסטת לנתיב אחד עד סוף השבוע.'),
  ('dd5b48ea-5879-51af-9a42-0bf3194809c3', 'he', 'general', 'informative', 'גן סאקר: נתיב אחד סגור עד סוף השבוע', 'עבודות החלפת צנרת ומדרכות. הגישה לחניונים ולבתי העסק נשמרת. העבודות מתבצעות בין 07:00 ל־17:00.'),
  ('d279f9c8-b1b0-586b-83e3-907f8f691f00', 'he', 'general', 'calm', 'שיבושים בקווי אוטובוס בתל אביב־יפו עד 12:00', 'בעקבות מחלוקת עבודה אצל אחד המפעילים, חלק מהקווים בתל אביב־יפו לא יפעלו הבוקר עד 12:00. הרכבת והקווים של שאר המפעילים פועלים כרגיל.'),
  ('d279f9c8-b1b0-586b-83e3-907f8f691f00', 'he', 'general', 'human', 'נוסעים בתל אביב־יפו מחפשים דרך אחרת לעבודה', 'בתחנות מתארגנים לנסיעות משותפות ולקורקינטים. "יצאתי חצי שעה מוקדם, זה עובד", מספרת סטודנטית. חלק מהקווים לא יפעלו עד 12:00.'),
  ('d279f9c8-b1b0-586b-83e3-907f8f691f00', 'he', 'general', 'informative', 'תל אביב־יפו: חלק מקווי האוטובוס מושבתים עד 12:00', 'מחלוקת עבודה אצל מפעיל אחד משביתה חלק מהקווים בתל אביב־יפו עד 12:00. רשימת הקווים באפליקציות התחבורה. הרכבת ושאר המפעילים פועלים כסדרם.'),
  ('d279f9c8-b1b0-586b-83e3-907f8f691f00', 'he', 'general', 'light', 'שיבושים בקווי אוטובוס בתל אביב־יפו עד 12:00', 'חלק מהקווים של אחד המפעילים לא יפעלו הבוקר עד 12:00. כדאי לבדוק באפליקציית התחבורה לפני היציאה.'),
  ('d279f9c8-b1b0-586b-83e3-907f8f691f00', 'en', 'general', 'informative', 'Tel Aviv-Yafo: some bus lines halted until 12:00', 'A labour dispute at one operator has stopped some bus lines in Tel Aviv-Yafo until 12:00. Trains and other operators run as usual; check your transit app for the affected lines.'),
  ('d279f9c8-b1b0-586b-83e3-907f8f691f00', 'en', 'general', 'calm', 'Some buses in Tel Aviv-Yafo delayed until 12:00', 'Part of one operator’s lines will not run this morning until 12:00. Trains and other lines are working normally, so most journeys just need a little more time.'),
  ('d279f9c8-b1b0-586b-83e3-907f8f691f00', 'fr', 'general', 'informative', 'Tel-Aviv-Jaffa : des lignes de bus à l’arrêt jusqu’à 12:00', 'Un conflit social chez un opérateur interrompt certaines lignes à Tel-Aviv-Jaffa jusqu’à 12:00. Les trains et les autres opérateurs circulent normalement ; vérifiez votre application de transport.'),
  ('d279f9c8-b1b0-586b-83e3-907f8f691f00', 'fr', 'general', 'calm', 'Perturbations des bus à Tel-Aviv-Jaffa jusqu’à 12:00', 'Une partie des lignes d’un opérateur ne circulera pas ce matin jusqu’à 12:00. Les trains et les autres lignes fonctionnent : prévoyez simplement un peu plus de temps.'),
  ('f051f525-68c8-5463-8fe5-c8701c1d92d8', 'he', 'general', 'calm', 'גשם ראשון בדרך לצפון', 'צפויות טפטופות וממטרים קלים בצפון ובחוף הכרמל מחר בערב. אין צורך בהיערכות מיוחדת, רק מטרייה קרובה.'),
  ('f051f525-68c8-5463-8fe5-c8701c1d92d8', 'he', 'general', 'human', 'בצפון מחכים לגשם הראשון, ובעיקר החקלאים', 'ממטרים קלים צפויים בצפון ובחוף הכרמל מחר בערב. "זה בדיוק מה שהאדמה צריכה אחרי הקיץ", אומר מגדל תפוחים מהאזור.'),
  ('f051f525-68c8-5463-8fe5-c8701c1d92d8', 'he', 'general', 'informative', 'תחזית: ממטרים ראשונים בצפון ובחוף הכרמל מחר בערב', 'ממטרים קלים ומקומיים צפויים בצפון ובחוף הכרמל מחר בערב, עם ירידה של 3–4 מעלות בטמפרטורות. בשאר הארץ יהיה מעונן חלקית.'),
  ('f051f525-68c8-5463-8fe5-c8701c1d92d8', 'he', 'general', 'light', 'הוציאו את המטריות מהבוידעם', 'הגשם הראשון של העונה מגיע בצפון ובחוף הכרמל מחר בערב. לא מבול, אבל מספיק כדי להריח את הסתיו.'),
  ('f051f525-68c8-5463-8fe5-c8701c1d92d8', 'en', 'general', 'informative', 'Forecast: first showers in the north and on the Carmel coast tomorrow evening', 'Light, scattered showers are expected in the north and on the Carmel coast tomorrow evening, with temperatures dropping 3–4°C. The rest of the country will be partly cloudy.'),
  ('f051f525-68c8-5463-8fe5-c8701c1d92d8', 'en', 'general', 'calm', 'The first rain is on its way north', 'Light showers are expected in the north and on the Carmel coast tomorrow evening. No special preparations are needed, just an umbrella nearby.'),
  ('f051f525-68c8-5463-8fe5-c8701c1d92d8', 'fr', 'general', 'informative', 'Prévisions : premières averses dans le Nord et sur la côte du Carmel demain soir', 'Des averses faibles et locales sont attendues dans le Nord et sur la côte du Carmel demain soir, avec une baisse de 3 à 4 °C. Ailleurs, ciel partiellement nuageux.'),
  ('f051f525-68c8-5463-8fe5-c8701c1d92d8', 'fr', 'general', 'calm', 'La première pluie arrive dans le Nord', 'De faibles averses sont prévues dans le Nord et sur la côte du Carmel demain soir. Aucune préparation particulière : gardez simplement un parapluie à portée de main.'),
  ('f051f525-68c8-5463-8fe5-c8701c1d92d8', 'he', 'youth', 'light', 'ריח של סתיו: הגשם הראשון מגיע', 'ממטרים קלים צפויים בצפון ובחוף הכרמל מחר בערב. זה זמן טוב לבדוק איפה המעיל מהשנה שעברה.'),
  ('f051f525-68c8-5463-8fe5-c8701c1d92d8', 'he', 'youth', 'calm', 'גשם ראשון בצפון', 'צפויים ממטרים קלים בצפון ובחוף הכרמל מחר בערב. לא צריך להתכונן במיוחד, רק לקחת מעיל דק.'),
  ('8e8d4146-5632-5886-a882-13b9280cd603', 'he', 'general', 'calm', 'הודעות מזויפות על משלוח חבילה: לא לשלם דרך קישור', 'מתקבלות הודעות SMS שמבקשות תשלום קטן על משלוח חבילה. גופים רשמיים לא מבקשים פרטי אשראי בהודעה. אם יש ספק, נכנסים לאתר הרשמי ישירות.'),
  ('8e8d4146-5632-5886-a882-13b9280cd603', 'he', 'general', 'human', '"כמעט שילמתי 12 שקלים על חבילה שלא הזמנתי"', 'גמלאית מהמרכז קיבלה הודעה על משלוח חבילה ועצרה רגע לפני התשלום. המשטרה מזכירה: לא לוחצים על קישורים בהודעות כאלה.'),
  ('8e8d4146-5632-5886-a882-13b9280cd603', 'he', 'general', 'informative', 'אזהרה: הודעות SMS מתחזות בנושא משלוח חבילה', 'הונאה חוזרת: הודעה עם קישור לתשלום קטן על משלוח חבילה. הקישור מוביל לאתר מתחזה שאוסף פרטי אשראי. מי שמסר פרטים צריך לפנות מיד לחברת האשראי.'),
  ('8e8d4146-5632-5886-a882-13b9280cd603', 'he', 'general', 'light', 'הודעה על משלוח חבילה? קודם נושמים', 'נוכלים שולחים הודעות עם קישור לתשלום קטן על משלוח חבילה. הכלל פשוט: לא לוחצים, נכנסים לבד לאתר הרשמי.'),
  ('8e8d4146-5632-5886-a882-13b9280cd603', 'en', 'general', 'informative', 'Warning: fake text messages about a parcel delivery', 'A recurring scam asks for a small payment for a parcel delivery through a link. The site collects card details. Anyone who entered them should contact their credit card company at once.'),
  ('8e8d4146-5632-5886-a882-13b9280cd603', 'en', 'general', 'calm', 'Don’t pay through links in text messages', 'Some people are receiving messages asking for a small payment for a parcel delivery. Official bodies do not ask for card details by SMS; when in doubt, go to the official website directly.'),
  ('8e8d4146-5632-5886-a882-13b9280cd603', 'fr', 'general', 'informative', 'Alerte : faux SMS concernant la livraison d’un colis', 'Une arnaque récurrente réclame un petit paiement pour la livraison d’un colis via un lien. Le site collecte les données de carte. En cas de saisie, contactez immédiatement votre banque.'),
  ('8e8d4146-5632-5886-a882-13b9280cd603', 'fr', 'general', 'calm', 'Ne payez pas via un lien reçu par SMS', 'Des messages demandent un petit paiement pour la livraison d’un colis. Les organismes officiels ne demandent pas de coordonnées bancaires par SMS ; en cas de doute, allez directement sur le site officiel.'),
  ('8e8d4146-5632-5886-a882-13b9280cd603', 'he', 'youth', 'light', 'קיבלתם הודעה מוזרה עם קישור? אל תלחצו', 'נוכלים שולחים הודעות על משלוח חבילה ומבקשים לשלם. תמיד מראים להורים לפני שלוחצים על משהו.'),
  ('8e8d4146-5632-5886-a882-13b9280cd603', 'he', 'youth', 'calm', 'הודעות מזויפות בטלפון', 'יש הודעות שמבקשות לשלם על משלוח חבילה. לא לוחצים על הקישור ומספרים למבוגר.'),
  ('25eec0a5-f113-5a00-9253-6e9da47d9ffd', 'he', 'general', 'calm', 'גל חום בדרום אירופה; הטיסות פועלות כסדרן', 'מדינות בדרום היבשת מדווחות על ימים חמים במיוחד. לתיירים מישראל אין שינוי בטיסות, ומומלץ לתכנן סיורים לשעות הבוקר והערב.'),
  ('25eec0a5-f113-5a00-9253-6e9da47d9ffd', 'he', 'general', 'human', 'ישראלים בחופשה באירופה מסיירים בבוקר ונחים בצהריים', '"אנחנו יוצאים בשבע ובצהריים במוזיאונים הממוזגים", מספרת משפחה בטיול. דרום אירופה מתמודד עם גל חום, והטיסות פועלות כרגיל.'),
  ('25eec0a5-f113-5a00-9253-6e9da47d9ffd', 'he', 'general', 'informative', 'דרום אירופה: גל חום, עד 40 מעלות בחלק מהערים', 'השירותים המטאורולוגיים במדינות האזור פרסמו אזהרות חום לימים הקרובים. שדות התעופה פועלים כרגיל. אתרי תיירות מסוימים מקצרים שעות פתיחה בצהריים.'),
  ('25eec0a5-f113-5a00-9253-6e9da47d9ffd', 'he', 'general', 'light', 'באירופה חם כמו אצלנו, ואפילו יותר', 'גל חום בדרום היבשת, עם 40 מעלות בחלק מהערים. הטיסות ממריאות כרגיל, והגלידה שם, כך מספרים, עדיין מצוינת.'),
  ('25eec0a5-f113-5a00-9253-6e9da47d9ffd', 'en', 'general', 'informative', 'Southern Europe heatwave: up to 40°C in some cities', 'Weather services in the region have issued heat warnings for the coming days. Airports are operating normally; some tourist sites are shortening midday opening hours.'),
  ('25eec0a5-f113-5a00-9253-6e9da47d9ffd', 'en', 'general', 'calm', 'A heatwave in southern Europe; flights run normally', 'Countries in the south of the continent are seeing very hot days. There are no changes to flights from Israel; it is best to plan sightseeing for mornings and evenings.'),
  ('25eec0a5-f113-5a00-9253-6e9da47d9ffd', 'fr', 'general', 'informative', 'Canicule dans le sud de l’Europe : jusqu’à 40 °C', 'Les services météorologiques de la région ont émis des alertes pour les prochains jours. Les aéroports fonctionnent normalement ; certains sites réduisent leurs horaires à midi.'),
  ('25eec0a5-f113-5a00-9253-6e9da47d9ffd', 'fr', 'general', 'calm', 'Canicule en Europe du Sud, vols normaux', 'Le sud du continent connaît des journées très chaudes. Aucun changement pour les vols depuis Israël ; mieux vaut visiter le matin et le soir.'),
  ('ba0e16f4-9f8e-5e6a-b66a-123b7f04503f', 'he', 'general', 'calm', 'ליגת העל בכדורגל: המחזור השביעי הושלם', 'שלוש הקבוצות המובילות ניצחו, והפער בצמרת נשאר נקודה אחת. המחזור הבא ייערך אחרי החג.'),
  ('ba0e16f4-9f8e-5e6a-b66a-123b7f04503f', 'he', 'general', 'human', 'אוהדים חזרו מהמגרש עם חיוך, ועם צרידות', '"שרנו תשעים דקות, שווה כל רגע", מספר אוהד. במחזור השביעי של ליגת העל ניצחו כל הקבוצות המובילות, והצמרת צפופה.'),
  ('ba0e16f4-9f8e-5e6a-b66a-123b7f04503f', 'he', 'general', 'informative', 'ליגת העל: סיכום המחזור השביעי', 'הקבוצות המובילות ניצחו, והפער בין המקום הראשון לשלישי עומד על נקודה אחת. נכבשו 21 שערים במחזור. המחזור הבא אחרי החג.'),
  ('ba0e16f4-9f8e-5e6a-b66a-123b7f04503f', 'he', 'general', 'light', 'הצמרת צפופה כמו תור לפלאפל', 'במחזור השביעי ניצחו כל המובילות, ורק נקודה אחת מפרידה בין שלוש הראשונות. אחרי החג ממשיכים.'),
  ('b3754213-6502-5206-9f82-501507633046', 'he', 'general', 'calm', 'לוח זמנים חדש לפינוי גזם ופסולת גושית', 'מהשבוע הבא יתבצע הפינוי בגן סאקר פעמיים בשבוע. את לוח הזמנים המלא אפשר למצוא באתר העירייה.'),
  ('b3754213-6502-5206-9f82-501507633046', 'he', 'general', 'informative', 'גן סאקר: פינוי גזם בימים שני וחמישי', 'העירייה מעדכנת את מועדי פינוי הגזם והפסולת הגושית. יש להוציא את הפסולת עד 07:00 בבוקר יום הפינוי.'),
  ('3cd49720-e30f-5d66-950f-6a4eacd84c0b', 'he', 'general', 'calm', 'שיבוש באספקת המים בדרום העיר של ירושלים עד 18:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 18:00. תאגיד המים מציב נקודות חלוקה, והצוותים כבר עובדים בשטח.'),
  ('3cd49720-e30f-5d66-950f-6a4eacd84c0b', 'he', 'general', 'human', 'תושבים בדרום העיר של ירושלים בלי לחץ מים עד 18:00', 'משפחות בכמה שכונות מתארגנות עם בקבוקים ושכנים. "מילאנו סירים מראש, יהיה בסדר", מספרת תושבת. תאגיד המים מציב נקודות חלוקה.'),
  ('3cd49720-e30f-5d66-950f-6a4eacd84c0b', 'he', 'general', 'informative', 'ירושלים: לחץ מים נמוך בדרום העיר עד 18:00', 'תקלה בצנרת ראשית פוגעת באספקת המים בדרום העיר. התיקון צפוי להסתיים עד 18:00. נקודות חלוקת מים פועלות, והפרטים באתר תאגיד המים.'),
  ('3cd49720-e30f-5d66-950f-6a4eacd84c0b', 'he', 'general', 'light', 'שיבוש באספקת המים בדרום העיר של ירושלים עד 18:00', 'בעקבות תקלה בצנרת ראשית צפוי לחץ מים נמוך בכמה שכונות עד 18:00. תאגיד המים מציב נקודות חלוקה ומעדכן באתר.'),
  ('3cd49720-e30f-5d66-950f-6a4eacd84c0b', 'en', 'general', 'informative', 'Jerusalem: low water pressure in the south of the city until 18:00', 'A fault in a main pipe is disrupting the water supply in the south of the city. Repairs are expected to finish by 18:00; the municipal water company has set up distribution points.'),
  ('3cd49720-e30f-5d66-950f-6a4eacd84c0b', 'en', 'general', 'calm', 'Water supply disrupted in parts of Jerusalem until 18:00', 'Following a pipe fault, some neighbourhoods in the south of the city will have low water pressure until 18:00. Crews are on site and water is available at distribution points.'),
  ('3cd49720-e30f-5d66-950f-6a4eacd84c0b', 'fr', 'general', 'informative', 'Jérusalem : faible pression d’eau dans le sud de la ville jusqu’à 18:00', 'Une panne sur une canalisation principale perturbe l’alimentation en eau dans le sud de la ville. La réparation devrait s’achever vers 18:00 ; des points de distribution sont ouverts.'),
  ('3cd49720-e30f-5d66-950f-6a4eacd84c0b', 'fr', 'general', 'calm', 'Perturbation de l’eau à Jérusalem jusqu’à 18:00', 'À la suite d’une panne, certains quartiers dans le sud de la ville auront une pression d’eau faible jusqu’à 18:00. Les équipes sont sur place et des points de distribution sont ouverts.'),
  ('a7fc2eb7-a5b8-5548-ad98-3b7268633b02', 'he', 'general', 'calm', 'פסטיבל סוכות בפארקים של ירושלים, בכניסה חופשית', 'בימי חול המועד יתקיימו הופעות, סדנאות ופעילויות לילדים בפארקים בעיר. אין צורך בהרשמה מראש, ומומלץ להגיע בתחבורה ציבורית.'),
  ('a7fc2eb7-a5b8-5548-ad98-3b7268633b02', 'he', 'general', 'human', 'אמנים מקומיים מכינים את פסטיבל החג בירושלים', '"אנחנו מופיעים בשכונה שבה גדלנו", מספר נגן בלהקה מקומית. בחול המועד יתקיימו הופעות וסדנאות בפארקים, בכניסה חופשית.'),
  ('a7fc2eb7-a5b8-5548-ad98-3b7268633b02', 'he', 'general', 'informative', 'ירושלים: פסטיבל סוכות בפארקים בחול המועד', 'העירייה מפרסמת תוכנייה של הופעות, סדנאות יצירה ופעילויות משפחה בפארקים, בכניסה חופשית. הפעילויות מתקיימות בין 10:00 ל־20:00.'),
  ('a7fc2eb7-a5b8-5548-ad98-3b7268633b02', 'he', 'general', 'light', 'חול המועד בירושלים: פיקניק, מוזיקה וסדנאות', 'הפארקים בעיר מתמלאים בהופעות ובסדנאות לילדים, בכניסה חופשית. מביאים מחצלת, כובע וסבלנות לחניה.'),
  ('a7fc2eb7-a5b8-5548-ad98-3b7268633b02', 'en', 'general', 'informative', 'Jerusalem: free Sukkot festival in the parks', 'The municipality has published a programme of shows, craft workshops and family activities in city parks during the intermediate days of Sukkot, from 10:00 to 20:00. Entry is free.'),
  ('a7fc2eb7-a5b8-5548-ad98-3b7268633b02', 'en', 'general', 'calm', 'A free Sukkot festival in Jerusalem', 'Parks across the city will host shows and children’s workshops during the holiday week. No booking is needed; public transport is recommended.'),
  ('a7fc2eb7-a5b8-5548-ad98-3b7268633b02', 'fr', 'general', 'informative', 'Jérusalem : festival de Souccot gratuit dans les parcs', 'La municipalité propose spectacles, ateliers et activités familiales dans les parcs pendant les demi-fêtes de Souccot, de 10 h à 20 h. Entrée libre.'),
  ('a7fc2eb7-a5b8-5548-ad98-3b7268633b02', 'fr', 'general', 'calm', 'Un festival de Souccot gratuit à Jérusalem', 'Les parcs de la ville accueilleront spectacles et ateliers pour enfants pendant la semaine de fête. Sans réservation ; transports en commun conseillés.'),
  ('a7fc2eb7-a5b8-5548-ad98-3b7268633b02', 'he', 'youth', 'light', 'חול המועד בירושלים: הופעות בפארקים', 'בחופש יהיו בפארקים הופעות, סדנאות ומשחקים, בכניסה חופשית. שווה לתאם עם חברים.'),
  ('a7fc2eb7-a5b8-5548-ad98-3b7268633b02', 'he', 'youth', 'calm', 'פעילויות חג בפארקים של ירושלים', 'בחול המועד יתקיימו הופעות וסדנאות לילדים בפארקים, בלי תשלום.'),
  ('a260bfac-ee02-512b-91ac-c9291acc39db', 'he', 'general', 'calm', 'לקראת החג: כמה כללי בטיחות פשוטים בבניית הסוכה', 'מרחיקים את הסוכה מכבלי חשמל, משתמשים בתאורה שמתאימה לחוץ, ומוודאים שהדפנות יציבות. כך חוגגים בשקט.'),
  ('a260bfac-ee02-512b-91ac-c9291acc39db', 'he', 'general', 'human', 'חשמלאי מתנדב עובר בין הסוכות בשכונה', '"אני בודק כבלים ותאורה, ורוב הזמן מקבל כוס תה", הוא צוחק. כבאות והצלה מזכירים כללי בטיחות פשוטים בבניית הסוכה.'),
  ('a260bfac-ee02-512b-91ac-c9291acc39db', 'he', 'general', 'informative', 'כבאות והצלה: הנחיות בטיחות לבניית סוכה', 'יש להרחיק את הסוכה מכבלי חשמל, להשתמש רק בתאורה המיועדת לשימוש חיצוני, לא להשאיר נרות דולקים בלי השגחה ולחזק את הדפנות מפני רוח.'),
  ('a260bfac-ee02-512b-91ac-c9291acc39db', 'he', 'general', 'light', 'סוכה יפה היא סוכה יציבה', 'שרשראות אור? רק כאלה שמתאימות לחוץ. נרות? רק כשמישהו בבית. ודפנות? שיחזיקו גם כשהשכן סוגר את הדלת בחוזקה.'),
  ('a260bfac-ee02-512b-91ac-c9291acc39db', 'en', 'general', 'informative', 'Fire service: safety tips for building a sukkah', 'Keep the sukkah away from power lines, use only outdoor-rated lighting, never leave candles burning unattended and secure the walls against wind.'),
  ('a260bfac-ee02-512b-91ac-c9291acc39db', 'en', 'general', 'calm', 'A few simple safety rules for your sukkah', 'Keep it clear of power cables, use outdoor lighting and make sure the walls are stable, and the holiday stays relaxed.'),
  ('a260bfac-ee02-512b-91ac-c9291acc39db', 'fr', 'general', 'informative', 'Pompiers : consignes de sécurité pour la souccah', 'Éloigner la souccah des câbles électriques, n’utiliser que des éclairages d’extérieur, ne jamais laisser de bougies sans surveillance et bien fixer les parois contre le vent.'),
  ('a260bfac-ee02-512b-91ac-c9291acc39db', 'fr', 'general', 'calm', 'Quelques règles simples pour la souccah', 'Tenez-la éloignée des câbles, utilisez un éclairage d’extérieur et vérifiez la stabilité des parois : la fête restera sereine.'),
  ('a260bfac-ee02-512b-91ac-c9291acc39db', 'he', 'youth', 'light', 'בונים סוכה? הנה כמה טיפים', 'שרשראות אור רק מתאימות לחוץ, בלי נרות בלי מבוגר, ודפנות שמחזיקות גם ברוח. ואז: קישוטים.'),
  ('a260bfac-ee02-512b-91ac-c9291acc39db', 'he', 'youth', 'calm', 'בטיחות בסוכה', 'מתרחקים מכבלי חשמל, משתמשים בתאורה שמתאימה לחוץ, ולא מדליקים נרות בלי מבוגר.'),
  ('ea723241-df61-5c8a-bca3-516af5fe7155', 'he', 'general', 'calm', 'מחיר הדלק יעלה מעט בתחילת החודש', 'השינוי קטן, כמה אגורות לליטר. אין סיבה לרוץ לתחנה: ההבדל במילוי מיכל ממוצע הוא שקלים בודדים.'),
  ('ea723241-df61-5c8a-bca3-516af5fe7155', 'he', 'general', 'human', 'נהגי מוניות עוקבים אחרי מחיר הדלק', 'בתחילת החודש מחיר הדלק יעלה בכמה אגורות. "כל אגורה מורגשת בסוף החודש", אומר נהג מונית ותיק.'),
  ('ea723241-df61-5c8a-bca3-516af5fe7155', 'he', 'general', 'informative', 'מחיר בנזין 95 יעלה בכמה אגורות לליטר', 'העדכון החודשי נכנס לתוקף בחצות שבין החודשים. השינוי נובע ממחירי הנפט העולמיים ומשער החליפין. המחיר בשירות מלא גבוה יותר.'),
  ('ea723241-df61-5c8a-bca3-516af5fe7155', 'he', 'general', 'light', 'הדלק זז קצת, הכיס כמעט לא מרגיש', 'בתחילת החודש מחיר הבנזין יעלה בכמה אגורות. במיכל מלא מדובר בשקלים בודדים, בערך מחיר של קפה קטן.'),
  ('ea723241-df61-5c8a-bca3-516af5fe7155', 'en', 'general', 'informative', 'Petrol price will rise by a few agorot a litre', 'The monthly update takes effect at midnight at the start of the month and reflects world oil prices and the exchange rate. Full-service prices are higher.'),
  ('ea723241-df61-5c8a-bca3-516af5fe7155', 'en', 'general', 'calm', 'A small change in fuel prices', 'The price of petrol will rise slightly next month, by a few agorot a litre. For a full tank that means just a few shekels.'),
  ('ea723241-df61-5c8a-bca3-516af5fe7155', 'fr', 'general', 'informative', 'Le prix de l’essence augmentera de quelques agorot', 'La mise à jour mensuelle entre en vigueur à minuit en début de mois et suit les cours du pétrole et du change. Le service complet est plus cher.'),
  ('ea723241-df61-5c8a-bca3-516af5fe7155', 'fr', 'general', 'calm', 'Léger changement du prix de l’essence', 'Le prix de l’essence augmentera légèrement le mois prochain, de quelques agorot par litre : quelques shekels pour un plein.'),
  ('83a51b47-1f84-5a4e-85f4-2e1edc86dd6e', 'he', 'general', 'calm', 'שיבושים בקווי אוטובוס בבאר שבע עד 09:30', 'בעקבות מחלוקת עבודה אצל אחד המפעילים, חלק מהקווים בבאר שבע לא יפעלו הבוקר עד 09:30. הרכבת והקווים של שאר המפעילים פועלים כרגיל.'),
  ('83a51b47-1f84-5a4e-85f4-2e1edc86dd6e', 'he', 'general', 'human', 'נוסעים בבאר שבע מחפשים דרך אחרת לעבודה', 'בתחנות מתארגנים לנסיעות משותפות ולקורקינטים. "יצאתי חצי שעה מוקדם, זה עובד", מספרת סטודנטית. חלק מהקווים לא יפעלו עד 09:30.'),
  ('83a51b47-1f84-5a4e-85f4-2e1edc86dd6e', 'he', 'general', 'informative', 'באר שבע: חלק מקווי האוטובוס מושבתים עד 09:30', 'מחלוקת עבודה אצל מפעיל אחד משביתה חלק מהקווים בבאר שבע עד 09:30. רשימת הקווים באפליקציות התחבורה. הרכבת ושאר המפעילים פועלים כסדרם.'),
  ('83a51b47-1f84-5a4e-85f4-2e1edc86dd6e', 'he', 'general', 'light', 'שיבושים בקווי אוטובוס בבאר שבע עד 09:30', 'חלק מהקווים של אחד המפעילים לא יפעלו הבוקר עד 09:30. כדאי לבדוק באפליקציית התחבורה לפני היציאה.'),
  ('a515fca7-6466-564d-a3a2-dad94bd07d29', 'he', 'general', 'calm', 'נבחרת הנוער בכדורעף עלתה לחצי הגמר באליפות אירופה', 'הנבחרת ניצחה אתמול בשני משחקים רצופים. המשחק הבא ישודר בערוצי הספורט, והשחקנים מספרים שהם ממוקדים ורגועים.'),
  ('a515fca7-6466-564d-a3a2-dad94bd07d29', 'he', 'general', 'human', 'ההורים ביציע לא הפסיקו לשיר', 'נבחרת הנוער בכדורעף עלתה לחצי הגמר באליפות אירופה. "הם שיחקו בשביל החברים שלהם בבית", אמר המאמן אחרי הניצחון.'),
  ('a515fca7-6466-564d-a3a2-dad94bd07d29', 'he', 'general', 'informative', 'נבחרת הנוער בכדורעף: עלייה לחצי הגמר באליפות אירופה', 'אחרי שני ניצחונות רצופים הבטיחה הנבחרת את מקומה לחצי הגמר. המשחק הבא בסוף השבוע ישודר בשידור חי.'),
  ('a515fca7-6466-564d-a3a2-dad94bd07d29', 'he', 'general', 'light', 'הנוער שלנו בכדורעף ממשיך לטפס', 'עוד ניצחון, ועוד שלב: נבחרת הנוער בכדורעף עלתה לחצי הגמר באליפות אירופה. הדגלים כבר במרפסות.'),
  ('a515fca7-6466-564d-a3a2-dad94bd07d29', 'en', 'general', 'informative', 'Israel’s youth volleyball team reaches the semi-finals', 'After two consecutive wins, the team has secured its place in the semi-finals of the European championship. The next match, this weekend, will be broadcast live.'),
  ('a515fca7-6466-564d-a3a2-dad94bd07d29', 'en', 'general', 'calm', 'Youth volleyball team advances in Europe', 'Israel’s youth team has reached the semi-finals of the European championship after two wins in a row.'),
  ('a515fca7-6466-564d-a3a2-dad94bd07d29', 'fr', 'general', 'informative', 'L’équipe israélienne junior de volley-ball en les demi-finales', 'Après deux victoires consécutives, l’équipe s’est qualifiée pour les demi-finales du championnat d’Europe. Le prochain match, ce week-end, sera diffusé en direct.'),
  ('a515fca7-6466-564d-a3a2-dad94bd07d29', 'fr', 'general', 'calm', 'L’équipe junior de volley-ball poursuit sa route', 'L’équipe israélienne des jeunes s’est qualifiée pour les demi-finales du championnat d’Europe après deux victoires.'),
  ('a515fca7-6466-564d-a3a2-dad94bd07d29', 'he', 'youth', 'light', 'נבחרת הנוער בכדורעף בדרך למעלה', 'שני ניצחונות ברצף, והנבחרת עלתה לחצי הגמר באליפות אירופה. המשחק הבא בסוף השבוע.'),
  ('a515fca7-6466-564d-a3a2-dad94bd07d29', 'he', 'youth', 'calm', 'הצלחה לנבחרת הנוער בכדורעף', 'הנבחרת עלתה לחצי הגמר באליפות אירופה אחרי שני ניצחונות.'),
  ('6ada1086-7611-55c8-9d9e-8facfd3b5877', 'he', 'general', 'calm', 'תרגיל של פיקוד העורף באזור השפלה: הצופר הוא חלק מהתרגיל', 'מחר בשעה 10:30 יישמע צופר באזור השפלה במסגרת תרגיל מתוכנן. אין צורך לעשות דבר מלבד להמשיך בשגרה. בתי הספר ישתתפו בתרגיל.'),
  ('6ada1086-7611-55c8-9d9e-8facfd3b5877', 'he', 'general', 'human', 'גננות ומורים באזור השפלה מכינים את הילדים לתרגיל', '"הסברנו מראש שזה רק תרגול, והילדים התייחסו לזה כמו למשחק", מספרת גננת. מחר בשעה 10:30 יישמע צופר כחלק מתרגיל מתוכנן.'),
  ('6ada1086-7611-55c8-9d9e-8facfd3b5877', 'he', 'general', 'informative', 'מחר ב־10:30: צופר תרגיל באזור השפלה', 'פיקוד העורף יקיים תרגיל מתוכנן באזור השפלה, כולל הפעלת צופר בשעה 10:30. אין הנחיות מיוחדות לציבור. מוסדות החינוך יתרגלו כניסה למרחב מוגן.'),
  ('6ada1086-7611-55c8-9d9e-8facfd3b5877', 'he', 'general', 'light', 'תרגיל של פיקוד העורף באזור השפלה: הצופר הוא חלק מהתרגיל', 'מחר בשעה 10:30 יישמע צופר במסגרת תרגיל מתוכנן. אין צורך לעשות דבר מלבד להמשיך בשגרה.'),
  ('6ada1086-7611-55c8-9d9e-8facfd3b5877', 'en', 'general', 'informative', 'Home Front Command drill in the Shfela region tomorrow at 10:30', 'The Home Front Command, the army body responsible for civil protection, will hold a planned drill in the Shfela region, including a siren at 10:30. No action is required from the public.'),
  ('6ada1086-7611-55c8-9d9e-8facfd3b5877', 'en', 'general', 'calm', 'The siren tomorrow in the Shfela region is only a drill', 'A siren will sound tomorrow at 10:30 as part of a planned Home Front Command drill. There is nothing to do but carry on with your day.'),
  ('6ada1086-7611-55c8-9d9e-8facfd3b5877', 'fr', 'general', 'informative', 'Exercice du Commandement du front intérieur dans la région de la Shfela demain à 10:30', 'Le Commandement du front intérieur, chargé de la protection civile, organise un exercice dans la région de la Shfela, avec une sirène à 10:30. Aucune consigne particulière pour le public.'),
  ('6ada1086-7611-55c8-9d9e-8facfd3b5877', 'fr', 'general', 'calm', 'La sirène de demain dans la région de la Shfela n’est qu’un exercice', 'Une sirène retentira demain à 10:30 dans le cadre d’un exercice prévu. Il suffit de poursuivre sa journée normalement.'),
  ('9a87ad26-6fc5-5773-a5f4-282a4507d0d5', 'he', 'general', 'calm', 'הכנסת תחזור מהפגרה אחרי החגים', 'מושב החורף ייפתח אחרי סוכות. על סדר היום: תקציב המדינה לשנה הבאה וכמה הצעות חוק בתחומי התחבורה והדיור.'),
  ('9a87ad26-6fc5-5773-a5f4-282a4507d0d5', 'he', 'general', 'human', 'עובדי הכנסת מתכוננים למושב עמוס', 'אחרי פגרה ארוכה, יועצים וצוותי ועדות כבר קובעים דיונים. "הסתיו תמיד הכי עמוס אצלנו", אומרת מזכירת ועדה. במרכז: תקציב המדינה.'),
  ('9a87ad26-6fc5-5773-a5f4-282a4507d0d5', 'he', 'general', 'informative', 'מושב החורף של הכנסת ייפתח אחרי סוכות', 'בראש סדר היום: הצעת התקציב לשנה הבאה, שצריכה לעבור עד סוף השנה האזרחית, והצעות חוק בנושאי תחבורה ציבורית ודיור.'),
  ('9a87ad26-6fc5-5773-a5f4-282a4507d0d5', 'he', 'general', 'light', 'הכנסת חוזרת מהחופש', 'אחרי החגים נפתח מושב החורף, ועל השולחן: התקציב לשנה הבאה ועוד כמה חוקים שמחכים בתור.'),
  ('9a87ad26-6fc5-5773-a5f4-282a4507d0d5', 'en', 'general', 'informative', 'Knesset winter session opens after Sukkot', 'Top of the agenda for Israel’s parliament: next year’s state budget, which must pass by the end of the calendar year, and bills on public transport and housing.'),
  ('9a87ad26-6fc5-5773-a5f4-282a4507d0d5', 'en', 'general', 'calm', 'Parliament returns after the holidays', 'The Knesset’s winter session opens after Sukkot, with the state budget at the centre of its agenda.'),
  ('9a87ad26-6fc5-5773-a5f4-282a4507d0d5', 'fr', 'general', 'informative', 'La session d’hiver de la Knesset s’ouvre après Souccot', 'Au programme du Parlement israélien : le budget de l’État pour l’an prochain, à adopter avant la fin de l’année civile, et des projets de loi sur les transports et le logement.'),
  ('9a87ad26-6fc5-5773-a5f4-282a4507d0d5', 'fr', 'general', 'calm', 'Le Parlement reprend après les fêtes', 'La session d’hiver de la Knesset s’ouvre après Souccot, avec le budget de l’État au cœur de l’agenda.'),
  ('5abb9d39-b32d-5f35-8588-b6682d417970', 'he', 'general', 'calm', 'כביש החוף (2) ייסגר בלילה בין נתניה לחדרה', 'בגלל עבודות גישור כביש החוף (2) ייסגר הלילה בין נתניה לחדרה בין 23:00–05:30. התנועה תופנה לדרכים חלופיות מסומנות, ובבוקר הכביש ייפתח כרגיל.'),
  ('5abb9d39-b32d-5f35-8588-b6682d417970', 'he', 'general', 'human', 'נהגי המשאיות מתכננים מסלול אחר הלילה', 'כביש החוף (2) ייסגר בין נתניה לחדרה בין 23:00–05:30. "נצא שעה מוקדם יותר ונעבור בדרך החלופית", אומר נהג הובלות. בבוקר הכביש ייפתח.'),
  ('5abb9d39-b32d-5f35-8588-b6682d417970', 'he', 'general', 'informative', 'כביש החוף (2) ייסגר בין נתניה לחדרה בין 23:00–05:30', 'סגירה לילית לצורך עבודות גישור. התנועה תופנה לדרכים חלופיות עם שילוט. צפויים עיכובים של 15–20 דקות. הפתיחה לפני שעות העומס של הבוקר.'),
  ('5abb9d39-b32d-5f35-8588-b6682d417970', 'he', 'general', 'light', 'נהגי לילה, שימו לב: עוקפים הלילה', 'כביש החוף (2) ייסגר בין נתניה לחדרה בין 23:00–05:30. השלטים יובילו אתכם בדרך חלופית, והבוקר ייפתח בזמן לפקקים הרגילים.'),
  ('5abb9d39-b32d-5f35-8588-b6682d417970', 'en', 'general', 'informative', 'the coastal highway (Route 2) closed between Netanya and Hadera overnight, 23:00–05:30', 'An overnight closure for bridge works: traffic will be diverted to signposted alternative roads, with delays of 15–20 minutes. The road reopens before the morning rush.'),
  ('5abb9d39-b32d-5f35-8588-b6682d417970', 'en', 'general', 'calm', 'Overnight closure on the coastal highway (Route 2)', 'the coastal highway (Route 2) will close between Netanya and Hadera between 23:00–05:30 for bridge works. Diversions are signposted, and the road reopens as usual in the morning.'),
  ('5abb9d39-b32d-5f35-8588-b6682d417970', 'fr', 'general', 'informative', 'l’autoroute côtière (route 2) fermée entre Netanya et Hadera cette nuit, 23:00–05:30', 'Fermeture nocturne pour travaux sur un pont : déviation balisée, avec 15 à 20 minutes de retard. Réouverture avant les heures de pointe du matin.'),
  ('5abb9d39-b32d-5f35-8588-b6682d417970', 'fr', 'general', 'calm', 'Fermeture de nuit sur l’autoroute côtière (route 2)', 'l’autoroute côtière (route 2) sera fermée entre Netanya et Hadera entre 23:00–05:30 pour des travaux. Les déviations sont indiquées et la route rouvre normalement le matin.'),
  ('bc198dd4-c1c3-53f2-a123-e6c6d58df463', 'he', 'general', 'calm', 'בית משפט: חברת תקשורת תחזיר ללקוחות חיובים כפולים', 'בית המשפט אישר הסדר בתביעה ייצוגית. הלקוחות שחויבו פעמיים יקבלו זיכוי אוטומטי בחשבון הבא, בלי צורך לפנות.'),
  ('bc198dd4-c1c3-53f2-a123-e6c6d58df463', 'he', 'general', 'human', 'לקוחה שגילתה חיוב כפול: "חשבתי שזה רק אצלי"', 'בדיקה שגרתית של דף האשראי הובילה לתביעה ייצוגית. עכשיו אישר בית המשפט הסדר: חברת תקשורת תחזיר את הכסף לכל מי שחויב פעמיים.'),
  ('bc198dd4-c1c3-53f2-a123-e6c6d58df463', 'he', 'general', 'informative', 'הסדר ייצוגי: חברת תקשורת תזכה לקוחות על חיובים כפולים', 'בית המשפט המחוזי אישר את ההסדר. הזיכוי יינתן אוטומטית בחשבון הקרוב. לקוחות לשעבר יקבלו החזר בהעברה בנקאית תוך 90 יום.'),
  ('bc198dd4-c1c3-53f2-a123-e6c6d58df463', 'he', 'general', 'light', 'חויבתם פעמיים? הכסף חוזר', 'בית משפט אישר הסדר שבו חברת תקשורת מחזירה ללקוחות חיובים כפולים. לא צריך לעשות כלום, רק לבדוק את החשבון הבא.'),
  ('bc198dd4-c1c3-53f2-a123-e6c6d58df463', 'en', 'general', 'informative', 'Class action: a telecom company to refund double charges', 'A district court approved the settlement. Current customers will be credited automatically on their next bill; former customers will receive a bank transfer within 90 days.'),
  ('bc198dd4-c1c3-53f2-a123-e6c6d58df463', 'en', 'general', 'calm', 'Refunds for double-charged customers', 'Following a court-approved settlement, a telecom company will refund customers who were charged twice. No action is needed.'),
  ('bc198dd4-c1c3-53f2-a123-e6c6d58df463', 'fr', 'general', 'informative', 'Action collective : un opérateur télécom remboursera les doubles facturations', 'Un tribunal de district a validé l’accord. Les clients actuels seront crédités automatiquement ; les anciens clients recevront un virement sous 90 jours.'),
  ('bc198dd4-c1c3-53f2-a123-e6c6d58df463', 'fr', 'general', 'calm', 'Remboursement des doubles facturations', 'Après un accord validé par le tribunal, un opérateur télécom remboursera les clients facturés deux fois. Aucune démarche n’est nécessaire.'),
  ('b6a8b827-7a28-5cc0-bf54-7d884493dea4', 'he', 'general', 'calm', 'בית משפט: רשת חדרי כושר תחזיר ללקוחות חיובים כפולים', 'בית המשפט אישר הסדר בתביעה ייצוגית. הלקוחות שחויבו פעמיים יקבלו זיכוי אוטומטי בחשבון הבא, בלי צורך לפנות.'),
  ('b6a8b827-7a28-5cc0-bf54-7d884493dea4', 'he', 'general', 'human', 'לקוחה שגילתה חיוב כפול: "חשבתי שזה רק אצלי"', 'בדיקה שגרתית של דף האשראי הובילה לתביעה ייצוגית. עכשיו אישר בית המשפט הסדר: רשת חדרי כושר תחזיר את הכסף לכל מי שחויב פעמיים.'),
  ('b6a8b827-7a28-5cc0-bf54-7d884493dea4', 'he', 'general', 'informative', 'הסדר ייצוגי: רשת חדרי כושר תזכה לקוחות על חיובים כפולים', 'בית המשפט המחוזי אישר את ההסדר. הזיכוי יינתן אוטומטית בחשבון הקרוב. לקוחות לשעבר יקבלו החזר בהעברה בנקאית תוך 90 יום.'),
  ('b6a8b827-7a28-5cc0-bf54-7d884493dea4', 'he', 'general', 'light', 'חויבתם פעמיים? הכסף חוזר', 'בית משפט אישר הסדר שבו רשת חדרי כושר מחזירה ללקוחות חיובים כפולים. לא צריך לעשות כלום, רק לבדוק את החשבון הבא.'),
  ('b6a8b827-7a28-5cc0-bf54-7d884493dea4', 'en', 'general', 'informative', 'Class action: a gym chain to refund double charges', 'A district court approved the settlement. Current customers will be credited automatically on their next bill; former customers will receive a bank transfer within 90 days.'),
  ('b6a8b827-7a28-5cc0-bf54-7d884493dea4', 'en', 'general', 'calm', 'Refunds for double-charged customers', 'Following a court-approved settlement, a gym chain will refund customers who were charged twice. No action is needed.'),
  ('b6a8b827-7a28-5cc0-bf54-7d884493dea4', 'fr', 'general', 'informative', 'Action collective : une chaîne de salles de sport remboursera les doubles facturations', 'Un tribunal de district a validé l’accord. Les clients actuels seront crédités automatiquement ; les anciens clients recevront un virement sous 90 jours.'),
  ('b6a8b827-7a28-5cc0-bf54-7d884493dea4', 'fr', 'general', 'calm', 'Remboursement des doubles facturations', 'Après un accord validé par le tribunal, une chaîne de salles de sport remboursera les clients facturés deux fois. Aucune démarche n’est nécessaire.'),
  ('8d33d808-594f-55a9-858d-a22f35323bcc', 'he', 'general', 'calm', 'עבודות מתוכננות: הפסקת מים לילית בבית שמש', 'בשכונות אחדות בבית שמש לא יהיו מים הלילה בין 23:00–04:00, בשל החלפת צנרת. בבוקר האספקה תחזור כרגיל.'),
  ('8d33d808-594f-55a9-858d-a22f35323bcc', 'he', 'general', 'human', 'תושבי בית שמש ממלאים קומקום לפני השינה', '"שמתי בקבוק ליד המיטה ומילאתי קומקום לקפה של הבוקר", מספר תושב. בשכונות אחדות לא יהיו מים הלילה בין 23:00–04:00.'),
  ('8d33d808-594f-55a9-858d-a22f35323bcc', 'he', 'general', 'informative', 'בית שמש: הפסקת מים מתוכננת בין 23:00–04:00', 'תאגיד המים מחליף צנרת ראשית. ההפסקה הלילה תחול על כמה שכונות, והרשימה המלאה באתר התאגיד. אחרי החידוש ייתכן צבע עכור במים לכמה דקות.'),
  ('8d33d808-594f-55a9-858d-a22f35323bcc', 'he', 'general', 'light', 'מקלחת מוקדמת הערב, תושבי בית שמש', 'בשכונות אחדות לא יהיו מים הלילה בין 23:00–04:00, כי מחליפים צנרת. ממלאים קומקום, והבוקר הכל זורם.'),
  ('06a352c1-073c-5053-9f3d-e7f16fa95e16', 'he', 'general', 'calm', 'חניה חינם בחניונים העירוניים בחול המועד', 'העירייה מודיעה על חניה ללא תשלום בחניונים העירוניים בימי חול המועד, כדי להקל על המבקרים ברחוב יפו.'),
  ('06a352c1-073c-5053-9f3d-e7f16fa95e16', 'he', 'general', 'informative', 'חול המועד: חניה חינם בחניונים העירוניים', 'ההקלה תחול בכל ימי חול המועד בחניונים העירוניים, כולל באזור רחוב יפו. בחניונים הפרטיים המחירים לא משתנים.'),
  ('111c3895-4eeb-5c28-9083-961a0ab3316f', 'he', 'general', 'calm', 'חניה חינם בחניונים העירוניים בחול המועד', 'העירייה מודיעה על חניה ללא תשלום בחניונים העירוניים בימי חול המועד, כדי להקל על המבקרים בפארק המסילה.'),
  ('111c3895-4eeb-5c28-9083-961a0ab3316f', 'he', 'general', 'informative', 'חול המועד: חניה חינם בחניונים העירוניים', 'ההקלה תחול בכל ימי חול המועד בחניונים העירוניים, כולל באזור פארק המסילה. בחניונים הפרטיים המחירים לא משתנים.'),
  ('a4b711f8-aadf-59fb-a9f8-aad1cf048acb', 'he', 'general', 'calm', 'הפסקת חשמל יזומה באשקלון ביום שני בבוקר', 'חברת החשמל תבצע עבודות תחזוקה בכמה רחובות באשקלון בין 08:00–11:00. הלקוחות ברחובות האלה קיבלו הודעה, והזרם יחזור בסיום העבודות.'),
  ('a4b711f8-aadf-59fb-a9f8-aad1cf048acb', 'he', 'general', 'human', 'עסקים קטנים באשקלון נערכים לבוקר בלי חשמל', '"נפתח שעתיים אחר כך, זה בסדר", אומרת בעלת בית קפה. חברת החשמל תבצע ביום שני עבודות תחזוקה בכמה רחובות בין 08:00–11:00.'),
  ('a4b711f8-aadf-59fb-a9f8-aad1cf048acb', 'he', 'general', 'informative', 'אשקלון: הפסקת חשמל מתוכננת ביום שני בין 08:00–11:00', 'העבודות נועדו לשדרג את רשת החשמל לקראת החורף. רשימת הרחובות באתר חברת החשמל. מומלץ לנתק מכשירים רגישים לפני ההפסקה.'),
  ('a4b711f8-aadf-59fb-a9f8-aad1cf048acb', 'he', 'general', 'light', 'ביום שני בבוקר: קפה בחוץ, תושבי אשקלון', 'חברת החשמל משדרגת את הרשת בכמה רחובות בין 08:00–11:00. מנתקים מחשבים רגישים, ובצהריים הכל דולק שוב.'),
  ('e37be3ff-edae-56a4-914c-a8421fd154cb', 'he', 'general', 'calm', 'גלים גבוהים בסוף השבוע: הרחצה בחופים אסורה', 'הים סוער, והמצילים לא יאפשרו כניסה למים. אפשר ליהנות מהחוף מבחוץ, ומחר צפוי שיפור.'),
  ('e37be3ff-edae-56a4-914c-a8421fd154cb', 'he', 'general', 'human', 'מציל ותיק: "גם שחיינים טובים לא נכנסים היום"', 'הים סוער בסוף השבוע, והרחצה בחופים אסורה. "אנחנו על הכיסאות, אבל לא נותנים להיכנס", הוא אומר.'),
  ('e37be3ff-edae-56a4-914c-a8421fd154cb', 'he', 'general', 'informative', 'בסוף השבוע: גובה גלים 2–3 מטרים, איסור רחצה', 'רשות הספנות והנמלים מדווחת על ים גבוה. הרחצה אסורה בכל החופים, והמעגנות סגורות לכלי שיט קטנים.'),
  ('e37be3ff-edae-56a4-914c-a8421fd154cb', 'he', 'general', 'light', 'הים עושה גלים, אנחנו נשארים על החול', 'גלים של 2–3 מטרים בסוף השבוע, והרחצה אסורה. תביאו ספר, תשאירו את הגלשן בבית.'),
  ('fa637969-e5c5-55d7-ac69-dc936a34b9a5', 'he', 'general', 'calm', 'כביש 6 ייסגר בלילה בין מחלף עירון למחלף עין תות', 'בגלל עבודות גישור כביש 6 ייסגר הלילה בין מחלף עירון למחלף עין תות בין 23:00–05:00. התנועה תופנה לדרכים חלופיות מסומנות, ובבוקר הכביש ייפתח כרגיל.'),
  ('fa637969-e5c5-55d7-ac69-dc936a34b9a5', 'he', 'general', 'human', 'נהגי המשאיות מתכננים מסלול אחר הלילה', 'כביש 6 ייסגר בין מחלף עירון למחלף עין תות בין 23:00–05:00. "נצא שעה מוקדם יותר ונעבור בדרך החלופית", אומר נהג הובלות. בבוקר הכביש ייפתח.'),
  ('fa637969-e5c5-55d7-ac69-dc936a34b9a5', 'he', 'general', 'informative', 'כביש 6 ייסגר בין מחלף עירון למחלף עין תות בין 23:00–05:00', 'סגירה לילית לצורך עבודות גישור. התנועה תופנה לדרכים חלופיות עם שילוט. צפויים עיכובים של 15–20 דקות. הפתיחה לפני שעות העומס של הבוקר.'),
  ('fa637969-e5c5-55d7-ac69-dc936a34b9a5', 'he', 'general', 'light', 'נהגי לילה, שימו לב: עוקפים הלילה', 'כביש 6 ייסגר בין מחלף עירון למחלף עין תות בין 23:00–05:00. השלטים יובילו אתכם בדרך חלופית, והבוקר ייפתח בזמן לפקקים הרגילים.'),
  ('98b59349-b41e-5e19-a831-a38dd0279c64', 'he', 'general', 'calm', 'חם מהרגיל היום, ובערב נעים יותר', 'הטמפרטורות יגיעו לכ־35 מעלות בעמקים ובגליל התחתון. מספיק לשתות מים ולהישאר בצל בשעות הצהריים. בערב צפויה הקלה.'),
  ('98b59349-b41e-5e19-a831-a38dd0279c64', 'he', 'general', 'human', 'מי שעובד בחוץ ירגיש את החום היום', 'פועלי בניין, שליחים וחקלאים בעמקים ובגליל התחתון יפגשו כ־35 מעלות. "אנחנו מתחילים מוקדם ומסיימים לפני הצהריים", מספר מנהל עבודה. בערב צפויה הקלה.'),
  ('98b59349-b41e-5e19-a831-a38dd0279c64', 'he', 'general', 'informative', '35 מעלות בעמקים ובגליל התחתון היום, הקלה בערב', 'עומס חום בינוני בעמקים ובגליל התחתון: עד 35 מעלות בשעות הצהריים. משרד הבריאות ממליץ לשתות באופן קבוע ולהימנע ממאמץ בשמש בין 11:00 ל־16:00.'),
  ('98b59349-b41e-5e19-a831-a38dd0279c64', 'he', 'general', 'light', 'הכובע והבקבוק חוזרים לתיק', 'היום יהיה חם, עד 35 מעלות בעמקים ובגליל התחתון. מים קרים, צל טוב ומזגן בטמפרטורה סבירה, והערב כבר יהיה נעים יותר.'),
  ('df43a8b5-bd99-54e5-a2b0-c7b0c540aa96', 'he', 'general', 'calm', 'עבודות תחזוקה ברכבת בין באר שבע לתל אביב בלילה שבין שני לשלישי', 'הרכבות בין באר שבע לתל אביב לא יפעלו בלילה שבין שני לשלישי אחרי 22:00. יופעלו אוטובוסים חלופיים מהתחנות, ובבוקר התנועה תחזור לשגרה.'),
  ('df43a8b5-bd99-54e5-a2b0-c7b0c540aa96', 'he', 'general', 'human', 'נוסעי הלילה בין באר שבע לתל אביב יעברו לאוטובוסים', 'מי שחוזר מאוחר מהעבודה יצטרך לתכנן מחדש בלילה שבין שני לשלישי. "העיקר שיש הסעה חלופית", אומר נוסע קבוע. הרכבות יחזרו לפעול בבוקר.'),
  ('df43a8b5-bd99-54e5-a2b0-c7b0c540aa96', 'he', 'general', 'informative', 'הרכבת בין באר שבע לתל אביב: הפסקת תנועה בלילה שבין שני לשלישי מ־22:00', 'בשל עבודות תחזוקה לא יפעלו רכבות בין באר שבע לתל אביב בלילה שבין שני לשלישי מ־22:00 ועד תחילת השירות בבוקר. אוטובוסים חלופיים ייצאו מהתחנות כל 20 דקות.'),
  ('df43a8b5-bd99-54e5-a2b0-c7b0c540aa96', 'he', 'general', 'light', 'הרכבת לוקחת כמה לילות לטיפוח', 'עבודות תחזוקה בין באר שבע לתל אביב בלילה שבין שני לשלישי: אחרי 22:00 עוברים לאוטובוסים החלופיים. בבוקר הכל חוזר למסלול.'),
  ('1930cc81-e6b5-50e2-ab1e-c818db3e06fd', 'he', 'general', 'calm', 'כביש 65 ייסגר בלילה בין עפולה לצומת גולני', 'בגלל עבודות גישור כביש 65 ייסגר הלילה בין עפולה לצומת גולני בין 22:00–04:00. התנועה תופנה לדרכים חלופיות מסומנות, ובבוקר הכביש ייפתח כרגיל.'),
  ('1930cc81-e6b5-50e2-ab1e-c818db3e06fd', 'he', 'general', 'human', 'נהגי המשאיות מתכננים מסלול אחר הלילה', 'כביש 65 ייסגר בין עפולה לצומת גולני בין 22:00–04:00. "נצא שעה מוקדם יותר ונעבור בדרך החלופית", אומר נהג הובלות. בבוקר הכביש ייפתח.'),
  ('1930cc81-e6b5-50e2-ab1e-c818db3e06fd', 'he', 'general', 'informative', 'כביש 65 ייסגר בין עפולה לצומת גולני בין 22:00–04:00', 'סגירה לילית לצורך עבודות גישור. התנועה תופנה לדרכים חלופיות עם שילוט. צפויים עיכובים של 15–20 דקות. הפתיחה לפני שעות העומס של הבוקר.'),
  ('1930cc81-e6b5-50e2-ab1e-c818db3e06fd', 'he', 'general', 'light', 'נהגי לילה, שימו לב: עוקפים הלילה', 'כביש 65 ייסגר בין עפולה לצומת גולני בין 22:00–04:00. השלטים יובילו אתכם בדרך חלופית, והבוקר ייפתח בזמן לפקקים הרגילים.'),
  ('c90a0865-bbd7-599e-a7ad-0050b9be798f', 'he', 'general', 'calm', 'לילות קרירים יותר בימים הקרובים', 'הטמפרטורות בלילה יירדו בכמה מעלות, בעיקר בהרים. ביום יהיה נעים עד חם, ללא שינוי מיוחד.'),
  ('c90a0865-bbd7-599e-a7ad-0050b9be798f', 'he', 'general', 'human', 'בירושלים כבר מוציאים שמיכה דקה', '"בלילה פתחתי חלון והרגשתי את הסתיו", מספר תושב. בימים הקרובים הלילות יהיו קרירים יותר, בעיקר בהרים.'),
  ('c90a0865-bbd7-599e-a7ad-0050b9be798f', 'he', 'general', 'informative', 'תחזית: ירידה בטמפרטורות הלילה בימים הקרובים', 'בהרים ירדו הטמפרטורות בלילה ל־16–18 מעלות, ובמישור החוף ל־21–23. ביום: נאה עד חם. אין צפי לגשם.'),
  ('c90a0865-bbd7-599e-a7ad-0050b9be798f', 'he', 'general', 'light', 'הסתיו שולח הודעה ראשונה', 'בימים הקרובים הלילות יהיו קרירים יותר, בעיקר בהרים. זה הרגע להוציא את השמיכה הדקה מהארון.'),
  ('72ff8127-68f7-5c58-a46b-c7b878ecda1c', 'he', 'general', 'calm', 'עומס חום כבד היום: להישאר בצל בשעות הצהריים', 'עד 18:00 צפוי עומס חום כבד ברוב אזורי הארץ. משרד הבריאות ממליץ להימנע משהייה בשמש ומפעילות גופנית בין 11:00 ל־16:00, ולשתות גם בלי תחושת צמא.'),
  ('72ff8127-68f7-5c58-a46b-c7b878ecda1c', 'he', 'general', 'human', 'ביום חם במיוחד, כדאי לבדוק מה שלום השכנים המבוגרים', 'עומס חום כבד צפוי עד 18:00. מתנדבים בכמה ערים כבר מתקשרים לקשישים שגרים לבד. משרד הבריאות ממליץ להישאר בצל ולשתות הרבה.'),
  ('72ff8127-68f7-5c58-a46b-c7b878ecda1c', 'he', 'general', 'informative', 'עומס חום כבד עד 18:00: הנחיות משרד הבריאות', 'צפויות טמפרטורות של 38–40 מעלות בפנים הארץ. ההנחיות: להימנע מפעילות בחוץ בין 11:00 ל־16:00, לשתות באופן קבוע, לא להשאיר ילדים או בעלי חיים ברכב.'),
  ('72ff8127-68f7-5c58-a46b-c7b878ecda1c', 'he', 'general', 'light', 'עומס חום כבד היום: להישאר בצל בשעות הצהריים', 'עד 18:00 צפוי עומס חום כבד. משרד הבריאות ממליץ להימנע מפעילות בשמש בין 11:00 ל־16:00 ולשתות הרבה.'),
  ('72ff8127-68f7-5c58-a46b-c7b878ecda1c', 'en', 'general', 'informative', 'Severe heat until 18:00: Health Ministry guidance', 'Temperatures of 38–40°C are expected inland. Avoid outdoor activity between 11:00 and 16:00, drink regularly, and never leave children or pets in a car.'),
  ('72ff8127-68f7-5c58-a46b-c7b878ecda1c', 'en', 'general', 'calm', 'Severe heat today: stay in the shade at midday', 'Heavy heat is expected across most of the country until 18:00. Stay out of the sun between 11:00 and 16:00 and drink even when not thirsty.'),
  ('72ff8127-68f7-5c58-a46b-c7b878ecda1c', 'fr', 'general', 'informative', 'Forte chaleur jusqu’à 18 h : consignes du ministère de la Santé', 'Des températures de 38 à 40 °C sont attendues à l’intérieur du pays. Évitez les activités en extérieur entre 11 h et 16 h, buvez régulièrement et ne laissez jamais d’enfant ou d’animal dans une voiture.'),
  ('72ff8127-68f7-5c58-a46b-c7b878ecda1c', 'fr', 'general', 'calm', 'Forte chaleur aujourd’hui : restez à l’ombre à midi', 'Une forte chaleur est attendue sur la majeure partie du pays jusqu’à 18 h. Évitez le soleil entre 11 h et 16 h et buvez sans attendre la soif.');
