  ('c097dc4e-14de-590d-bb06-d014f15b0231', 'sample-ad-farm-box-fr', 'Panier de la ferme', 'Des légumes frais de la vallée, livrés chaque semaine. 10 % de remise sur le premier panier.', 'https://example.com/sample-farm-box', 'fr', 'general', '2026-08-26T10:20:48.001586+00:00', '2026-12-24T11:20:48.001586+00:00', 1, true);
